def _campo_configuracao_modulo(
    chave: str,
    nome: str,
    tipo: str = "texto",
    padrao: Any = "",
    *,
    secao: str = "Regras gerais",
    ajuda: str = "",
    opcoes: tuple[tuple[str, str], ...] = (),
    minimo: float | None = None,
    maximo: float | None = None,
) -> dict[str, Any]:
    return {
        "chave": chave,
        "nome": nome,
        "tipo": tipo,
        "padrao": padrao,
        "secao": secao,
        "ajuda": ajuda,
        "opcoes": [{"valor": valor, "nome": rotulo} for valor, rotulo in opcoes],
        "minimo": minimo,
        "maximo": maximo,
    }


