def normalizar_modulos_empresa(valor: Any) -> dict[str, bool]:
    modulos = dict(GESTFLOW_MODULOS_PADRAO)

    if not valor:
        return modulos

    try:
        dados = json.loads(str(valor))
    except (TypeError, ValueError, json.JSONDecodeError):
        return modulos

    if isinstance(dados, dict):
        for codigo in GESTFLOW_MODULOS_CODIGOS:
            modulos[codigo] = bool(dados.get(codigo, True))
    elif isinstance(dados, list):
        ativos = {str(item) for item in dados}
        for codigo in GESTFLOW_MODULOS_CODIGOS:
            modulos[codigo] = codigo in ativos

    return modulos


def serializar_modulos_empresa(modulos: dict[str, bool]) -> str:
    normalizado = {codigo: bool(modulos.get(codigo, True)) for codigo in sorted(GESTFLOW_MODULOS_CODIGOS)}
    return json.dumps(normalizado, ensure_ascii=False, sort_keys=True)


def buscar_modulos_empresa(empresa_id: int | None = None) -> dict[str, bool]:
    empresa = int(empresa_id or empresa_logada_id())

    try:
        with conectar_db() as conn:
            row = conn.execute(
                """
                SELECT modulos_ativos
                FROM empresas
                WHERE id = ?
                LIMIT 1
                """,
                (empresa,),
            ).fetchone()
    except sqlite3.Error:
        return dict(GESTFLOW_MODULOS_PADRAO)

    if row is None:
        return dict(GESTFLOW_MODULOS_PADRAO)

    return normalizar_modulos_empresa(row["modulos_ativos"])


def modulo_empresa_ativo(codigo: str) -> bool:
    codigo_normalizado = str(codigo or "").strip()

    if not codigo_normalizado:
        return True

    return bool(buscar_modulos_empresa().get(codigo_normalizado, True))


def salvar_modulos_empresa(codigos_ativos: list[str]) -> None:
    empresa_id = empresa_logada_id()
    ativos = {str(codigo or "").strip() for codigo in codigos_ativos}
    modulos = {codigo: codigo in ativos for codigo in GESTFLOW_MODULOS_CODIGOS}

    with conectar_db() as conn:
        conn.execute(
            """
            UPDATE empresas
            SET modulos_ativos = ?
            WHERE id = ?
            """,
            (serializar_modulos_empresa(modulos), empresa_id),
        )
        conn.commit()



def obter_segmento_onboarding(codigo: Any) -> dict[str, str]:
    codigo_normalizado = str(codigo or "").strip()
    return GESTFLOW_SEGMENTOS_POR_CODIGO.get(codigo_normalizado, GESTFLOW_SEGMENTOS_POR_CODIGO["outro"])


def sugerir_modulos_por_anamnese(dados: dict[str, Any]) -> dict[str, bool]:
    segmento = obter_segmento_onboarding(dados.get("segmento"))
    perfil = str(dados.get("perfil") or segmento.get("perfil") or "completo").strip()
    nivel = str(dados.get("nivel") or "intermediario").strip()
    operacao = {str(item or "").strip() for item in dados.get("operacao", []) if str(item or "").strip()}
    comercial = {str(item or "").strip() for item in dados.get("comercial", []) if str(item or "").strip()}
    execucao = {str(item or "").strip() for item in dados.get("execucao", []) if str(item or "").strip()}
    estoque = {str(item or "").strip() for item in dados.get("estoque", []) if str(item or "").strip()}
    financeiro = {str(item or "").strip() for item in dados.get("financeiro", []) if str(item or "").strip()}
    cadastros = {str(item or "").strip() for item in dados.get("cadastros", []) if str(item or "").strip()}

    if nivel == "completo":
        ativos = set(GESTFLOW_MODULOS_CODIGOS)
    else:
        ativos = set(GESTFLOW_PERFIS_MODULOS.get(perfil, GESTFLOW_PERFIS_MODULOS["completo"]))

    if "produtos" in operacao or "balcao" in operacao or "estoque" in operacao:
        ativos.update({"clientes", "produtos", "vendas", "estoque"})
    if "servicos" in operacao:
        ativos.update({"clientes", "servicos", "orcamentos", "contratos", "agendamentos"})
    if "balcao" in operacao:
        ativos.update({"pdv", "devolucoes"})
    if "equipe_externa" in operacao or "ordem_servico" in operacao:
        ativos.update({"clientes", "funcionarios", "equipamentos", "servicos", "ordens_servico", "registro_ponto"})
    if "projetos_obras" in operacao:
        ativos.update({"clientes", "fornecedores", "funcionarios", "produtos", "servicos", "orcamentos", "gerador_orcamentos", "contratos", "ordens_servico", "financeiro", "registro_ponto"})

    if "orcamento" in comercial:
        ativos.update({"clientes", "orcamentos", "contratos"})
    if "gerador" in comercial:
        ativos.update({"clientes", "orcamentos", "gerador_orcamentos", "contratos", "produtos", "servicos", "funcionarios"})
    if "venda_direta" in comercial:
        ativos.update({"clientes", "vendas"})
    if "whatsapp" in comercial:
        ativos.update({"clientes", "vendas", "vitrine"})

    if "os_simples" in execucao or "os_completa" in execucao:
        ativos.update({"clientes", "equipamentos", "servicos", "ordens_servico", "registro_ponto"})
    if "campo" in execucao or "fotos" in execucao or "acompanhamento" in execucao:
        ativos.update({"clientes", "funcionarios", "equipamentos", "servicos", "ordens_servico", "painel_os"})

    if "estoque_simples" in estoque or "estoque_completo" in estoque:
        ativos.update({"produtos", "estoque"})
    if financeiro and "sem_financeiro" not in financeiro:
        ativos.add("financeiro")

    mapa_cadastros = {
        "clientes": "clientes",
        "fornecedores": "fornecedores",
        "funcionarios": "funcionarios",
        "equipamentos": "equipamentos",
        "produtos": "produtos",
        "servicos": "servicos",
    }
    for item in cadastros:
        if item in mapa_cadastros:
            ativos.add(mapa_cadastros[item])

    if nivel == "simples":
        if "gerador" not in comercial:
            ativos.discard("gerador_orcamentos")
        if not ({"campo", "fotos", "acompanhamento"} & execucao):
            ativos.discard("painel_os")
        if "orcamento" not in comercial and "servicos" not in operacao:
            ativos.discard("orcamentos")
        if "ordem_servico" not in operacao and not execucao:
            ativos.discard("ordens_servico")
        if "funcionarios" not in cadastros and "equipe_externa" not in operacao and not ({"campo", "fotos", "acompanhamento"} & execucao):
            ativos.discard("funcionarios")
            ativos.discard("registro_ponto")

    if "produtos" in ativos:
        ativos.add("clientes")
    if "pdv" in ativos:
        ativos.update({"produtos", "vendas"})
    if "devolucoes" in ativos:
        ativos.add("vendas")
    if "vitrine" in ativos:
        ativos.update({"clientes", "produtos", "vendas"})
    if "gerador_orcamentos" in ativos:
        ativos.add("orcamentos")
    if "contratos" in ativos:
        ativos.add("clientes")
    if "painel_os" in ativos:
        ativos.add("ordens_servico")
    if "estoque" in ativos:
        ativos.add("produtos")
    if "agendamentos" in ativos:
        ativos.update({"clientes", "servicos"})
    if "ordens_servico" in ativos:
        ativos.add("equipamentos")
    if "registro_ponto" in ativos:
        ativos.add("funcionarios")

    return {codigo: codigo in ativos for codigo in GESTFLOW_MODULOS_CODIGOS}


def montar_onboarding_formulario() -> dict[str, Any]:
    segmento = (request.form.get("segmento") or request.form.get("ramo") or "").strip() or "outro"
    segmento_info = obter_segmento_onboarding(segmento)
    nivel = (request.form.get("nivel") or "intermediario").strip()

    if nivel not in GESTFLOW_NIVEIS_ONBOARDING:
        nivel = "intermediario"

    dados = {
        "segmento": segmento,
        "segmento_nome": segmento_info["nome"],
        "perfil": segmento_info["perfil"],
        "nivel": nivel,
        "operacao": [item.strip() for item in request.form.getlist("operacao") if item.strip()],
        "comercial": [item.strip() for item in request.form.getlist("comercial") if item.strip()],
        "execucao": [item.strip() for item in request.form.getlist("execucao") if item.strip()],
        "estoque": [item.strip() for item in request.form.getlist("estoque") if item.strip()],
        "financeiro": [item.strip() for item in request.form.getlist("financeiro") if item.strip()],
        "cadastros": [item.strip() for item in request.form.getlist("cadastros") if item.strip()],
        "objetivos": [item.strip() for item in request.form.getlist("objetivos") if item.strip()],
        "ferramenta_atual": (request.form.get("ferramenta_atual") or "").strip(),
        "canal_contato": (request.form.get("canal_contato") or "").strip(),
        "usar_configuracao_completa": (request.form.get("usar_configuracao_completa") or "").strip() == "sim",
    }

    if dados["usar_configuracao_completa"]:
        dados["perfil"] = "completo"
        dados["nivel"] = "completo"
        dados["modulos"] = dict(GESTFLOW_MODULOS_PADRAO)
    else:
        dados["modulos"] = sugerir_modulos_por_anamnese(dados)

    return dados


def empresa_precisa_onboarding() -> bool:
    if not session.get("usuario_id"):
        return False

    empresa = buscar_onboarding_empresa()
    onboarding_modulos = str(empresa.get("onboarding_modulos_concluido") or "nao").strip().lower()
    onboarding_basico = str(empresa.get("onboarding_concluido") or "nao").strip().lower()

    return onboarding_modulos != "sim" or onboarding_basico != "sim"



def modulo_por_rota(path: str) -> str:
    caminho = str(path or "").strip()

    if caminho == "/":
        return "dashboard"

    regras = [
        ("/orcamentos/gerador", "gerador_orcamentos"),
        ("/orcamentos", "orcamentos"),
        ("/contratos", "contratos"),
        ("/vendas/balcao", "pdv"),
        ("/vendas/devolucoes", "devolucoes"),
        ("/vendas", "vendas"),
        ("/vitrine", "vitrine"),
        ("/ordens-servico/painel", "painel_os"),
        ("/ordens-servico", "ordens_servico"),
        ("/clientes", "clientes"),
        ("/fornecedores", "fornecedores"),
        ("/funcionarios", "funcionarios"),
        ("/equipamentos", "equipamentos"),
        ("/produtos", "produtos"),
        ("/servicos", "servicos"),
        ("/estoque", "estoque"),
        ("/financeiro", "financeiro"),
        ("/emprestimos", "emprestimos"),
        ("/agendamentos", "agendamentos"),
        ("/registro-ponto", "registro_ponto"),
        ("/gestao-atividades", "gestao_atividades"),
        ("/configuracoes", "configuracoes"),
        ("/admin", "admin"),
    ]

    for prefixo, codigo in regras:
        if caminho == prefixo or caminho.startswith(f"{prefixo}/"):
            return codigo

    return ""


def _twiml_message(text: str) -> str:
    safe = html.escape(text or "")
    return f'<?xml version="1.0" encoding="UTF-8"?><Response><Message>{safe}</Message></Response>'


def conectar_db() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def _variavel_ambiente_whatsapp(nome: str) -> str:
    return str(os.getenv(nome, "") or "").strip()


def _inteiro_ambiente_whatsapp(nome: str) -> int | None:
    valor = _variavel_ambiente_whatsapp(nome)
    if not valor:
        return None
    try:
        inteiro = int(valor)
    except (TypeError, ValueError):
        return None
    return inteiro if inteiro > 0 else None


def _assinatura_whatsapp_valida(corpo_bruto: bytes, assinatura_recebida: str) -> tuple[bool, str]:
    segredo_app = _variavel_ambiente_whatsapp("META_APP_SECRET")
    if not segredo_app:
        return False, "META_APP_SECRET não configurado."

    assinatura = str(assinatura_recebida or "").strip()
    if not assinatura.startswith("sha256="):
        return False, "Cabeçalho X-Hub-Signature-256 ausente ou inválido."

    assinatura_esperada = "sha256=" + hmac.new(
        segredo_app.encode("utf-8"),
        corpo_bruto,
        hashlib.sha256,
    ).hexdigest()

    if not hmac.compare_digest(assinatura_esperada, assinatura):
        return False, "Assinatura do webhook não confere."

    return True, ""


def _json_canonico_whatsapp(valor: Any) -> str:
    return json.dumps(
        valor,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )


def _versao_graph_whatsapp() -> str:
    versao = _variavel_ambiente_whatsapp("WHATSAPP_GRAPH_API_VERSION") or "v25.0"
    return versao if re.fullmatch(r"v\d+\.\d+", versao) else "v25.0"


def _normalizar_destinatario_whatsapp(destinatario: Any) -> tuple[str, str]:
    digitos = re.sub(r"\D", "", str(destinatario or ""))
    if digitos.startswith("00"):
        digitos = digitos[2:]
    if digitos.startswith("0") and len(digitos) in {11, 12}:
        digitos = digitos[1:]
    if len(digitos) in {10, 11}:
        digitos = f"55{digitos}"
    if not 10 <= len(digitos) <= 15:
        return "", "Número de WhatsApp inválido. Informe DDI, DDD e telefone."
    return digitos, ""


def _configuracao_envio_whatsapp() -> tuple[str, str, str]:
    token = _variavel_ambiente_whatsapp("WHATSAPP_ACCESS_TOKEN")
    phone_number_id = _variavel_ambiente_whatsapp("WHATSAPP_PHONE_NUMBER_ID")
    if not token:
        return "", "", "WHATSAPP_ACCESS_TOKEN não está configurado."
    if not phone_number_id:
        return "", "", "WHATSAPP_PHONE_NUMBER_ID não está configurado."
    endpoint = f"https://graph.facebook.com/{_versao_graph_whatsapp()}/{phone_number_id}/messages"
    return token, endpoint, ""


def _mensagem_erro_graph_whatsapp(payload: Any, status_http: int | None = None) -> str:
    if isinstance(payload, dict):
        erro = payload.get("error") or {}
        if isinstance(erro, dict):
            mensagem = str(erro.get("message") or "").strip()
            codigo = str(erro.get("code") or "").strip()
            subcodigo = str(erro.get("error_subcode") or "").strip()
            partes = [parte for parte in (mensagem, f"código {codigo}" if codigo else "", f"subcódigo {subcodigo}" if subcodigo else "") if parte]
            if partes:
                return " | ".join(partes)
    return f"A API do WhatsApp retornou HTTP {status_http}." if status_http else "A API do WhatsApp recusou a solicitação."


def _registrar_envio_whatsapp(
    *,
    destinatario: str,
    tipo: str,
    texto: str,
    payload_enviado: dict[str, Any],
    resposta_api: dict[str, Any],
    sucesso: bool,
    erro: str = "",
) -> None:
    phone_number_id = _variavel_ambiente_whatsapp("WHATSAPP_PHONE_NUMBER_ID")
    waba_id = _variavel_ambiente_whatsapp("WHATSAPP_WABA_ID")
    message_id = ""
    mensagens = resposta_api.get("messages") if isinstance(resposta_api, dict) else None
    if isinstance(mensagens, list) and mensagens and isinstance(mensagens[0], dict):
        message_id = str(mensagens[0].get("id") or "").strip()

    agora = datetime.now(ZoneInfo("UTC")).isoformat(timespec="seconds")
    evento_payload = {"request": payload_enviado, "response": resposta_api}
    event_key = f"outbound:{message_id or secrets.token_hex(16)}"
    request_hash = _hash_whatsapp(payload_enviado)

    try:
        with conectar_db() as conn:
            _garantir_integracoes_ambiente_whatsapp(conn)
            integracao = _buscar_integracao_whatsapp(conn, phone_number_id, waba_id)
            conn.execute(
                """
                INSERT OR IGNORE INTO whatsapp_webhook_eventos (
                    event_key, request_hash, empresa_id, integracao_id, waba_id, phone_number_id,
                    display_phone_number, event_type, field_name, message_id, conversation_id,
                    message_status, message_type, sender_phone, recipient_phone, sender_name,
                    message_text, error_code, error_title, error_message, event_timestamp, payload_json,
                    signature_valid, processing_status, received_at, processed_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, 'message_outbound', 'messages', ?, '', ?, ?, '', ?, '', ?, '', '', ?, ?, ?, 1, ?, ?, ?)
                """,
                (
                    event_key, request_hash, (integracao or {}).get("empresa_id"), (integracao or {}).get("id"),
                    waba_id, phone_number_id, (integracao or {}).get("display_phone_number", ""), message_id,
                    "accepted" if sucesso else "failed", tipo, destinatario, texto, erro, agora,
                    _json_canonico_whatsapp(evento_payload), "processed" if sucesso else "failed", agora, agora,
                ),
            )
            conn.commit()
    except Exception:
        app.logger.exception("Falha ao registrar envio do WhatsApp no histórico.")


def enviar_payload_whatsapp(
    destinatario: Any,
    conteudo: dict[str, Any],
    *,
    tipo: str,
    texto_log: str = "",
) -> tuple[bool, str, dict[str, Any]]:
    numero, erro_numero = _normalizar_destinatario_whatsapp(destinatario)
    if erro_numero:
        return False, erro_numero, {}

    token, endpoint, erro_configuracao = _configuracao_envio_whatsapp()
    if erro_configuracao:
        return False, erro_configuracao, {}

    payload: dict[str, Any] = {
        "messaging_product": "whatsapp",
        "recipient_type": "individual",
        "to": numero,
        "type": tipo,
        tipo: conteudo,
    }
    corpo = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    requisicao = urllib.request.Request(
        endpoint,
        data=corpo,
        method="POST",
        headers={
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json",
            "Accept": "application/json",
        },
    )
    timeout = max(5, min(_inteiro_ambiente_whatsapp("WHATSAPP_API_TIMEOUT_SEGUNDOS") or 20, 60))

    try:
        with urllib.request.urlopen(requisicao, timeout=timeout) as resposta:
            bruto = resposta.read().decode("utf-8", errors="replace")
            resposta_json = json.loads(bruto) if bruto.strip() else {}
            if not isinstance(resposta_json, dict):
                resposta_json = {"response": resposta_json}
            message_id = str(((resposta_json.get("messages") or [{}])[0] or {}).get("id") or "").strip()
            detalhe = f"Mensagem aceita pela Meta{f' ({message_id})' if message_id else ''}."
            _registrar_envio_whatsapp(destinatario=numero, tipo=tipo, texto=texto_log, payload_enviado=payload, resposta_api=resposta_json, sucesso=True)
            return True, detalhe, resposta_json
    except urllib.error.HTTPError as exc:
        bruto = exc.read().decode("utf-8", errors="replace")
        try:
            resposta_json = json.loads(bruto) if bruto.strip() else {}
        except json.JSONDecodeError:
            resposta_json = {"raw": bruto[:2000]}
        detalhe = _mensagem_erro_graph_whatsapp(resposta_json, exc.code)
        app.logger.warning("Envio do WhatsApp recusado pela Meta: %s", detalhe)
        _registrar_envio_whatsapp(destinatario=numero, tipo=tipo, texto=texto_log, payload_enviado=payload, resposta_api=resposta_json, sucesso=False, erro=detalhe)
        return False, detalhe, resposta_json
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        detalhe = f"Falha de comunicação com a API do WhatsApp: {exc}."
        app.logger.warning(detalhe)
        _registrar_envio_whatsapp(destinatario=numero, tipo=tipo, texto=texto_log, payload_enviado=payload, resposta_api={}, sucesso=False, erro=detalhe)
        return False, detalhe, {}


def enviar_whatsapp(destinatario: Any, mensagem: Any, *, preview_url: bool = False) -> tuple[bool, str, dict[str, Any]]:
    texto = str(mensagem or "").strip()
    if not texto:
        return False, "A mensagem do WhatsApp está vazia.", {}
    if len(texto) > 4096:
        return False, "A mensagem ultrapassa o limite de 4.096 caracteres.", {}
    return enviar_payload_whatsapp(destinatario, {"preview_url": bool(preview_url), "body": texto}, tipo="text", texto_log=texto)


def enviar_whatsapp_template(
    destinatario: Any,
    nome_template: str,
    *,
    idioma: str = "pt_BR",
    componentes: list[dict[str, Any]] | None = None,
) -> tuple[bool, str, dict[str, Any]]:
    nome = str(nome_template or "").strip()
    if not nome:
        return False, "Nome do template não informado.", {}
    conteudo: dict[str, Any] = {"name": nome, "language": {"code": str(idioma or "pt_BR").strip() or "pt_BR"}}
    if componentes:
        conteudo["components"] = componentes
    return enviar_payload_whatsapp(destinatario, conteudo, tipo="template", texto_log=f"Template: {nome}")


def enviar_whatsapp_imagem(destinatario: Any, link: str, *, legenda: str = "") -> tuple[bool, str, dict[str, Any]]:
    url = str(link or "").strip()
    if not url.startswith(("https://", "http://")):
        return False, "Link público da imagem inválido.", {}
    conteudo: dict[str, Any] = {"link": url}
    if str(legenda or "").strip():
        conteudo["caption"] = str(legenda).strip()[:1024]
    return enviar_payload_whatsapp(destinatario, conteudo, tipo="image", texto_log=str(legenda or "").strip())


def enviar_whatsapp_documento(
    destinatario: Any,
    link: str,
    *,
    nome_arquivo: str = "documento.pdf",
    legenda: str = "",
) -> tuple[bool, str, dict[str, Any]]:
    url = str(link or "").strip()
    if not url.startswith(("https://", "http://")):
        return False, "Link público do documento inválido.", {}
    conteudo: dict[str, Any] = {"link": url, "filename": str(nome_arquivo or "documento.pdf").strip()[:240]}
    if str(legenda or "").strip():
        conteudo["caption"] = str(legenda).strip()[:1024]
    return enviar_payload_whatsapp(destinatario, conteudo, tipo="document", texto_log=str(legenda or nome_arquivo).strip())


def marcar_mensagem_whatsapp_como_lida(message_id: str) -> tuple[bool, str, dict[str, Any]]:
    identificador = str(message_id or "").strip()
    if not identificador:
        return False, "ID da mensagem não informado.", {}
    token, endpoint, erro_configuracao = _configuracao_envio_whatsapp()
    if erro_configuracao:
        return False, erro_configuracao, {}
    payload = {"messaging_product": "whatsapp", "status": "read", "message_id": identificador}
    requisicao = urllib.request.Request(endpoint, data=json.dumps(payload).encode("utf-8"), method="POST", headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json", "Accept": "application/json"})
    try:
        with urllib.request.urlopen(requisicao, timeout=20) as resposta:
            bruto = resposta.read().decode("utf-8", errors="replace")
            dados = json.loads(bruto) if bruto.strip() else {}
            return True, "Mensagem marcada como lida.", dados if isinstance(dados, dict) else {"response": dados}
    except urllib.error.HTTPError as exc:
        bruto = exc.read().decode("utf-8", errors="replace")
        try:
            dados = json.loads(bruto) if bruto.strip() else {}
        except json.JSONDecodeError:
            dados = {"raw": bruto[:2000]}
        return False, _mensagem_erro_graph_whatsapp(dados, exc.code), dados
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        return False, f"Falha de comunicação com a API do WhatsApp: {exc}.", {}


def _hash_whatsapp(valor: Any) -> str:
    conteudo = valor if isinstance(valor, bytes) else _json_canonico_whatsapp(valor).encode("utf-8")
    return hashlib.sha256(conteudo).hexdigest()


def _timestamp_whatsapp_iso(valor: Any) -> str:
    try:
        timestamp = int(str(valor or "").strip())
    except (TypeError, ValueError):
        return ""

    try:
        return datetime.fromtimestamp(timestamp, tz=ZoneInfo("UTC")).isoformat(timespec="seconds")
    except (OverflowError, OSError, ValueError):
        return ""


def _texto_mensagem_whatsapp(mensagem: dict[str, Any]) -> str:
    tipo = str(mensagem.get("type") or "").strip().lower()

    if tipo == "text":
        return str((mensagem.get("text") or {}).get("body") or "").strip()

    if tipo == "button":
        return str((mensagem.get("button") or {}).get("text") or "").strip()

    if tipo == "interactive":
        interativo = mensagem.get("interactive") or {}
        resposta_botao = interativo.get("button_reply") or {}
        resposta_lista = interativo.get("list_reply") or {}
        return str(
            resposta_botao.get("title")
            or resposta_botao.get("id")
            or resposta_lista.get("title")
            or resposta_lista.get("description")
            or resposta_lista.get("id")
            or ""
        ).strip()

    if tipo in {"image", "video", "document"}:
        return str((mensagem.get(tipo) or {}).get("caption") or "").strip()

    if tipo == "location":
        localizacao = mensagem.get("location") or {}
        nome = str(localizacao.get("name") or "").strip()
        endereco = str(localizacao.get("address") or "").strip()
        latitude = str(localizacao.get("latitude") or "").strip()
        longitude = str(localizacao.get("longitude") or "").strip()
        partes = [parte for parte in (nome, endereco, f"{latitude},{longitude}" if latitude and longitude else "") if parte]
        return " | ".join(partes)

    if tipo == "contacts":
        contatos = mensagem.get("contacts") or []
        nomes = []
        for contato in contatos:
            if not isinstance(contato, dict):
                continue
            nome = str((contato.get("name") or {}).get("formatted_name") or "").strip()
            if nome:
                nomes.append(nome)
        return ", ".join(nomes)

    return ""


def _primeiro_erro_whatsapp(valor: dict[str, Any]) -> tuple[str, str, str]:
    erros = valor.get("errors") or []
    if not erros or not isinstance(erros[0], dict):
        return "", "", ""

    erro = erros[0]
    detalhes = erro.get("error_data") or {}
    return (
        str(erro.get("code") or "").strip(),
        str(erro.get("title") or "").strip(),
        str(erro.get("message") or detalhes.get("details") or "").strip(),
    )


def _garantir_integracao_teste_whatsapp(conn: sqlite3.Connection) -> None:
    phone_number_id = _variavel_ambiente_whatsapp("WHATSAPP_TEST_PHONE_NUMBER_ID")
    if not phone_number_id:
        return

    waba_id = _variavel_ambiente_whatsapp("WHATSAPP_TEST_WABA_ID")
    empresa_id = _inteiro_ambiente_whatsapp("WHATSAPP_TEST_EMPRESA_ID")
    agora = datetime.now(ZoneInfo("UTC")).isoformat(timespec="seconds")

    conn.execute(
        """
        INSERT OR IGNORE INTO whatsapp_integracoes (
            empresa_id,
            waba_id,
            phone_number_id,
            nome_integracao,
            status,
            ambiente,
            criado_em,
            atualizado_em
        ) VALUES (?, ?, ?, ?, 'ativo', 'teste', ?, ?)
        """,
        (
            empresa_id,
            waba_id,
            phone_number_id,
            "Conta de teste da Meta",
            agora,
            agora,
        ),
    )

    conn.execute(
        """
        UPDATE whatsapp_integracoes
        SET waba_id = COALESCE(NULLIF(?, ''), waba_id),
            status = 'ativo',
            ambiente = 'teste',
            atualizado_em = ?
        WHERE phone_number_id = ?
        """,
        (waba_id, agora, phone_number_id),
    )


def _garantir_integracao_producao_whatsapp(conn: sqlite3.Connection) -> None:
    phone_number_id = _variavel_ambiente_whatsapp("WHATSAPP_PHONE_NUMBER_ID")
    if not phone_number_id:
        return
    waba_id = _variavel_ambiente_whatsapp("WHATSAPP_WABA_ID")
    empresa_id = _inteiro_ambiente_whatsapp("WHATSAPP_EMPRESA_ID")
    display_phone_number = _variavel_ambiente_whatsapp("WHATSAPP_DISPLAY_PHONE_NUMBER")
    agora = datetime.now(ZoneInfo("UTC")).isoformat(timespec="seconds")
    conn.execute(
        """
        INSERT OR IGNORE INTO whatsapp_integracoes (
            empresa_id, waba_id, phone_number_id, display_phone_number, nome_integracao, status, ambiente, criado_em, atualizado_em
        ) VALUES (?, ?, ?, ?, 'WhatsApp oficial', 'ativo', 'producao', ?, ?)
        """,
        (empresa_id, waba_id, phone_number_id, display_phone_number, agora, agora),
    )
    conn.execute(
        """
        UPDATE whatsapp_integracoes
        SET empresa_id = COALESCE(?, empresa_id), waba_id = COALESCE(NULLIF(?, ''), waba_id),
            display_phone_number = COALESCE(NULLIF(?, ''), display_phone_number), status = 'ativo',
            ambiente = 'producao', atualizado_em = ?
        WHERE phone_number_id = ?
        """,
        (empresa_id, waba_id, display_phone_number, agora, phone_number_id),
    )


def _garantir_integracoes_ambiente_whatsapp(conn: sqlite3.Connection) -> None:
    _garantir_integracao_teste_whatsapp(conn)
    _garantir_integracao_producao_whatsapp(conn)


def _buscar_integracao_whatsapp(
    conn: sqlite3.Connection,
    phone_number_id: str,
    waba_id: str,
) -> dict[str, Any] | None:
    _garantir_integracoes_ambiente_whatsapp(conn)

    row = None
    if phone_number_id:
        row = conn.execute(
            """
            SELECT id, empresa_id, waba_id, phone_number_id, display_phone_number,
                   nome_integracao, status, ambiente
            FROM whatsapp_integracoes
            WHERE phone_number_id = ?
            LIMIT 1
            """,
            (phone_number_id,),
        ).fetchone()

    if row is None and waba_id:
        row = conn.execute(
            """
            SELECT id, empresa_id, waba_id, phone_number_id, display_phone_number,
                   nome_integracao, status, ambiente
            FROM whatsapp_integracoes
            WHERE waba_id = ?
            ORDER BY id ASC
            LIMIT 1
            """,
            (waba_id,),
        ).fetchone()

    return dict(row) if row is not None else None


def _extrair_eventos_whatsapp(payload: dict[str, Any], hash_requisicao: str) -> list[dict[str, Any]]:
    eventos: list[dict[str, Any]] = []
    objeto = str(payload.get("object") or "").strip()
    entradas = payload.get("entry") or []

    for indice_entrada, entrada in enumerate(entradas):
        if not isinstance(entrada, dict):
            continue

        waba_id = str(entrada.get("id") or "").strip()
        alteracoes = entrada.get("changes") or []

        for indice_alteracao, alteracao in enumerate(alteracoes):
            if not isinstance(alteracao, dict):
                continue

            campo = str(alteracao.get("field") or "").strip()
            valor = alteracao.get("value") or {}
            if not isinstance(valor, dict):
                valor = {"value": valor}

            metadata = valor.get("metadata") or {}
            phone_number_id = str(metadata.get("phone_number_id") or "").strip()
            display_phone_number = str(metadata.get("display_phone_number") or "").strip()
            contatos = {
                str(contato.get("wa_id") or "").strip(): str((contato.get("profile") or {}).get("name") or "").strip()
                for contato in (valor.get("contacts") or [])
                if isinstance(contato, dict)
            }
            erro_codigo, erro_titulo, erro_mensagem = _primeiro_erro_whatsapp(valor)
            quantidade_antes = len(eventos)

            for mensagem in valor.get("messages") or []:
                if not isinstance(mensagem, dict):
                    continue

                message_id = str(mensagem.get("id") or "").strip()
                remetente = str(mensagem.get("from") or "").strip()
                evento_payload = {
                    "object": objeto,
                    "waba_id": waba_id,
                    "field": campo,
                    "metadata": metadata,
                    "contact": contatos.get(remetente, ""),
                    "message": mensagem,
                }
                chave_base = message_id or _hash_whatsapp(evento_payload)
                eventos.append(
                    {
                        "event_key": f"message:{chave_base}",
                        "request_hash": hash_requisicao,
                        "waba_id": waba_id,
                        "phone_number_id": phone_number_id,
                        "display_phone_number": display_phone_number,
                        "event_type": "message_received",
                        "field_name": campo,
                        "message_id": message_id,
                        "conversation_id": "",
                        "message_status": "received",
                        "message_type": str(mensagem.get("type") or "").strip(),
                        "sender_phone": remetente,
                        "recipient_phone": display_phone_number,
                        "sender_name": contatos.get(remetente, ""),
                        "message_text": _texto_mensagem_whatsapp(mensagem),
                        "error_code": erro_codigo,
                        "error_title": erro_titulo,
                        "error_message": erro_mensagem,
                        "event_timestamp": _timestamp_whatsapp_iso(mensagem.get("timestamp")),
                        "payload_json": _json_canonico_whatsapp(evento_payload),
                    }
                )

            for status in valor.get("statuses") or []:
                if not isinstance(status, dict):
                    continue

                message_id = str(status.get("id") or "").strip()
                status_nome = str(status.get("status") or "").strip()
                timestamp = str(status.get("timestamp") or "").strip()
                conversa = status.get("conversation") or {}
                erros_status = {"errors": status.get("errors") or []}
                status_erro_codigo, status_erro_titulo, status_erro_mensagem = _primeiro_erro_whatsapp(erros_status)
                evento_payload = {
                    "object": objeto,
                    "waba_id": waba_id,
                    "field": campo,
                    "metadata": metadata,
                    "status": status,
                }
                chave_base = ":".join(parte for parte in (message_id, status_nome, timestamp) if parte)
                if not chave_base:
                    chave_base = _hash_whatsapp(evento_payload)
                eventos.append(
                    {
                        "event_key": f"status:{chave_base}",
                        "request_hash": hash_requisicao,
                        "waba_id": waba_id,
                        "phone_number_id": phone_number_id,
                        "display_phone_number": display_phone_number,
                        "event_type": "message_status",
                        "field_name": campo,
                        "message_id": message_id,
                        "conversation_id": str(conversa.get("id") or "").strip(),
                        "message_status": status_nome,
                        "message_type": "status",
                        "sender_phone": display_phone_number,
                        "recipient_phone": str(status.get("recipient_id") or "").strip(),
                        "sender_name": "",
                        "message_text": "",
                        "error_code": status_erro_codigo or erro_codigo,
                        "error_title": status_erro_titulo or erro_titulo,
                        "error_message": status_erro_mensagem or erro_mensagem,
                        "event_timestamp": _timestamp_whatsapp_iso(status.get("timestamp")),
                        "payload_json": _json_canonico_whatsapp(evento_payload),
                    }
                )

            if len(eventos) == quantidade_antes:
                evento_payload = {
                    "object": objeto,
                    "waba_id": waba_id,
                    "field": campo,
                    "metadata": metadata,
                    "value": valor,
                }
                eventos.append(
                    {
                        "event_key": f"change:{_hash_whatsapp(evento_payload)}",
                        "request_hash": hash_requisicao,
                        "waba_id": waba_id,
                        "phone_number_id": phone_number_id,
                        "display_phone_number": display_phone_number,
                        "event_type": "webhook_change",
                        "field_name": campo,
                        "message_id": "",
                        "conversation_id": "",
                        "message_status": "",
                        "message_type": "",
                        "sender_phone": "",
                        "recipient_phone": "",
                        "sender_name": "",
                        "message_text": "",
                        "error_code": erro_codigo,
                        "error_title": erro_titulo,
                        "error_message": erro_mensagem,
                        "event_timestamp": "",
                        "payload_json": _json_canonico_whatsapp(evento_payload),
                    }
                )

    if not eventos:
        eventos.append(
            {
                "event_key": f"payload:{_hash_whatsapp(payload)}",
                "request_hash": hash_requisicao,
                "waba_id": "",
                "phone_number_id": "",
                "display_phone_number": "",
                "event_type": "webhook_payload",
                "field_name": "",
                "message_id": "",
                "conversation_id": "",
                "message_status": "",
                "message_type": "",
                "sender_phone": "",
                "recipient_phone": "",
                "sender_name": "",
                "message_text": "",
                "error_code": "",
                "error_title": "",
                "error_message": "",
                "event_timestamp": "",
                "payload_json": _json_canonico_whatsapp(payload),
            }
        )

    return eventos


def _registrar_eventos_whatsapp(payload: dict[str, Any], corpo_bruto: bytes) -> tuple[int, int]:
    hash_requisicao = _hash_whatsapp(corpo_bruto)
    eventos = _extrair_eventos_whatsapp(payload, hash_requisicao)
    inseridos = 0
    duplicados = 0
    recebido_em = datetime.now(ZoneInfo("UTC")).isoformat(timespec="seconds")

    with conectar_db() as conn:
        for evento in eventos:
            integracao = _buscar_integracao_whatsapp(
                conn,
                str(evento.get("phone_number_id") or ""),
                str(evento.get("waba_id") or ""),
            )
            cursor = conn.execute(
                """
                INSERT OR IGNORE INTO whatsapp_webhook_eventos (
                    event_key,
                    request_hash,
                    empresa_id,
                    integracao_id,
                    waba_id,
                    phone_number_id,
                    display_phone_number,
                    event_type,
                    field_name,
                    message_id,
                    conversation_id,
                    message_status,
                    message_type,
                    sender_phone,
                    recipient_phone,
                    sender_name,
                    message_text,
                    error_code,
                    error_title,
                    error_message,
                    event_timestamp,
                    payload_json,
                    signature_valid,
                    processing_status,
                    received_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, 'received', ?)
                """,
                (
                    str(evento.get("event_key") or ""),
                    str(evento.get("request_hash") or ""),
                    (integracao or {}).get("empresa_id"),
                    (integracao or {}).get("id"),
                    str(evento.get("waba_id") or ""),
                    str(evento.get("phone_number_id") or ""),
                    str(evento.get("display_phone_number") or ""),
                    str(evento.get("event_type") or ""),
                    str(evento.get("field_name") or ""),
                    str(evento.get("message_id") or ""),
                    str(evento.get("conversation_id") or ""),
                    str(evento.get("message_status") or ""),
                    str(evento.get("message_type") or ""),
                    str(evento.get("sender_phone") or ""),
                    str(evento.get("recipient_phone") or ""),
                    str(evento.get("sender_name") or ""),
                    str(evento.get("message_text") or ""),
                    str(evento.get("error_code") or ""),
                    str(evento.get("error_title") or ""),
                    str(evento.get("error_message") or ""),
                    str(evento.get("event_timestamp") or ""),
                    str(evento.get("payload_json") or "{}"),
                    recebido_em,
                ),
            )
            if cursor.rowcount == 1:
                inseridos += 1
            else:
                duplicados += 1

        conn.commit()

    return inseridos, duplicados


def buscar_usuario_por_email(email: str) -> dict[str, Any] | None:
    email_normalizado = str(email or "").strip().lower()

    if not email_normalizado:
        return None

    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT
                usuarios.id,
                usuarios.empresa_id,
                usuarios.funcionario_id,
                usuarios.nome,
                usuarios.email,
                usuarios.senha_hash,
                usuarios.perfil,
                usuarios.permissoes_json,
                usuarios.status,
                usuarios.sessao_versao,
                usuarios.ultimo_login,
                usuarios.atualizado_em,
                usuarios.criado_em,
                empresas.nome_fantasia AS empresa_nome,
                empresas.plano AS empresa_plano,
                empresas.status AS empresa_status
            FROM usuarios
            JOIN empresas ON empresas.id = usuarios.empresa_id
            WHERE LOWER(usuarios.email) = ?
            LIMIT 1
            """,
            (email_normalizado,),
        ).fetchone()

    if row is None:
        return None

    return dict(row)


def autenticar_usuario(email: str, senha: str) -> dict[str, Any] | None:
    email_normalizado = str(email or "").strip().lower()
    senha_normalizada = str(senha or "").strip()

    usuario = buscar_usuario_por_email(email_normalizado)

    if usuario is None:
        return None

    if str(usuario.get("status") or "").strip().lower() != "ativo":
        return None

    if str(usuario.get("empresa_status") or "").strip().lower() not in {"ativo", "trial"}:
        return None

    senha_hash = str(usuario.get("senha_hash") or "")

    if not senha_hash or not check_password_hash(senha_hash, senha_normalizada):
        return None

    return usuario


def normalizar_perfil_usuario(perfil: Any) -> str:
    perfil_normalizado = str(perfil or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "admin": "administrador",
        "dono": "administrador",
        "administrador_empresa": "administrador",
        "administrador_sistema": "super_admin",
        "superadmin": "super_admin",
        "estoque_compras": "estoque",
        "operacional": "tecnico",
        "tecnico_operacional": "tecnico",
        "somente_leitura": "consulta",
    }
    perfil_normalizado = aliases.get(perfil_normalizado, perfil_normalizado)
    return perfil_normalizado if perfil_normalizado in GESTFLOW_PERFIS_USUARIO_CODIGOS else "consulta"


def rotulo_perfil_usuario(perfil: Any) -> str:
    perfil_normalizado = normalizar_perfil_usuario(perfil)
    return str(GESTFLOW_PERFIS_USUARIO.get(perfil_normalizado, {}).get("nome") or perfil_normalizado)


def normalizar_permissoes_usuario(valor: Any) -> dict[str, set[str]] | None:
    texto = str(valor or "").strip()
    if not texto:
        return None

    try:
        dados = json.loads(texto)
    except (TypeError, ValueError, json.JSONDecodeError):
        return None

    if not isinstance(dados, dict):
        return None

    permissoes: dict[str, set[str]] = {}
    modulos_validos = {item["codigo"] for item in GESTFLOW_MODULOS_PERMISSOES}

    for modulo, acoes in dados.items():
        modulo_normalizado = str(modulo or "").strip()
        if modulo_normalizado not in modulos_validos:
            continue

        if isinstance(acoes, str):
            acoes_iteraveis = [acoes]
        elif isinstance(acoes, (list, tuple, set)):
            acoes_iteraveis = acoes
        else:
            continue

        acoes_validas = {
            str(acao or "").strip()
            for acao in acoes_iteraveis
            if str(acao or "").strip() in GESTFLOW_ACOES_PERMISSAO_CODIGOS
        }
        permissoes[modulo_normalizado] = acoes_validas

    return permissoes


def serializar_permissoes_usuario(permissoes: dict[str, set[str]] | None) -> str:
    if permissoes is None:
        return ""

    normalizado = {
        modulo: sorted(
            acao for acao in acoes
            if acao in GESTFLOW_ACOES_PERMISSAO_CODIGOS
        )
        for modulo, acoes in sorted(permissoes.items())
    }
    return json.dumps(normalizado, ensure_ascii=False, sort_keys=True)


def permissoes_padrao_perfil(perfil: Any) -> dict[str, set[str]]:
    perfil_normalizado = normalizar_perfil_usuario(perfil)

    if perfil_normalizado in {"super_admin", "administrador"}:
        return {
            modulo["codigo"]: set(_ACOES_TOTAIS)
            for modulo in GESTFLOW_MODULOS_PERMISSOES
        }

    base = GESTFLOW_PERMISSOES_PADRAO_PERFIL.get(perfil_normalizado, {})
    return {modulo: set(acoes) for modulo, acoes in base.items()}


def permissoes_efetivas_usuario(usuario: dict[str, Any] | None = None) -> dict[str, set[str]]:
    usuario_atual = dict(usuario or usuario_logado() or {})
    perfil = normalizar_perfil_usuario(usuario_atual.get("perfil"))

    if perfil in {"super_admin", "administrador"}:
        return permissoes_padrao_perfil(perfil)

    personalizadas = normalizar_permissoes_usuario(
        usuario_atual.get("permissoes_json")
        if "permissoes_json" in usuario_atual
        else session.get("usuario_permissoes_json")
    )

    if personalizadas is not None:
        return personalizadas

    return permissoes_padrao_perfil(perfil)


def usuario_tem_permissao(
    modulo: str,
    acao: str = "visualizar",
    usuario: dict[str, Any] | None = None,
) -> bool:
    modulo_normalizado = str(modulo or "").strip()
    acao_normalizada = str(acao or "visualizar").strip().lower()

    if not session.get("usuario_id") and usuario is None:
        return False

    perfil = normalizar_perfil_usuario(
        (usuario or {}).get("perfil")
        if usuario is not None
        else session.get("usuario_perfil")
    )

    if modulo_normalizado == "admin":
        return perfil == "super_admin"

    if modulo_normalizado == "configuracoes":
        return perfil in {"super_admin", "administrador"}

    if perfil in {"super_admin", "administrador"}:
        return True

    permissoes = permissoes_efetivas_usuario(usuario)
    return acao_normalizada in permissoes.get(modulo_normalizado, set())


def modulo_usuario_visivel(modulo: str) -> bool:
    return usuario_tem_permissao(modulo, "visualizar")


def usuario_logado_eh_administrador_empresa() -> bool:
    return normalizar_perfil_usuario(session.get("usuario_perfil")) in {
        "super_admin",
        "administrador",
    }


def acao_permissao_por_requisicao() -> str:
    endpoint = str(request.endpoint or "").strip().lower()
    caminho = str(request.path or "").strip().lower()
    metodo = str(request.method or "GET").upper()

    if endpoint == "novo_contrato":
        return "criar"

    if endpoint == "editar_contrato":
        return "editar"

    if metodo in {"GET", "HEAD", "OPTIONS"}:
        if any(token in endpoint or token in caminho for token in (
            "export", "imprimir", "download", "baixar-arquivo", "cupom", "a4"
        )):
            return "exportar"
        return "visualizar"

    if any(token in endpoint or token in caminho for token in (
        "excluir", "remover", "delete"
    )):
        return "excluir"

    if any(token in endpoint or token in caminho for token in (
        "aprovar", "baixar", "receber", "pagar", "finalizar",
        "cancelar", "reabrir", "status", "sincronizar"
    )):
        return "aprovar"

    if any(token in endpoint or token in caminho for token in (
        "editar", "atualizar", "redefinir", "configuracoes", "salvar_"
    )):
        return "editar"

    return "criar"


def buscar_usuario_sessao_por_id(usuario_id: int) -> dict[str, Any] | None:
    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT
                u.id,
                u.empresa_id,
                u.funcionario_id,
                u.nome,
                u.email,
                u.perfil,
                u.permissoes_json,
                u.status,
                u.sessao_versao,
                e.nome_fantasia AS empresa_nome,
                e.plano AS empresa_plano,
                e.status AS empresa_status
            FROM usuarios u
            JOIN empresas e ON e.id = u.empresa_id
            WHERE u.id = ?
            LIMIT 1
            """,
            (usuario_id,),
        ).fetchone()

    return dict(row) if row else None


def revalidar_sessao_usuario() -> tuple[bool, str]:
    try:
        usuario_id = int(session.get("usuario_id") or 0)
    except (TypeError, ValueError):
        usuario_id = 0

    if not usuario_id:
        return False, "Sessão inválida."

    usuario = buscar_usuario_sessao_por_id(usuario_id)
    if usuario is None:
        session.clear()
        return False, "Usuário não encontrado."

    if str(usuario.get("status") or "").strip().lower() != "ativo":
        session.clear()
        return False, "Usuário inativo."

    if str(usuario.get("empresa_status") or "").strip().lower() not in {"ativo", "trial"}:
        session.clear()
        return False, "Empresa inativa."

    try:
        versao_sessao = int(session.get("usuario_sessao_versao") or 1)
        versao_banco = int(usuario.get("sessao_versao") or 1)
    except (TypeError, ValueError):
        versao_sessao = 1
        versao_banco = 1

    if versao_sessao != versao_banco:
        session.clear()
        return False, "A sessão foi encerrada após uma alteração de segurança."

    session["empresa_id"] = int(usuario["empresa_id"])
    session["usuario_nome"] = str(usuario.get("nome") or "")
    session["usuario_email"] = str(usuario.get("email") or "")
    session["usuario_perfil"] = normalizar_perfil_usuario(usuario.get("perfil"))
    session["usuario_permissoes_json"] = str(usuario.get("permissoes_json") or "")
    session["empresa_nome"] = str(usuario.get("empresa_nome") or "")
    session["empresa_plano"] = str(usuario.get("empresa_plano") or "")
    return True, ""


