def buscar_cliente_por_nome(nome_cliente: str) -> dict[str, Any] | None:
    empresa_id = empresa_logada_id()
    nome_normalizado = str(nome_cliente or "").strip()

    if not nome_normalizado:
        return None

    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT
                id,
                empresa_id,
                nome,
                documento,
                telefone,
                cidade,
                status,
                email,
                criado_em
            FROM clientes
            WHERE empresa_id = ?
              AND LOWER(nome) = LOWER(?)
            ORDER BY id DESC
            LIMIT 1
            """,
            (empresa_id, nome_normalizado),
        ).fetchone()

        if row is None:
            row = conn.execute(
                """
                SELECT
                    id,
                    empresa_id,
                    nome,
                    documento,
                    telefone,
                    cidade,
                    status,
                    email,
                    criado_em
                FROM clientes
                WHERE empresa_id = ?
                  AND LOWER(nome) LIKE LOWER(?)
                ORDER BY id DESC
                LIMIT 1
                """,
                (empresa_id, f"%{nome_normalizado}%"),
            ).fetchone()

    if row is None:
        return None

    return dict(row)




def normalizar_telefone_publico(valor: Any) -> str:
    return re.sub(r"\D+", "", str(valor or ""))


def normalizar_telefone_validacao_ponto(valor: Any) -> str:
    telefone = normalizar_telefone_publico(valor)

    if telefone.startswith("55") and len(telefone) in {12, 13}:
        telefone = telefone[2:]

    if len(telefone) not in {10, 11}:
        return ""

    ddd = telefone[:2]
    numero_base = telefone[-8:]
    return f"{ddd}{numero_base}"


def gerar_token_publico_cliente() -> str:
    return secrets.token_urlsafe(24)


