def produzir_produto_db(
    produto_id: int,
    quantidade_produzir: float,
    responsavel: str = "",
    observacoes: str = "",
) -> tuple[int | None, str]:
    empresa_id = empresa_logada_id()

    if quantidade_produzir <= 0:
        return None, "Informe uma quantidade de produção maior que zero."

    with conectar_db() as conn:
        try:
            conn.execute("BEGIN IMMEDIATE")
            produto = conn.execute(
                """
                SELECT
                    id,
                    nome,
                    unidade,
                    estoque_atual,
                    preco_custo_manual
                FROM produtos
                WHERE id = ?
                  AND empresa_id = ?
                LIMIT 1
                """,
                (produto_id, empresa_id),
            ).fetchone()

            if produto is None:
                conn.rollback()
                return None, "Produto não encontrado."

            itens = conn.execute(
                """
                SELECT
                    pci.componente_produto_id,
                    COALESCE(NULLIF(TRIM(p.nome), ''), pci.componente_nome) AS componente_nome,
                    COALESCE(NULLIF(TRIM(p.unidade), ''), pci.unidade, 'un') AS unidade,
                    pci.quantidade,
                    pci.perda_percentual,
                    COALESCE(NULLIF(TRIM(p.preco_custo), ''), pci.custo_unitario, '0,00') AS custo_unitario,
                    p.estoque_atual,
                    p.status
                FROM produto_composicao_itens pci
                JOIN produtos p
                  ON p.id = pci.componente_produto_id
                 AND p.empresa_id = pci.empresa_id
                WHERE pci.produto_id = ?
                  AND pci.empresa_id = ?
                ORDER BY pci.id ASC
                """,
                (produto_id, empresa_id),
            ).fetchall()

            if not itens:
                conn.rollback()
                return None, "Cadastre ao menos um componente na ficha técnica antes de produzir."

            resumo_cmv = calcular_cmv_produto(produto_id, atualizar_produto=True, conn=conn)
            cmv_unitario = float(resumo_cmv.get("cmv_unitario") or 0)
            consumos: list[dict[str, Any]] = []

            for item in itens:
                quantidade_base = _converter_valor_brl(item["quantidade"])
                perda = _converter_valor_brl(item["perda_percentual"])
                quantidade_consumida = quantidade_base * (1 + (perda / 100)) * quantidade_produzir
                estoque_anterior = _converter_valor_brl(item["estoque_atual"])
                custo_unitario = _converter_valor_brl(item["custo_unitario"])

                if str(item["status"] or "ativo").strip().lower() != "ativo":
                    conn.rollback()
                    return None, f"O componente {item['componente_nome']} está inativo."

                if estoque_anterior + 1e-9 < quantidade_consumida:
                    conn.rollback()
                    falta = quantidade_consumida - estoque_anterior
                    return None, (
                        f"Estoque insuficiente de {item['componente_nome']}. "
                        f"Necessário: {_formatar_numero_estoque(quantidade_consumida)} {item['unidade']}; "
                        f"disponível: {_formatar_numero_estoque(estoque_anterior)}; "
                        f"falta: {_formatar_numero_estoque(falta)}."
                    )

                consumos.append(
                    {
                        "componente_produto_id": int(item["componente_produto_id"]),
                        "componente_nome": str(item["componente_nome"] or ""),
                        "unidade": str(item["unidade"] or "un"),
                        "quantidade_consumida": quantidade_consumida,
                        "custo_unitario": custo_unitario,
                        "custo_total": quantidade_consumida * custo_unitario,
                        "estoque_anterior": estoque_anterior,
                        "estoque_atual": estoque_anterior - quantidade_consumida,
                    }
                )

            estoque_anterior_produto = _converter_valor_brl(produto["estoque_atual"])
            estoque_atual_produto = estoque_anterior_produto + quantidade_produzir
            custo_total = cmv_unitario * quantidade_produzir

            cursor = conn.execute(
                """
                INSERT INTO produto_producoes (
                    empresa_id,
                    produto_id,
                    produto_nome,
                    quantidade_produzida,
                    cmv_unitario,
                    custo_total,
                    estoque_anterior,
                    estoque_atual,
                    responsavel,
                    observacoes
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    produto_id,
                    str(produto["nome"] or ""),
                    _formatar_numero_estoque(quantidade_produzir),
                    _formatar_moeda_brl(cmv_unitario),
                    _formatar_moeda_brl(custo_total),
                    _formatar_numero_estoque(estoque_anterior_produto),
                    _formatar_numero_estoque(estoque_atual_produto),
                    responsavel,
                    observacoes,
                ),
            )
            producao_id = int(cursor.lastrowid)
            documento = f"Produção Nº {producao_id}"

            for consumo in consumos:
                conn.execute(
                    """
                    UPDATE produtos
                    SET estoque_atual = ?
                    WHERE id = ?
                      AND empresa_id = ?
                    """,
                    (
                        _formatar_numero_estoque(float(consumo["estoque_atual"])),
                        int(consumo["componente_produto_id"]),
                        empresa_id,
                    ),
                )
                conn.execute(
                    """
                    INSERT INTO estoque_movimentacoes (
                        empresa_id,
                        produto_id,
                        produto_nome,
                        tipo,
                        quantidade,
                        saldo_anterior,
                        saldo_atual,
                        motivo,
                        documento,
                        responsavel,
                        observacoes
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        empresa_id,
                        int(consumo["componente_produto_id"]),
                        str(consumo["componente_nome"]),
                        "saida",
                        _formatar_numero_estoque(float(consumo["quantidade_consumida"])),
                        _formatar_numero_estoque(float(consumo["estoque_anterior"])),
                        _formatar_numero_estoque(float(consumo["estoque_atual"])),
                        "Produção - consumo de componente",
                        documento,
                        responsavel,
                        f"Consumo automático para produzir {quantidade_produzir:g} unidade(s) de {produto['nome']}.",
                    ),
                )
                conn.execute(
                    """
                    INSERT INTO produto_producao_consumos (
                        empresa_id,
                        producao_id,
                        produto_id,
                        componente_produto_id,
                        componente_nome,
                        unidade,
                        quantidade_consumida,
                        custo_unitario,
                        custo_total,
                        estoque_anterior,
                        estoque_atual
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        empresa_id,
                        producao_id,
                        produto_id,
                        int(consumo["componente_produto_id"]),
                        str(consumo["componente_nome"]),
                        str(consumo["unidade"]),
                        _formatar_numero_estoque(float(consumo["quantidade_consumida"])),
                        _formatar_moeda_brl(float(consumo["custo_unitario"])),
                        _formatar_moeda_brl(float(consumo["custo_total"])),
                        _formatar_numero_estoque(float(consumo["estoque_anterior"])),
                        _formatar_numero_estoque(float(consumo["estoque_atual"])),
                    ),
                )

            conn.execute(
                """
                UPDATE produtos
                SET
                    estoque_atual = ?,
                    preco_custo = ?,
                    cmv_calculado = ?,
                    custo_origem = 'composicao',
                    possui_composicao = 'sim',
                    cmv_atualizado_em = ?
                WHERE id = ?
                  AND empresa_id = ?
                """,
                (
                    _formatar_numero_estoque(estoque_atual_produto),
                    _formatar_moeda_brl(cmv_unitario),
                    _formatar_moeda_brl(cmv_unitario),
                    agora_empresa().isoformat(timespec="seconds"),
                    produto_id,
                    empresa_id,
                ),
            )
            recalcular_produtos_dependentes(produto_id, conn)
            conn.execute(
                """
                INSERT INTO estoque_movimentacoes (
                    empresa_id,
                    produto_id,
                    produto_nome,
                    tipo,
                    quantidade,
                    saldo_anterior,
                    saldo_atual,
                    motivo,
                    documento,
                    responsavel,
                    observacoes
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    produto_id,
                    str(produto["nome"] or ""),
                    "entrada",
                    _formatar_numero_estoque(quantidade_produzir),
                    _formatar_numero_estoque(estoque_anterior_produto),
                    _formatar_numero_estoque(estoque_atual_produto),
                    "Produção de produto",
                    documento,
                    responsavel,
                    "Entrada automática do produto final após consumo dos componentes da ficha técnica.",
                ),
            )

            conn.commit()
            return producao_id, ""
        except sqlite3.Error as exc:
            conn.rollback()
            return None, f"Não foi possível concluir a produção: {exc}."


def excluir_produto_db(produto_id: int) -> tuple[bool, str]:
    return excluir_cadastro_sem_vinculos("produtos", produto_id, "produto")

def listar_estoque_movimentacoes(limite: int = 100, produto_id: int | None = None) -> list[dict[str, Any]]:
    empresa_id = empresa_logada_id()
    consulta = """
        SELECT
            id,
            empresa_id,
            produto_id,
            produto_nome,
            tipo,
            quantidade,
            saldo_anterior,
            saldo_atual,
            motivo,
            documento,
            responsavel,
            observacoes,
            criado_em
        FROM estoque_movimentacoes
        WHERE empresa_id = ?
    """

    parametros: list[Any] = [empresa_id]

    if produto_id is not None:
        consulta += " AND produto_id = ?"
        parametros.append(produto_id)

    consulta += " ORDER BY id DESC LIMIT ?"
    parametros.append(limite)

    with conectar_db() as conn:
        rows = conn.execute(consulta, parametros).fetchall()

    return [dict(row) for row in rows]

def salvar_estoque_movimentacao_db(movimentacao: dict[str, str]) -> int:
    empresa_id = empresa_logada_id()

    with conectar_db() as conn:
        cursor = conn.execute(
            """
            INSERT INTO estoque_movimentacoes (
                empresa_id,
                produto_id,
                produto_nome,
                tipo,
                quantidade,
                saldo_anterior,
                saldo_atual,
                motivo,
                documento,
                responsavel,
                observacoes
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                movimentacao["produto_id"],
                movimentacao["produto_nome"],
                movimentacao["tipo"],
                movimentacao["quantidade"],
                movimentacao["saldo_anterior"],
                movimentacao["saldo_atual"],
                movimentacao["motivo"],
                movimentacao["documento"],
                movimentacao["responsavel"],
                movimentacao["observacoes"],
            ),
        )

        if str(movimentacao.get("tipo") or "") != "compra":
            conn.execute(
                """
                UPDATE produtos
                SET estoque_atual = ?
                WHERE id = ?
                  AND empresa_id = ?
                """,
                (
                    movimentacao["saldo_atual"],
                    movimentacao["produto_id"],
                    empresa_id,
                ),
            )

        conn.commit()

    return int(cursor.lastrowid)


def _fornecedor_compra_por_motivo(motivo: Any) -> str:
    texto = str(motivo or "").strip()
    prefixo = "Compra de produto - "

    if texto.lower().startswith(prefixo.lower()):
        return texto[len(prefixo):].strip()

    return ""


def _dados_observacoes_compra(observacoes: Any) -> tuple[str, str]:
    linhas = str(observacoes or "").replace("\r\n", "\n").replace("\r", "\n").split("\n")
    valor_custo = ""
    observacoes_livres: list[str] = []

    for indice, linha in enumerate(linhas):
        texto = linha.strip()
        if indice == 0 and texto.lower().startswith("valor de custo:"):
            valor_custo = texto.split(":", 1)[1].strip()
            continue
        observacoes_livres.append(linha)

    return valor_custo, "\n".join(observacoes_livres).strip()


def normalizar_compra_estoque(registro: dict[str, Any]) -> dict[str, Any]:
    compra = dict(registro)
    valor_custo, observacoes = _dados_observacoes_compra(compra.get("observacoes"))
    quantidade = _converter_valor_brl(compra.get("quantidade"))
    custo_unitario = _converter_valor_brl(valor_custo)

    compra["fornecedor"] = _fornecedor_compra_por_motivo(compra.get("motivo"))
    compra["valor_custo"] = valor_custo
    compra["observacoes_compra"] = observacoes
    compra["valor_total_compra"] = _formatar_moeda_brl(quantidade * custo_unitario)
    compra["criado_em_exibicao"] = formatar_data_hora_br(compra.get("criado_em"))
    return compra


