            """
            UPDATE servicos
            SET nome = ?, codigo = ?, categoria = ?, unidade = ?, custo = ?, valor_venda = ?,
                tempo_estimado = ?, tempo_estimado_valor = ?, tempo_estimado_unidade = ?,
                tempo_estimado_minutos = ?, tipo_contratacao = ?, status = ?, observacoes = ?
            WHERE id = ? AND empresa_id = ?
            """,
