def resumir_atividade_financeira(atividade_id: int | None) -> dict[str, Any]:
    vazio = {
        "previsto": 0.0,
        "recebido": 0.0,
        "a_receber": 0.0,
        "custos": 0.0,
        "resultado": 0.0,
        "margem": 0.0,
        "previsto_formatado": "0,00",
        "recebido_formatado": "0,00",
        "a_receber_formatado": "0,00",
        "custos_formatado": "0,00",
        "resultado_formatado": "0,00",
        "margem_formatada": "0,00",
    }

    if not atividade_id:
        return vazio

    atividade = buscar_atividade_financeira_por_id(int(atividade_id))
    if not atividade:
        return vazio

    empresa_id = empresa_logada_id()
    atividade_id = int(atividade_id)
    previsto = _converter_valor_brl(atividade.get("valor_previsto"))

    origem_atividade = str(atividade.get("origem") or "").strip().lower()
    origem_atividade_id = atividade.get("origem_id")

    try:
        origem_atividade_id = (
            int(origem_atividade_id)
            if origem_atividade_id not in (None, "")
            else None
        )
    except (TypeError, ValueError):
        origem_atividade_id = None

    with conectar_db() as conn:
        parametros: list[Any] = [empresa_id, atividade_id]
        vinculo_venda_orcamento = ""

        if origem_atividade == "orcamento" and origem_atividade_id:
            vinculo_venda_orcamento = """
                OR (
                    ft.origem = 'venda'
                    AND EXISTS (
                        SELECT 1
                        FROM vendas v
                        WHERE v.id = ft.origem_id
                          AND v.empresa_id = ft.empresa_id
                          AND v.origem_orcamento_id = ?
                    )
                )
            """
            parametros.append(origem_atividade_id)

        rows = conn.execute(
            f"""
            SELECT DISTINCT
                ft.id,
                ft.tipo,
                ft.status,
                ft.valor
            FROM financeiro_titulos ft
            WHERE ft.empresa_id = ?
              AND LOWER(TRIM(COALESCE(ft.status, ''))) <> 'cancelado'
              AND (
                    ft.atividade_financeira_id = ?
                    {vinculo_venda_orcamento}
              )
            ORDER BY ft.id ASC
            """,
            parametros,
        ).fetchall()

    recebido = 0.0
    custos = 0.0

    for row in rows:
        tipo = str(row["tipo"] or "").strip().lower()
        status = str(row["status"] or "").strip().lower()
        valor = _converter_valor_brl(row["valor"])

        if tipo == "receber" and status in {"pago", "recebido"}:
            recebido += valor
        elif tipo == "pagar":
            custos += valor

    a_receber = max(previsto - recebido, 0.0)
    resultado = recebido - custos
    margem = (resultado / recebido * 100) if recebido else 0.0

    return {
        "previsto": previsto,
        "recebido": recebido,
        "a_receber": a_receber,
        "custos": custos,
        "resultado": resultado,
        "margem": margem,
        "previsto_formatado": _formatar_moeda_brl(previsto),
        "recebido_formatado": _formatar_moeda_brl(recebido),
        "a_receber_formatado": _formatar_moeda_brl(a_receber),
        "custos_formatado": _formatar_moeda_brl(custos),
        "resultado_formatado": _formatar_moeda_brl(resultado),
        "margem_formatada": _formatar_percentual_simples(margem),
    }


def normalizar_vinculos_financeiros_documento(
    dados: dict[str, Any],
) -> dict[str, Any]:
    dados_normalizados = dict(dados)
    centro_texto_original = str(
        dados_normalizados.get("centro_custo") or ""
    ).strip()

    centro_id: int | None = None
    atividade_id: int | None = None

    try:
        centro_id_texto = str(
            dados_normalizados.get("centro_custo_id") or ""
        ).strip()
        if centro_id_texto:
            centro_id = int(centro_id_texto)
    except (TypeError, ValueError):
        centro_id = None

    try:
        atividade_id_texto = str(
            dados_normalizados.get("atividade_financeira_id") or ""
        ).strip()
        if atividade_id_texto:
            atividade_id = int(atividade_id_texto)
    except (TypeError, ValueError):
        atividade_id = None

    centro = buscar_centro_custo_por_id(centro_id) if centro_id else None
    atividade = (
        buscar_atividade_financeira_por_id(atividade_id)
        if atividade_id
        else None
    )

    if atividade_id and atividade is None:
        atividade_id = None

    atividade_centro_id: int | None = None
    if atividade is not None:
        try:
            valor_atividade_centro = atividade.get("centro_custo_id")
            if valor_atividade_centro not in (None, ""):
                atividade_centro_id = int(valor_atividade_centro)
        except (TypeError, ValueError):
            atividade_centro_id = None

    if centro is None and atividade_centro_id:
        centro = buscar_centro_custo_por_id(atividade_centro_id)
        if centro is not None:
            centro_id = atividade_centro_id

    if (
        centro_id
        and atividade_centro_id
        and centro_id != atividade_centro_id
    ):
        atividade_id = None

    if centro is not None:
        dados_normalizados["centro_custo_id"] = str(int(centro["id"]))
        dados_normalizados["centro_custo"] = str(
            centro.get("nome") or ""
        ).strip()
    else:
        dados_normalizados["centro_custo_id"] = ""
        dados_normalizados["centro_custo"] = centro_texto_original

    dados_normalizados["atividade_financeira_id"] = (
        str(atividade_id) if atividade_id else ""
    )

    return dados_normalizados


def salvar_centro_custo_formulario(centro_id: int | None = None) -> str:
    dados = {k: (request.form.get(k) or '').strip() for k in ['codigo','nome','descricao','cor','status']}
    dados['status'] = dados['status'] or 'ativo'
    if not dados['nome']:
        return "Informe o nome do centro de custo."
    empresa_id = empresa_logada_id()
    with conectar_db() as conn:
        conflito = conn.execute(
            """SELECT id FROM centros_custo WHERE empresa_id = ? AND id <> COALESCE(?, 0) AND (LOWER(TRIM(nome)) = LOWER(TRIM(?)) OR (? <> '' AND LOWER(TRIM(codigo)) = LOWER(TRIM(?)))) LIMIT 1""",
            (empresa_id, centro_id, dados['nome'], dados['codigo'], dados['codigo']),
        ).fetchone()
        if conflito is not None:
            return "Já existe um centro de custo com este nome ou código."
        if centro_id:
            conn.execute("UPDATE centros_custo SET codigo=?, nome=?, descricao=?, cor=?, status=?, atualizado_em=? WHERE id=? AND empresa_id=?", (dados['codigo'],dados['nome'],dados['descricao'],dados['cor'],dados['status'],agora_empresa().isoformat(timespec='seconds'),centro_id,empresa_id))
        else:
            conn.execute("INSERT INTO centros_custo (empresa_id,codigo,nome,descricao,cor,status,atualizado_em) VALUES (?,?,?,?,?,?,?)", (empresa_id,dados['codigo'],dados['nome'],dados['descricao'],dados['cor'],dados['status'],agora_empresa().isoformat(timespec='seconds')))
        conn.commit()
    return ""


@app.route('/financeiro/centros-custo', methods=['GET','POST'])
def centros_custo() -> str | Response:
    if request.method == 'POST':
        erro = salvar_centro_custo_formulario()
        if erro:
            return redirect(url_for('centros_custo', erro=erro))
        return redirect(url_for('centros_custo', sucesso='Centro de custo salvo.'))
    return render_template('centros_custo.html', centros=listar_centros_custo(False))


@app.route('/financeiro/centros-custo/<int:centro_id>/editar', methods=['GET','POST'])
def editar_centro_custo(centro_id: int) -> str | Response:
    centro = buscar_centro_custo_por_id(centro_id)
    if not centro: return redirect(url_for('centros_custo'))
    if request.method == 'POST':
        erro = salvar_centro_custo_formulario(centro_id)
        if erro:
            return redirect(url_for('editar_centro_custo', centro_id=centro_id, erro=erro))
        return redirect(url_for('centros_custo', sucesso='Centro de custo atualizado.'))
    return render_template('centro_custo_editar.html', centro=centro)


@app.post('/financeiro/centros-custo/<int:centro_id>/excluir')
def excluir_centro_custo(centro_id: int) -> Response:
    with conectar_db() as conn:
        usos = conn.execute("SELECT COUNT(*) total FROM atividades_financeiras WHERE empresa_id=? AND centro_custo_id=?", (empresa_logada_id(),centro_id)).fetchone()['total']
        if usos: conn.execute("UPDATE centros_custo SET status='inativo' WHERE id=? AND empresa_id=?", (centro_id,empresa_logada_id()))
        else: conn.execute("DELETE FROM centros_custo WHERE id=? AND empresa_id=?", (centro_id,empresa_logada_id()))
        conn.commit()
    return redirect(url_for('centros_custo'))


@app.get('/financeiro/atividades')
def atividades_financeiras() -> str:
    atividades = listar_atividades_financeiras(False)
    for atividade in atividades:
        atividade['resumo'] = resumir_atividade_financeira(atividade['id'])
