def salvar_orcamento_adicionais_mao_obra_db(
    orcamento_id: int,
    adicionais: list[dict[str, Any]],
) -> None:
    empresa_id = empresa_logada_id()

    with conectar_db() as conn:
        conn.execute(
            """
            DELETE FROM orcamento_adicionais_mao_obra
            WHERE orcamento_id = ?
              AND empresa_id = ?
            """,
            (orcamento_id, empresa_id),
        )

        for adicional in adicionais:
            descricao = str(adicional.get("descricao") or adicional.get("tipo_nome") or "").strip()
            valor_total = _converter_valor_brl(
                adicional.get("custo")
                if adicional.get("custo") is not None
                else adicional.get("valor_total")
            )

            if not descricao or valor_total <= 0:
                continue

            conn.execute(
                """
                INSERT INTO orcamento_adicionais_mao_obra (
                    empresa_id,
                    orcamento_id,
                    tipo,
                    descricao,
                    funcionario_funcao,
                    pessoas,
                    quantidade,
                    unidade,
                    forma_calculo,
                    percentual,
                    valor_base,
                    valor_unitario,
                    valor_total,
                    exibir_cliente
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    orcamento_id,
                    str(adicional.get("tipo") or "especial"),
                    descricao,
                    str(adicional.get("funcionario_funcao") or ""),
                    _formatar_numero_estoque(_converter_valor_brl(adicional.get("pessoas")) or 1),
                    _formatar_numero_estoque(_converter_valor_brl(adicional.get("quantidade")) or 1),
                    str(adicional.get("unidade") or ""),
                    str(adicional.get("forma_calculo") or "fixo"),
                    _formatar_percentual_simples(_converter_valor_brl(adicional.get("percentual"))),
                    _formatar_moeda_brl(_converter_valor_brl(adicional.get("valor_base"))),
                    _formatar_moeda_brl(_converter_valor_brl(adicional.get("valor_unitario"))),
                    _formatar_moeda_brl(valor_total),
                    "sim" if str(adicional.get("exibir_cliente") or "nao").strip().lower() == "sim" else "nao",
                ),
            )

        conn.commit()


def normalizar_modo_apresentacao(valor: Any, padrao: str = "agrupado") -> str:
    modo = str(valor or "").strip().lower()
    if modo in ORCAMENTO_MODOS_APRESENTACAO_VALIDOS:
        return modo
    return padrao if padrao in ORCAMENTO_MODOS_APRESENTACAO_VALIDOS else "agrupado"


def normalizar_texto_multilinha(valor: Any) -> str:
    texto = str(valor or "")
    texto = texto.replace("\r\n", "\n").replace("\r", "\n").replace("\\n", "\n")

    linhas_normalizadas: list[str] = []
    linha_anterior_vazia = False

    for linha in texto.split("\n"):
        linha_limpa = re.sub(r"[ \t\f\v]+", " ", linha).strip()

        if not linha_limpa:
            if linhas_normalizadas and not linha_anterior_vazia:
                linhas_normalizadas.append("")
            linha_anterior_vazia = True
            continue

        linhas_normalizadas.append(linha_limpa)
        linha_anterior_vazia = False

    while linhas_normalizadas and not linhas_normalizadas[-1]:
        linhas_normalizadas.pop()

    return "\n".join(linhas_normalizadas).strip()


