def _limpar_item_escopo(valor: Any) -> str:
    texto = normalizar_texto_multilinha(valor)
    texto = re.sub(r"^\s*(?:[-–—•*▪◦]+|\d+[.)])\s*", "", texto)
    return re.sub(r"\s+", " ", texto).strip(" ;")


def _segmentar_servicos_escopo(texto: str) -> list[str]:
    padrao = "|".join(
        sorted((re.escape(item) for item in ORCAMENTO_ESCOPO_INICIOS_SERVICOS), key=len, reverse=True)
    )
    ocorrencias = list(re.finditer(rf"(?<!\w)(?:{padrao})\b", texto, re.IGNORECASE))

    if len(ocorrencias) < 2:
        return []

    itens: list[str] = []
    for indice, ocorrencia in enumerate(ocorrencias):
        fim = ocorrencias[indice + 1].start() if indice + 1 < len(ocorrencias) else len(texto)
        item = _limpar_item_escopo(texto[ocorrencia.start():fim])
        if item:
            itens.append(item)

    return itens


def _extrair_itens_escopo(texto: str, numero_secao: str) -> list[str]:
    texto_normalizado = normalizar_texto_multilinha(texto)
    if not texto_normalizado:
        return []

    linhas = [
        _limpar_item_escopo(linha)
        for linha in texto_normalizado.split("\n")
        if _limpar_item_escopo(linha)
    ]

    possui_marcadores = any(
        re.match(r"^\s*(?:[-–—•*▪◦]+|\d+[.)])\s+", linha)
        for linha in texto_normalizado.split("\n")
        if linha.strip()
    )

    if possui_marcadores or len(linhas) > 1:
        return linhas

    partes_pontuadas = [
        _limpar_item_escopo(parte)
        for parte in re.split(r"\s*(?:;|•|▪|\|)\s*", texto_normalizado)
        if _limpar_item_escopo(parte)
    ]
    if len(partes_pontuadas) > 1:
        return partes_pontuadas

    if numero_secao == "4":
        return _segmentar_servicos_escopo(texto_normalizado)

    return []


def _extrair_paragrafos_escopo(texto: str) -> list[str]:
    texto_normalizado = normalizar_texto_multilinha(texto)
    if not texto_normalizado:
        return []

    blocos = [
        re.sub(r"\s*\n\s*", " ", bloco).strip()
        for bloco in re.split(r"\n\s*\n+", texto_normalizado)
        if bloco.strip()
    ]

    if len(blocos) > 1:
        return blocos

    texto_unico = blocos[0] if blocos else texto_normalizado
    sentencas = [
        sentenca.strip()
        for sentenca in re.split(r"(?<=[.!?])\s+(?=[A-ZÁÀÂÃÉÊÍÓÔÕÚÇ0-9])", texto_unico)
        if sentenca.strip()
    ]

    if len(sentencas) <= 1:
        return [texto_unico]

    return sentencas


def formatar_escopo_orcamento(
    observacoes: Any,
    dados_gerador: dict[str, Any] | None = None,
) -> dict[str, Any]:
    dados = dados_gerador or {}
    escopo_salvo = normalizar_escopo_orcamento(dados.get("escopo"))
    observacoes_salvas = normalizar_escopo_orcamento(dados.get("observacoes_cliente"))

    texto_origem = escopo_salvo or normalizar_escopo_orcamento(observacoes)

    resultado: dict[str, Any] = {
        "secoes": [],
        "texto_livre": [],
        "observacoes_adicionais": _extrair_paragrafos_escopo(observacoes_salvas),
    }

    if not texto_origem:
        return resultado

    cabecalhos = list(ORCAMENTO_ESCOPO_CABECALHO_REGEX.finditer(texto_origem))

    if not cabecalhos:
        resultado["texto_livre"] = _extrair_paragrafos_escopo(texto_origem)
        return resultado

    texto_antes = texto_origem[:cabecalhos[0].start()].strip()
    if texto_antes:
        resultado["texto_livre"] = _extrair_paragrafos_escopo(texto_antes)

    secoes: list[dict[str, Any]] = []

    for indice, cabecalho in enumerate(cabecalhos):
        numero = str(cabecalho.group("numero"))
        titulo_secao = _titulo_secao_escopo(numero, cabecalho.group("titulo"))
        inicio_corpo = cabecalho.end()
        fim_corpo = cabecalhos[indice + 1].start() if indice + 1 < len(cabecalhos) else len(texto_origem)
        corpo = texto_origem[inicio_corpo:fim_corpo].strip(" \n:-")

        chave_titulo = _chave_titulo_escopo(titulo_secao)
        itens = (
            _extrair_itens_escopo(corpo, numero)
            if numero == "4" or "MATERIAIS" in chave_titulo
            else []
        )
        paragrafos = [] if itens else _extrair_paragrafos_escopo(corpo)

        secoes.append(
            {
                "numero": numero,
                "titulo": titulo_secao,
                "paragrafos": paragrafos,
                "itens": itens,
            }
        )

    resultado["secoes"] = secoes
    return resultado


def listar_orcamento_apresentacao_itens(orcamento_id: int) -> list[dict[str, Any]]:
    empresa_id = empresa_logada_id()
    with conectar_db() as conn:
        rows = conn.execute(
            """
            SELECT id, empresa_id, orcamento_id, descricao, detalhes, quantidade,
                   valor_unitario, subtotal, ordem, criado_em
            FROM orcamento_apresentacao_itens
            WHERE orcamento_id = ? AND empresa_id = ?
            ORDER BY ordem ASC, id ASC
            """,
            (orcamento_id, empresa_id),
        ).fetchall()
    return [dict(row) for row in rows]


def salvar_orcamento_apresentacao_itens_db(
    orcamento_id: int,
    itens: list[dict[str, Any]],
) -> None:
    empresa_id = empresa_logada_id()
    with conectar_db() as conn:
        conn.execute(
            "DELETE FROM orcamento_apresentacao_itens WHERE orcamento_id = ? AND empresa_id = ?",
            (orcamento_id, empresa_id),
        )
        ordem = 0
        for item in itens:
            descricao = str(item.get("descricao") or "").strip()
            subtotal = _converter_valor_brl(item.get("subtotal"))
            quantidade = _converter_valor_brl(item.get("quantidade")) or 1
            valor_unitario = _converter_valor_brl(item.get("valor_unitario"))
            if not descricao or subtotal <= 0:
                continue
            if valor_unitario <= 0:
                valor_unitario = subtotal / quantidade if quantidade > 0 else subtotal
            ordem += 1
            conn.execute(
                """
                INSERT INTO orcamento_apresentacao_itens (
                    empresa_id, orcamento_id, descricao, detalhes, quantidade,
                    valor_unitario, subtotal, ordem
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    orcamento_id,
                    descricao,
                    str(item.get("detalhes") or "").strip(),
                    _formatar_numero_estoque(quantidade),
                    _formatar_moeda_brl(valor_unitario),
                    _formatar_moeda_brl(subtotal),
                    ordem,
                ),
            )
        conn.commit()


def montar_orcamento_apresentacao_formulario() -> list[dict[str, str]]:
    descricoes = request.form.getlist("apresentacao_descricao")
    detalhes = request.form.getlist("apresentacao_detalhes")
    quantidades = request.form.getlist("apresentacao_quantidade")
    valores = request.form.getlist("apresentacao_valor_unitario")
    subtotais = request.form.getlist("apresentacao_subtotal")
    total = max(len(descricoes), len(detalhes), len(quantidades), len(valores), len(subtotais), 0)
    itens: list[dict[str, str]] = []
    for indice in range(total):
        itens.append(
            {
                "descricao": (descricoes[indice] if indice < len(descricoes) else "").strip(),
                "detalhes": (detalhes[indice] if indice < len(detalhes) else "").strip(),
                "quantidade": (quantidades[indice] if indice < len(quantidades) else "1").strip() or "1",
                "valor_unitario": (valores[indice] if indice < len(valores) else "").strip(),
                "subtotal": (subtotais[indice] if indice < len(subtotais) else "").strip(),
            }
        )
    return itens


def total_orcamento_apresentacao(itens: list[dict[str, Any]]) -> float:
    return round(
        sum(
            max(_converter_valor_brl(item.get("subtotal")), 0.0)
            for item in itens
            if str(item.get("descricao") or "").strip()
        ),
        2,
    )


def redistribuir_itens_orcamento_valor_final(
    itens: list[dict[str, str]],
    valor_final: float,
) -> tuple[list[dict[str, str]], float, float]:
    valor_final = max(round(float(valor_final or 0), 2), 0.0)
    itens_recalculados = [dict(item) for item in itens]
    indices_validos: list[int] = []
    bases: list[float] = []

    for indice, item in enumerate(itens_recalculados):
        if not str(item.get("descricao") or "").strip():
            continue

        quantidade = _converter_valor_brl(item.get("quantidade"))
        if quantidade <= 0:
            continue

        subtotal = _converter_valor_brl(item.get("subtotal"))
        if subtotal <= 0:
            subtotal = max(
                (quantidade * _converter_valor_brl(item.get("valor_unitario")))
                - _converter_valor_brl(item.get("desconto")),
                0.0,
            )

        indices_validos.append(indice)
        bases.append(subtotal if subtotal > 0 else 1.0)

    if not indices_validos or valor_final <= 0:
        return itens_recalculados, 0.0, 0.0

    valores_distribuidos = _gerador_alocar_total(valor_final, bases)
    total_produtos = 0.0
    total_servicos = 0.0

    for indice, subtotal_novo in zip(indices_validos, valores_distribuidos):
        item = itens_recalculados[indice]
        quantidade = max(_converter_valor_brl(item.get("quantidade")), 1.0)
        subtotal_decimal = Decimal(str(round(subtotal_novo, 2))).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )
        quantidade_decimal = Decimal(str(quantidade))
        valor_unitario_decimal = (subtotal_decimal / quantidade_decimal).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )
        subtotal_calculado = (valor_unitario_decimal * quantidade_decimal).quantize(
            Decimal("0.01"),
            rounding=ROUND_HALF_UP,
        )

        if subtotal_calculado < subtotal_decimal:
            valor_unitario_decimal += Decimal("0.01")
            subtotal_calculado = (valor_unitario_decimal * quantidade_decimal).quantize(
                Decimal("0.01"),
                rounding=ROUND_HALF_UP,
            )

        desconto_decimal = max(subtotal_calculado - subtotal_decimal, Decimal("0.00"))

        item["valor_unitario"] = _formatar_moeda_brl(float(valor_unitario_decimal))
        item["desconto"] = _formatar_moeda_brl(float(desconto_decimal))
        item["subtotal"] = _formatar_moeda_brl(float(subtotal_decimal))

        if str(item.get("tipo_item") or "produto") == "servico":
            total_servicos += float(subtotal_decimal)
        else:
            total_produtos += float(subtotal_decimal)

    return itens_recalculados, round(total_produtos, 2), round(total_servicos, 2)


def ajustar_itens_apresentacao_ao_total(
    itens: list[dict[str, Any]],
    valor_final: float,
    modo: str,
) -> list[dict[str, Any]]:
    validos = [
        dict(item)
        for item in itens
        if str(item.get("descricao") or "").strip()
    ]

    if not validos or valor_final <= 0:
        return []

    if modo == "global":
        primeiro = validos[0]
        primeiro["quantidade"] = "1"
        primeiro["valor_unitario"] = _formatar_moeda_brl(valor_final)
        primeiro["subtotal"] = _formatar_moeda_brl(valor_final)
        return [primeiro]

    bases = [
        max(_converter_valor_brl(item.get("subtotal")), 0.0)
        for item in validos
    ]
    if not any(base > 0 for base in bases):
        bases = [1.0] * len(validos)

    valores = _gerador_alocar_total(valor_final, bases)
    ajustados: list[dict[str, Any]] = []

    for item, valor in zip(validos, valores):
        item["quantidade"] = "1"
        item["valor_unitario"] = _formatar_moeda_brl(valor)
        item["subtotal"] = _formatar_moeda_brl(valor)
        ajustados.append(item)

    return ajustados


def atualizar_dados_gerador_apos_edicao_orcamento(
    orcamento_id: int,
    orcamento_atual: dict[str, Any],
    orcamento_novo: dict[str, Any],
) -> None:
    dados_anteriores = buscar_orcamento_gerador_dados(orcamento_id)
    if dados_anteriores is None:
        return

    valor_anterior = _converter_valor_brl(
        dados_anteriores.get("valor_escolhido")
        or orcamento_atual.get("valor_total")
    )
    valor_novo = _converter_valor_brl(orcamento_novo.get("valor_total"))
    custo_total = _converter_valor_brl(dados_anteriores.get("custo_total"))
    imposto_percentual = _converter_valor_brl(dados_anteriores.get("imposto_percentual"))
    administrativo_valor = _converter_valor_brl(dados_anteriores.get("administrativo_valor"))
    reserva_valor = _converter_valor_brl(dados_anteriores.get("reserva_valor"))
    lucro_bruto_estimado = valor_novo - custo_total
    margem_bruta_estimada = (lucro_bruto_estimado / valor_novo * 100) if valor_novo > 0 else 0.0
    impostos_estimados = valor_novo * (imposto_percentual / 100)
    despesas_indiretas_estimadas = administrativo_valor + reserva_valor
    lucro_liquido_estimado = lucro_bruto_estimado - impostos_estimados - despesas_indiretas_estimadas
    margem_liquida_estimada = (lucro_liquido_estimado / valor_novo * 100) if valor_novo > 0 else 0.0
    markup_custo_estimado = (lucro_bruto_estimado / custo_total * 100) if custo_total > 0 else 0.0
    lucro_estimado = lucro_liquido_estimado
    margem_estimada = margem_liquida_estimada

    dados_novos = dict(dados_anteriores)
    dados_novos.update(
        {
            "cliente": str(orcamento_novo.get("cliente") or ""),
            "responsavel": str(orcamento_novo.get("responsavel") or ""),
            "data": str(orcamento_novo.get("data") or ""),
            "prazo": str(orcamento_novo.get("prazo_entrega") or ""),
            "validade": str(orcamento_novo.get("validade") or ""),
            "forma_pagamento": str(orcamento_novo.get("forma_pagamento") or ""),
            "modo_apresentacao": normalizar_modo_apresentacao(
                orcamento_novo.get("modo_apresentacao"),
                "agrupado",
            ),
            "descricao_comercial": str(
                orcamento_novo.get("descricao_comercial") or ""
            ),
            "tipo_valor": "customizado",
            "valor_escolhido": valor_novo,
            "lucro_estimado": lucro_estimado,
            "margem_estimado": margem_estimada,
            "lucro_bruto_estimado": lucro_bruto_estimado,
            "margem_bruta_estimada": margem_bruta_estimada,
            "impostos_estimados": impostos_estimados,
            "despesas_indiretas_estimadas": despesas_indiretas_estimadas,
            "lucro_liquido_estimado": lucro_liquido_estimado,
            "margem_liquida_estimada": margem_liquida_estimada,
            "markup_custo_estimado": markup_custo_estimado,
        }
    )

    observacoes_anteriores = normalizar_texto_multilinha(
        orcamento_atual.get("observacoes")
    )
    observacoes_novas = normalizar_texto_multilinha(
        orcamento_novo.get("observacoes")
    )
    if observacoes_novas != observacoes_anteriores:
        dados_novos["escopo"] = normalizar_escopo_orcamento(observacoes_novas)
        dados_novos["observacoes_cliente"] = ""

    salvar_orcamento_gerador_dados_db(orcamento_id, dados_novos)

    if abs(valor_novo - valor_anterior) > 0.009:
        registrar_historico_gerador_db(
            orcamento_id,
            dados_anteriores,
            dados_novos,
        )


def montar_apresentacao_padrao_orcamento(
    orcamento: dict[str, Any],
    itens_internos: list[dict[str, Any]],
) -> list[dict[str, str]]:
    modo = normalizar_modo_apresentacao(orcamento.get("modo_apresentacao"), "agrupado")
    if modo == "detalhado":
        return []

    descricao_comercial = str(orcamento.get("descricao_comercial") or "").strip()
    total = _converter_valor_brl(orcamento.get("valor_total"))
    total_produtos = _converter_valor_brl(orcamento.get("total_produtos"))
    total_servicos = _converter_valor_brl(orcamento.get("total_servicos"))

    primeira_descricao = ""
    for item in itens_internos:
        if str(item.get("tipo_item") or "") == "servico" and str(item.get("detalhes") or "").strip():
            primeira_descricao = str(item.get("detalhes") or "").strip()
            break
        if not primeira_descricao and str(item.get("descricao") or "").strip():
            primeira_descricao = str(item.get("descricao") or "").strip()

    descricao_base = descricao_comercial or primeira_descricao or "Fornecimento e execução conforme escopo técnico"

    if modo == "global":
        return [{
            "descricao": descricao_base,
            "detalhes": "Valor global da proposta, contemplando os materiais, serviços e custos previstos no escopo.",
            "quantidade": "1",
            "valor_unitario": _formatar_moeda_brl(total),
            "subtotal": _formatar_moeda_brl(total),
        }]

    itens: list[dict[str, str]] = []
    if total_servicos > 0:
        itens.append({
            "descricao": descricao_base,
            "detalhes": "Serviços técnicos, mão de obra, mobilização e custos operacionais conforme escopo.",
            "quantidade": "1",
            "valor_unitario": _formatar_moeda_brl(total_servicos),
            "subtotal": _formatar_moeda_brl(total_servicos),
        })
    if total_produtos > 0:
        itens.append({
            "descricao": "Fornecimento de materiais e componentes necessários",
            "detalhes": "Materiais e componentes previstos para execução, sem abertura da composição interna.",
            "quantidade": "1",
            "valor_unitario": _formatar_moeda_brl(total_produtos),
            "subtotal": _formatar_moeda_brl(total_produtos),
        })
    if not itens and total > 0:
        itens.append({
            "descricao": descricao_base,
            "detalhes": "Proposta comercial conforme escopo técnico.",
            "quantidade": "1",
            "valor_unitario": _formatar_moeda_brl(total),
            "subtotal": _formatar_moeda_brl(total),
        })
    return itens


def sincronizar_apresentacao_orcamento_db(
    orcamento_id: int,
    orcamento: dict[str, Any],
    itens_internos: list[dict[str, Any]],
    itens_informados: list[dict[str, Any]] | None = None,
    preservar_descricoes: bool = False,
) -> None:
    modo = normalizar_modo_apresentacao(orcamento.get("modo_apresentacao"), "agrupado")
    if modo == "detalhado":
        salvar_orcamento_apresentacao_itens_db(orcamento_id, [])
        return

    validos = [
        item for item in (itens_informados or [])
        if str(item.get("descricao") or "").strip() and _converter_valor_brl(item.get("subtotal")) > 0
    ]
    if validos:
        valor_final = _converter_valor_brl(orcamento.get("valor_total"))
        salvar_orcamento_apresentacao_itens_db(
            orcamento_id,
            ajustar_itens_apresentacao_ao_total(validos, valor_final, modo),
        )
        return

    existentes = listar_orcamento_apresentacao_itens(orcamento_id) if preservar_descricoes else []
    total_novo = _converter_valor_brl(orcamento.get("valor_total"))
    if existentes and total_novo > 0:
        if modo == "global":
            primeiro = dict(existentes[0])
            primeiro["quantidade"] = "1"
            primeiro["valor_unitario"] = _formatar_moeda_brl(total_novo)
            primeiro["subtotal"] = _formatar_moeda_brl(total_novo)
            salvar_orcamento_apresentacao_itens_db(orcamento_id, [primeiro])
            return

        bases = [_converter_valor_brl(item.get("subtotal")) for item in existentes]
        valores = _gerador_alocar_total(total_novo, bases)
        ajustados: list[dict[str, Any]] = []
        for item, valor in zip(existentes, valores):
            novo = dict(item)
            novo["quantidade"] = "1"
            novo["valor_unitario"] = _formatar_moeda_brl(valor)
            novo["subtotal"] = _formatar_moeda_brl(valor)
            ajustados.append(novo)
        salvar_orcamento_apresentacao_itens_db(orcamento_id, ajustados)
        return

    salvar_orcamento_apresentacao_itens_db(
        orcamento_id,
        montar_apresentacao_padrao_orcamento(orcamento, itens_internos),
    )


def _json_lista_segura(valor: Any) -> list[dict[str, Any]]:
    if isinstance(valor, list):
        return [dict(item) for item in valor if isinstance(item, dict)]
    try:
        dados = json.loads(str(valor or "[]"))
    except (TypeError, ValueError, json.JSONDecodeError):
        return []
    return [dict(item) for item in dados if isinstance(item, dict)] if isinstance(dados, list) else []


def buscar_orcamento_gerador_dados(orcamento_id: int) -> dict[str, Any] | None:
    empresa_id = empresa_logada_id()
    with conectar_db() as conn:
        row = conn.execute(
            "SELECT * FROM orcamento_gerador_dados WHERE orcamento_id = ? AND empresa_id = ? LIMIT 1",
            (orcamento_id, empresa_id),
        ).fetchone()
    if row is None:
        return None
    dados = dict(row)
    dados["materiais"] = _json_lista_segura(dados.get("materiais_json"))
    dados["mao_obra"] = _json_lista_segura(dados.get("mao_obra_json"))
    dados["adicionais_mao_obra"] = _json_lista_segura(dados.get("adicionais_json"))
    dados["custos_adicionais"] = _json_lista_segura(dados.get("custos_json"))
    return dados


def salvar_orcamento_gerador_dados_db(orcamento_id: int, dados: dict[str, Any]) -> None:
    empresa_id = empresa_logada_id()
    campos = {
        "cliente": str(dados.get("cliente") or ""),
        "responsavel": str(dados.get("responsavel") or ""),
        "tipo_servico": str(dados.get("tipo_servico") or ""),
        "data": str(dados.get("data") or ""),
        "prazo": str(dados.get("prazo") or ""),
        "validade": str(dados.get("validade") or ""),
        "forma_pagamento": str(dados.get("forma_pagamento") or ""),
        "resumo_servico": str(dados.get("resumo_servico") or ""),
        "escopo": normalizar_escopo_orcamento(dados.get("escopo")),
        "observacoes_cliente": str(dados.get("observacoes_cliente") or ""),
        "modo_apresentacao": normalizar_modo_apresentacao(dados.get("modo_apresentacao"), "agrupado"),
        "descricao_comercial": str(dados.get("descricao_comercial") or ""),
        "materiais_json": json.dumps(list(dados.get("materiais") or []), ensure_ascii=False),
        "mao_obra_json": json.dumps(list(dados.get("mao_obra") or []), ensure_ascii=False),
        "adicionais_json": json.dumps(list(dados.get("adicionais_mao_obra") or []), ensure_ascii=False),
        "custos_json": json.dumps(list(dados.get("custos_adicionais") or []), ensure_ascii=False),
    }
    numericos = [
        "margem_material", "margem_mao_obra", "margem_custos", "imposto_percentual",
        "administrativo_percentual", "reserva_percentual", "custo_material", "custo_mao_obra",
        "custo_adicionais_mao_obra", "custo_adicional", "custo_total", "venda_material",
        "venda_mao_obra", "venda_adicionais_mao_obra", "venda_custos", "administrativo_valor",
        "reserva_valor", "valor_minimo", "valor_recomendado", "valor_ideal", "valor_escolhido",
        "lucro_estimado", "margem_estimado", "lucro_bruto_estimado",
        "margem_bruta_estimada", "impostos_estimados", "despesas_indiretas_estimadas",
        "lucro_liquido_estimado", "margem_liquida_estimada", "markup_custo_estimado",
    ]
    for campo in numericos:
        campos[campo] = str(float(dados.get(campo) or 0))
    campos["tipo_valor"] = str(dados.get("tipo_valor") or "recomendado")

    nomes = list(campos.keys())
    colunas = ", ".join(nomes)
    placeholders = ", ".join("?" for _ in nomes)
    atualizacoes = ", ".join(f"{nome} = excluded.{nome}" for nome in nomes)
    valores = [campos[nome] for nome in nomes]

    with conectar_db() as conn:
        conn.execute(
            f"""
            INSERT INTO orcamento_gerador_dados (
                empresa_id, orcamento_id, {colunas}, atualizado_em
            ) VALUES (?, ?, {placeholders}, ?)
            ON CONFLICT(orcamento_id) DO UPDATE SET
                empresa_id = excluded.empresa_id,
                {atualizacoes},
                atualizado_em = excluded.atualizado_em
            """,
            [empresa_id, orcamento_id, *valores, agora_empresa().isoformat(timespec="seconds")],
        )
        conn.commit()


def registrar_historico_gerador_db(
    orcamento_id: int,
    dados_anteriores: dict[str, Any] | None,
    dados_novos: dict[str, Any],
) -> None:
    empresa_id = empresa_logada_id()
    anterior = dados_anteriores or {}
    valor_anterior = _converter_valor_brl(anterior.get("valor_escolhido"))
    valor_novo = _converter_valor_brl(dados_novos.get("valor_escolhido"))
    margem_anterior = _converter_valor_brl(anterior.get("margem_estimado"))
    margem_nova = _converter_valor_brl(dados_novos.get("margem_estimado"))
    usuario = usuario_logado() or {}
    with conectar_db() as conn:
        conn.execute(
            """
            INSERT INTO orcamento_gerador_historico (
                empresa_id, orcamento_id, valor_anterior, valor_novo,
                margem_anterior, margem_nova, diferenca_valor,
                dados_anteriores_json, dados_novos_json, responsavel
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                orcamento_id,
                _formatar_moeda_brl(valor_anterior),
                _formatar_moeda_brl(valor_novo),
                _formatar_percentual_simples(margem_anterior),
                _formatar_percentual_simples(margem_nova),
                _formatar_moeda_brl(valor_novo - valor_anterior),
                json.dumps(anterior, ensure_ascii=False, default=str),
                json.dumps(dados_novos, ensure_ascii=False, default=str),
                str(usuario.get("nome") or "Usuário"),
            ),
        )
        conn.commit()


def listar_historico_gerador(orcamento_id: int) -> list[dict[str, Any]]:
    empresa_id = empresa_logada_id()
    with conectar_db() as conn:
        rows = conn.execute(
            """
            SELECT id, orcamento_id, valor_anterior, valor_novo, margem_anterior,
                   margem_nova, diferenca_valor, dados_anteriores_json, dados_novos_json,
                   responsavel, criado_em
            FROM orcamento_gerador_historico
            WHERE orcamento_id = ? AND empresa_id = ?
            ORDER BY id DESC
            """,
            (orcamento_id, empresa_id),
        ).fetchall()
    resultado = [dict(row) for row in rows]
    for item in resultado:
        item["criado_em"] = formatar_data_hora_br(item.get("criado_em"))
        try:
            anteriores = json.loads(str(item.get("dados_anteriores_json") or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError):
            anteriores = {}
        try:
            novos = json.loads(str(item.get("dados_novos_json") or "{}"))
        except (TypeError, ValueError, json.JSONDecodeError):
            novos = {}
        lucro_anterior = _converter_valor_brl(anteriores.get("lucro_liquido_estimado") or anteriores.get("lucro_estimado"))
        lucro_novo = _converter_valor_brl(novos.get("lucro_liquido_estimado") or novos.get("lucro_estimado"))
        item["lucro_liquido_anterior"] = _formatar_moeda_brl(lucro_anterior)
        item["lucro_liquido_novo"] = _formatar_moeda_brl(lucro_novo)
        item.pop("dados_anteriores_json", None)
        item.pop("dados_novos_json", None)
    return resultado


def atualizar_orcamento_db(
    orcamento_id: int,
    orcamento: dict[str, str],
    itens: list[dict[str, str]],
    *,
    versao_esperada: int | None = None,
) -> bool:
    empresa_id = empresa_logada_id()
    atualizado_em = agora_empresa().isoformat(timespec="seconds")
    condicao_versao = ""
    parametros: list[Any] = [
        orcamento["numero"],
        orcamento["cliente"],
        orcamento["responsavel"],
        orcamento["data"],
        orcamento["prazo_entrega"],
        orcamento["validade"],
        orcamento["canal_venda"],
        orcamento["centro_custo"],
        orcamento.get("centro_custo_id") or None,
        orcamento["introducao"],
        orcamento["tipo"],
        orcamento["status"],
        orcamento["total_produtos"],
        orcamento["total_servicos"],
        orcamento["desconto_valor"],
        orcamento["desconto_percentual"],
        orcamento["valor_total"],
        orcamento["forma_pagamento"],
        orcamento["observacoes"],
        orcamento["observacoes_internas"],
        str(orcamento.get("origem") or "manual"),
        normalizar_modo_apresentacao(
            orcamento.get("modo_apresentacao"),
            "agrupado",
        ),
        str(orcamento.get("descricao_comercial") or ""),
        atualizado_em,
        orcamento_id,
        empresa_id,
    ]

    if versao_esperada is not None:
        condicao_versao = " AND COALESCE(versao, 1) = ?"
        parametros.append(int(versao_esperada))

    with conectar_db() as conn:
        conn.execute("BEGIN IMMEDIATE")
        cursor = conn.execute(
            f"""
            UPDATE orcamentos
            SET
                numero = ?,
                cliente = ?,
                responsavel = ?,
                data = ?,
                prazo_entrega = ?,
                validade = ?,
                canal_venda = ?,
                centro_custo = ?,
                centro_custo_id = ?,
                introducao = ?,
                tipo = ?,
                status = ?,
                total_produtos = ?,
                total_servicos = ?,
                desconto_valor = ?,
                desconto_percentual = ?,
                valor_total = ?,
                forma_pagamento = ?,
                observacoes = ?,
                observacoes_internas = ?,
                origem = ?,
                modo_apresentacao = ?,
                descricao_comercial = ?,
                versao = COALESCE(versao, 1) + 1,
                atualizado_em = ?
            WHERE id = ?
              AND empresa_id = ?
              {condicao_versao}
            """,
            tuple(parametros),
        )

        if cursor.rowcount != 1:
            conn.rollback()
            return False

        conn.execute(
            """
            DELETE FROM orcamento_itens
            WHERE orcamento_id = ?
              AND empresa_id = ?
            """,
            (orcamento_id, empresa_id),
        )

        for item in itens:
            if not item["descricao"]:
                continue

            conn.execute(
                """
                INSERT INTO orcamento_itens (
                    empresa_id,
                    orcamento_id,
                    tipo_item,
                    descricao,
                    detalhes,
                    quantidade,
                    valor_unitario,
                    desconto,
                    subtotal
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    orcamento_id,
                    item["tipo_item"],
                    item["descricao"],
                    item["detalhes"],
                    item["quantidade"],
                    item["valor_unitario"],
                    item["desconto"],
                    item["subtotal"],
                ),
            )

        conn.commit()

    garantir_atividade_orcamento(orcamento_id)
    return True


def excluir_orcamento_db(orcamento_id: int) -> None:
    empresa_id = empresa_logada_id()
    if aplicar_exclusao_logica_configurada("orcamentos", orcamento_id, "cancelado"):
        return

    with conectar_db() as conn:
        for tabela in (
            "orcamento_gerador_historico",
            "orcamento_gerador_dados",
            "orcamento_apresentacao_itens",
            "orcamento_adicionais_mao_obra",
            "orcamento_itens",
        ):
            conn.execute(
                f"DELETE FROM {tabela} WHERE orcamento_id = ? AND empresa_id = ?",
                (orcamento_id, empresa_id),
            )
        atividade = conn.execute(
            "SELECT id FROM atividades_financeiras WHERE empresa_id = ? AND origem = 'orcamento' AND origem_id = ?",
            (empresa_id, orcamento_id),
        ).fetchone()
        if atividade is not None:
            atividade_id = int(atividade["id"])
            conn.execute("UPDATE financeiro_titulos SET atividade_financeira_id = NULL WHERE empresa_id = ? AND atividade_financeira_id = ?", (empresa_id, atividade_id))
            conn.execute("UPDATE vendas SET atividade_financeira_id = NULL WHERE empresa_id = ? AND atividade_financeira_id = ?", (empresa_id, atividade_id))
            conn.execute("UPDATE ordens_servico SET atividade_financeira_id = NULL WHERE empresa_id = ? AND atividade_financeira_id = ?", (empresa_id, atividade_id))
            conn.execute("DELETE FROM atividades_financeiras WHERE id = ? AND empresa_id = ?", (atividade_id, empresa_id))
        conn.execute(
            "DELETE FROM orcamentos WHERE id = ? AND empresa_id = ?",
            (orcamento_id, empresa_id),
        )
        conn.commit()


