def atualizar_venda_db(venda_id: int, venda: dict[str, str], itens: list[dict[str, str]]) -> None:
    empresa_id = empresa_logada_id()
    venda = normalizar_vinculos_financeiros_documento(venda)
    venda["status"] = normalizar_status_venda(venda.get("status"))

    with conectar_db() as conn:
        conn.execute(
            """
            UPDATE vendas
            SET
                cliente = ?,
                responsavel = ?,
                data = ?,
                prazo_entrega = ?,
                canal_venda = ?,
                centro_custo = ?,
                centro_custo_id = ?,
                atividade_financeira_id = ?,
                tipo = ?,
                status = ?,
                total_produtos = ?,
                total_servicos = ?,
                desconto_valor = ?,
                desconto_percentual = ?,
                valor_total = ?,
                forma_pagamento = ?,
                condicao_pagamento = ?,
                meio_pagamento = ?,
                valor_entrada = ?,
                meio_pagamento_entrada = ?,
                data_entrada = ?,
                quantidade_parcelas = ?,
                primeiro_vencimento = ?,
                intervalo_parcelas = ?,
                observacoes = ?,
                observacoes_internas = ?
            WHERE id = ?
              AND empresa_id = ?
            """,
            (
                venda["cliente"],
                venda["responsavel"],
                venda["data"],
                venda["prazo_entrega"],
                venda["canal_venda"],
                venda["centro_custo"],
                venda.get("centro_custo_id") or None,
                venda.get("atividade_financeira_id") or None,
                venda["tipo"],
                venda["status"],
                venda["total_produtos"],
                venda["total_servicos"],
                venda["desconto_valor"],
                venda["desconto_percentual"],
                venda["valor_total"],
                venda["forma_pagamento"],
                venda["condicao_pagamento"],
                venda["meio_pagamento"],
                venda["valor_entrada"],
                venda["meio_pagamento_entrada"],
                venda["data_entrada"],
                venda["quantidade_parcelas"],
                venda["primeiro_vencimento"],
                venda["intervalo_parcelas"],
                venda["observacoes"],
                venda["observacoes_internas"],
                venda_id,
                empresa_id,
            ),
        )

        conn.execute(
            """
            DELETE FROM venda_itens
            WHERE venda_id = ?
              AND empresa_id = ?
            """,
            (venda_id, empresa_id),
        )

        for item in itens:
            if not item["descricao"]:
                continue

            conn.execute(
                """
                INSERT INTO venda_itens (
                    empresa_id,
                    venda_id,
                    tipo_item,
                    descricao,
                    detalhes,
                    quantidade,
                    valor_unitario,
                    desconto,
                    subtotal
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    venda_id,
                    item["tipo_item"],
                    item["descricao"],
                    item["detalhes"],
                    item["quantidade"],
                    item["valor_unitario"],
                    item["desconto"],
                    item["subtotal"],
                ),
            )

        conn.commit()

def excluir_venda_db(venda_id: int) -> None:
    empresa_id = empresa_logada_id()
    if aplicar_exclusao_logica_configurada("vendas", venda_id, "excluida"):
        return

    with conectar_db() as conn:
        conn.execute(
            """
            DELETE FROM venda_itens
            WHERE venda_id = ?
              AND empresa_id = ?
            """,
            (venda_id, empresa_id),
        )
        conn.execute(
            """
            DELETE FROM vendas
            WHERE id = ?
              AND empresa_id = ?
            """,
            (venda_id, empresa_id),
        )
        conn.commit()

