def _converter_inteiro_positivo(valor: Any) -> int | None:
    try:
        numero = int(str(valor or "").strip())
    except ValueError:
        return None

    if numero <= 0:
        return None

    return numero


def montar_itens_acompanhamento_formulario(formulario: Any) -> dict[str, list[dict[str, str]]]:
    equipe: list[dict[str, str]] = []
    materiais: list[dict[str, str]] = []
    servicos: list[dict[str, str]] = []

    equipe_ids = formulario.getlist("equipe_funcionario_id[]")
    equipe_horas = formulario.getlist("equipe_horas[]")
    equipe_observacoes = formulario.getlist("equipe_observacoes[]")

    for indice, funcionario_id in enumerate(equipe_ids):
        funcionario_id_texto = str(funcionario_id or "").strip()

        if not funcionario_id_texto:
            continue

        equipe.append(
            {
                "funcionario_id": funcionario_id_texto,
                "horas": str(equipe_horas[indice] if indice < len(equipe_horas) else "").strip(),
                "observacoes": str(equipe_observacoes[indice] if indice < len(equipe_observacoes) else "").strip(),
            }
        )

    material_ids = formulario.getlist("material_produto_id[]")
    material_quantidades = formulario.getlist("material_quantidade[]")
    material_observacoes = formulario.getlist("material_observacoes[]")

    for indice, produto_id in enumerate(material_ids):
        produto_id_texto = str(produto_id or "").strip()

        if not produto_id_texto:
            continue

        materiais.append(
            {
                "produto_id": produto_id_texto,
                "quantidade": str(material_quantidades[indice] if indice < len(material_quantidades) else "").strip(),
                "observacoes": str(material_observacoes[indice] if indice < len(material_observacoes) else "").strip(),
            }
        )

    servico_ids = formulario.getlist("servico_id[]")
    servico_quantidades = formulario.getlist("servico_quantidade[]")
    servico_observacoes = formulario.getlist("servico_observacoes[]")

    for indice, servico_id in enumerate(servico_ids):
        servico_id_texto = str(servico_id or "").strip()

        if not servico_id_texto:
            continue

        servicos.append(
            {
                "servico_id": servico_id_texto,
                "quantidade": str(servico_quantidades[indice] if indice < len(servico_quantidades) else "").strip(),
                "observacoes": str(servico_observacoes[indice] if indice < len(servico_observacoes) else "").strip(),
            }
        )

    return {
        "equipe": equipe,
        "materiais": materiais,
        "servicos": servicos,
    }


def salvar_itens_acompanhamento_os(
    conn: sqlite3.Connection,
    acompanhamento: dict[str, Any],
    itens: dict[str, list[dict[str, str]]],
) -> None:
    acompanhamento_id = int(acompanhamento.get("id") or 0)
    empresa_id = int(acompanhamento.get("empresa_id") or 0)

    if acompanhamento_id <= 0 or empresa_id <= 0:
        return

    conn.execute(
        "DELETE FROM os_acompanhamento_equipe WHERE acompanhamento_id = ? AND empresa_id = ?",
        (acompanhamento_id, empresa_id),
    )
    conn.execute(
        "DELETE FROM os_acompanhamento_materiais WHERE acompanhamento_id = ? AND empresa_id = ?",
        (acompanhamento_id, empresa_id),
    )
    conn.execute(
        "DELETE FROM os_acompanhamento_servicos WHERE acompanhamento_id = ? AND empresa_id = ?",
        (acompanhamento_id, empresa_id),
    )

    for item in itens.get("equipe", []):
        funcionario_id = _converter_inteiro_positivo(item.get("funcionario_id"))

        if funcionario_id is None:
            continue

        funcionario = conn.execute(
            """
            SELECT id, nome, cargo
            FROM funcionarios
            WHERE id = ?
              AND empresa_id = ?
            LIMIT 1
            """,
            (funcionario_id, empresa_id),
        ).fetchone()

        if funcionario is None:
            continue

        conn.execute(
            """
            INSERT INTO os_acompanhamento_equipe (
                empresa_id,
                acompanhamento_id,
                funcionario_id,
                nome,
                cargo,
                horas,
                observacoes
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                acompanhamento_id,
                funcionario_id,
                str(funcionario["nome"] or ""),
                str(funcionario["cargo"] or ""),
                str(item.get("horas") or ""),
                str(item.get("observacoes") or ""),
            ),
        )

    for item in itens.get("materiais", []):
        produto_id = _converter_inteiro_positivo(item.get("produto_id"))

        if produto_id is None:
            continue

        produto = conn.execute(
            """
            SELECT id, nome, unidade
            FROM produtos
            WHERE id = ?
              AND empresa_id = ?
            LIMIT 1
            """,
            (produto_id, empresa_id),
        ).fetchone()

        if produto is None:
            continue

        conn.execute(
            """
            INSERT INTO os_acompanhamento_materiais (
                empresa_id,
                acompanhamento_id,
                produto_id,
                nome,
                unidade,
                quantidade,
                observacoes
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                acompanhamento_id,
                produto_id,
                str(produto["nome"] or ""),
                str(produto["unidade"] or ""),
                str(item.get("quantidade") or ""),
                str(item.get("observacoes") or ""),
            ),
        )

    for item in itens.get("servicos", []):
        servico_id = _converter_inteiro_positivo(item.get("servico_id"))

        if servico_id is None:
            continue

        servico = conn.execute(
            """
            SELECT id, nome
            FROM servicos
            WHERE id = ?
              AND empresa_id = ?
            LIMIT 1
            """,
            (servico_id, empresa_id),
        ).fetchone()

        if servico is None:
            continue

        conn.execute(
            """
            INSERT INTO os_acompanhamento_servicos (
                empresa_id,
                acompanhamento_id,
                servico_id,
                nome,
                quantidade,
                observacoes
            ) VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                acompanhamento_id,
                servico_id,
                str(servico["nome"] or ""),
                str(item.get("quantidade") or ""),
                str(item.get("observacoes") or ""),
            ),
        )



def buscar_acompanhamento_ordem_servico_interno(
    ordem_servico_id: int,
    acompanhamento_id: int,
) -> dict[str, Any] | None:
    empresa_id = empresa_logada_id()

    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT *
            FROM os_acompanhamentos
            WHERE id = ?
              AND ordem_servico_id = ?
              AND empresa_id = ?
            LIMIT 1
            """,
            (acompanhamento_id, ordem_servico_id, empresa_id),
        ).fetchone()

    return dict(row) if row else None


def atualizar_acompanhamento_ordem_servico_interno(
    ordem_servico_id: int,
    acompanhamento_id: int,
    dados: dict[str, str],
    itens: dict[str, list[dict[str, str]]],
) -> tuple[bool, str]:
    acompanhamento = buscar_acompanhamento_ordem_servico_interno(
        ordem_servico_id,
        acompanhamento_id,
    )
    if acompanhamento is None:
        return False, "Acompanhamento diário não encontrado nesta OS."

    data_acompanhamento = str(dados.get("data_acompanhamento") or "").strip()
    if not data_acompanhamento:
        return False, "Informe a data do acompanhamento diário."

    try:
        datetime.strptime(data_acompanhamento, "%Y-%m-%d")
    except ValueError:
        return False, "Informe uma data válida para o acompanhamento diário."

    status_dia = str(dados.get("status_dia") or "registrado").strip().lower()
    status_validos = {"aberto", "registrado", "finalizado"}
    if status_dia not in status_validos:
        return False, "Selecione um status válido para o acompanhamento diário."

    status_link = str(dados.get("status_link") or "ativo").strip().lower()
    if status_link not in {"ativo", "inativo"}:
        status_link = "ativo"

    agora_iso = agora_empresa().isoformat(timespec="seconds")
    finalizado_em = str(acompanhamento.get("finalizado_em") or "").strip()
    if status_dia == "aberto":
        finalizado_em = ""
    elif not finalizado_em:
        finalizado_em = agora_iso

    try:
        with conectar_db() as conn:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                """
                SELECT id, empresa_id, ordem_servico_id
                FROM os_acompanhamentos
                WHERE id = ?
                  AND ordem_servico_id = ?
                  AND empresa_id = ?
                LIMIT 1
                """,
                (acompanhamento_id, ordem_servico_id, empresa_logada_id()),
            ).fetchone()
            if row is None:
                conn.rollback()
                return False, "O acompanhamento foi removido ou pertence a outra OS."

            acompanhamento_para_itens = dict(row)
            salvar_itens_acompanhamento_os(conn, acompanhamento_para_itens, itens)

            cursor = conn.execute(
                """
                UPDATE os_acompanhamentos
                SET
                    data_acompanhamento = ?,
                    responsavel = ?,
                    status_link = ?,
                    status_dia = ?,
                    atividades_previstas = ?,
                    atividades_executadas = ?,
                    observacoes = ?,
                    finalizado_em = ?,
                    atualizado_em = ?
                WHERE id = ?
                  AND ordem_servico_id = ?
                  AND empresa_id = ?
                """,
                (
                    data_acompanhamento,
                    str(dados.get("responsavel") or "").strip(),
                    status_link,
                    status_dia,
                    str(dados.get("atividades_previstas") or "").strip(),
                    str(dados.get("atividades_executadas") or "").strip(),
                    str(dados.get("observacoes") or "").strip(),
                    finalizado_em,
                    agora_iso,
                    acompanhamento_id,
                    ordem_servico_id,
                    empresa_logada_id(),
                ),
            )
            if cursor.rowcount != 1:
                conn.rollback()
                return False, "Não foi possível atualizar o acompanhamento diário."

            conn.commit()
    except sqlite3.Error:
        return False, "Não foi possível salvar o acompanhamento diário. Tente novamente."

    return True, "Acompanhamento diário atualizado com sucesso."


def excluir_acompanhamento_ordem_servico_interno(
    ordem_servico_id: int,
    acompanhamento_id: int,
) -> tuple[bool, str]:
    acompanhamento = buscar_acompanhamento_ordem_servico_interno(
        ordem_servico_id,
        acompanhamento_id,
    )
    if acompanhamento is None:
        return False, "Acompanhamento diário não encontrado nesta OS."

    empresa_id = empresa_logada_id()

    try:
        with conectar_db() as conn:
            conn.execute("BEGIN IMMEDIATE")
            for tabela in (
                "os_acompanhamento_equipe",
                "os_acompanhamento_materiais",
                "os_acompanhamento_servicos",
            ):
                conn.execute(
                    f"DELETE FROM {tabela} WHERE acompanhamento_id = ? AND empresa_id = ?",
                    (acompanhamento_id, empresa_id),
                )

            cursor = conn.execute(
                """
                DELETE FROM os_acompanhamentos
                WHERE id = ?
                  AND ordem_servico_id = ?
                  AND empresa_id = ?
                """,
                (acompanhamento_id, ordem_servico_id, empresa_id),
            )
            if cursor.rowcount != 1:
                conn.rollback()
                return False, "Não foi possível excluir o acompanhamento diário."

            conn.commit()
    except sqlite3.Error:
        return False, "Não foi possível excluir o acompanhamento diário. Tente novamente."

    return True, "Acompanhamento diário excluído com sucesso."


