def listar_usuarios_configuracoes() -> list[dict[str, Any]]:
    with conectar_db() as conn:
        rows = conn.execute(
            """
            SELECT
                u.id,
                u.empresa_id,
                u.funcionario_id,
                u.nome,
                u.email,
                u.perfil,
                u.permissoes_json,
                u.status,
                u.ultimo_login,
                u.atualizado_em,
                u.criado_em,
                f.nome AS funcionario_nome,
                f.cargo AS funcionario_cargo
            FROM usuarios u
            LEFT JOIN funcionarios f
              ON f.id = u.funcionario_id
             AND f.empresa_id = u.empresa_id
            WHERE u.empresa_id = ?
            ORDER BY u.id ASC
            """,
            (empresa_logada_id(),),
        ).fetchall()

    usuarios = [dict(row) for row in rows]
    for usuario in usuarios:
        usuario["perfil_rotulo"] = rotulo_perfil_usuario(usuario.get("perfil"))
    return usuarios


def listar_lojas_configuracoes() -> list[dict[str, Any]]:
    with conectar_db() as conn:
        rows = conn.execute(
            """
            SELECT
                id,
                empresa_id,
                nome,
                tipo,
                cidade,
                status,
                criado_em
            FROM lojas
            WHERE empresa_id = ?
            ORDER BY id ASC
            """,
            (empresa_logada_id(),),
        ).fetchall()

    return [dict(row) for row in rows]


