def _resolver_registro_configuravel(mapeamento: dict[str, Any]) -> int | None:
    id_arg = str(mapeamento.get("id_arg") or "")
    if id_arg:
        valor = (request.view_args or {}).get(id_arg)
        return int(valor) if str(valor or "").isdigit() else None

    condicoes = ["empresa_id = ?"]
    parametros: list[Any] = [empresa_logada_id()]
    for coluna, campo_formulario in dict(mapeamento.get("campos") or {}).items():
        valor = str(request.form.get(campo_formulario) or "").strip()
        if not valor:
            continue
        if not re.fullmatch(r"[a-z_][a-z0-9_]*", str(coluna)):
            continue
        condicoes.append(f"COALESCE({coluna}, '') = ?")
        parametros.append(valor)
    for coluna, valor in dict(mapeamento.get("fixos") or {}).items():
        if not re.fullmatch(r"[a-z_][a-z0-9_]*", str(coluna)):
            continue
        condicoes.append(f"COALESCE({coluna}, '') = ?")
        parametros.append(str(valor))
    tabela = str(mapeamento.get("tabela") or "")
    if not re.fullmatch(r"[a-z_][a-z0-9_]*", tabela):
        return None
    with conectar_db() as conn:
        row = conn.execute(
            f"SELECT id FROM {tabela} WHERE {' AND '.join(condicoes)} ORDER BY id DESC LIMIT 1",
            parametros,
        ).fetchone()
    return int(row["id"]) if row is not None else None


@app.after_request
def persistir_campos_configuraveis_apos_requisicao(response: Response) -> Response:
    if request.method != "POST" or response.status_code < 300 or response.status_code >= 400:
        return response
    if "erro=" in str(response.headers.get("Location") or "").lower():
        return response
    mapeamento = CONFIGURACOES_ENTIDADES_ENDPOINTS.get(str(request.endpoint or ""))
    if not mapeamento:
        return response
    dados = capturar_dados_configuraveis_formulario(str(mapeamento["modulo"]))
    if not dados:
        return response
    try:
        registro_id = _resolver_registro_configuravel(mapeamento)
        if registro_id:
            salvar_dados_configuraveis_entidade(
                str(mapeamento["modulo"]),
                str(mapeamento["entidade"]),
                registro_id,
                dados,
            )
    except sqlite3.Error:
        app.logger.exception("Falha ao salvar campos configuráveis da entidade.")
    return response


def redirecionar_configuracoes_usuarios(
    sucesso: str = "",
    erro: str = "",
) -> Response:
    parametros = {
        chave: valor
        for chave, valor in {"sucesso": sucesso, "erro": erro}.items()
        if str(valor or "").strip()
    }
    destino = "/configuracoes/usuarios"
    if parametros:
        destino = f"{destino}?{urllib.parse.urlencode(parametros)}"
    return redirect(destino)



def buscar_usuario_configuracoes_por_id(usuario_id: int) -> dict[str, Any] | None:
    empresa_id = empresa_logada_id()

    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT
                u.id,
                u.empresa_id,
                u.funcionario_id,
                u.nome,
                u.email,
                u.perfil,
                u.permissoes_json,
                u.status,
                u.sessao_versao,
                u.ultimo_login,
                u.atualizado_em,
                u.criado_em,
                f.nome AS funcionario_nome
            FROM usuarios u
            LEFT JOIN funcionarios f
              ON f.id = u.funcionario_id
             AND f.empresa_id = u.empresa_id
            WHERE u.id = ?
              AND u.empresa_id = ?
            LIMIT 1
            """,
            (usuario_id, empresa_id),
        ).fetchone()

    if row is None:
        return None

    usuario = dict(row)
    usuario["perfil"] = normalizar_perfil_usuario(usuario.get("perfil"))
    usuario["perfil_rotulo"] = rotulo_perfil_usuario(usuario.get("perfil"))
    return usuario


def listar_funcionarios_vinculo_usuario() -> list[dict[str, Any]]:
    empresa_id = empresa_logada_id()
    with conectar_db() as conn:
        rows = conn.execute(
            """
            SELECT
                f.id,
                f.nome,
                f.cargo,
                f.status,
                u.id AS usuario_id
            FROM funcionarios f
            LEFT JOIN usuarios u
              ON u.funcionario_id = f.id
             AND u.empresa_id = f.empresa_id
            WHERE f.empresa_id = ?
              AND LOWER(COALESCE(f.status, 'ativo')) <> 'excluido'
            ORDER BY f.nome ASC, f.id ASC
            """,
            (empresa_id,),
        ).fetchall()
    return [dict(row) for row in rows]


def perfis_disponiveis_para_gestao() -> dict[str, dict[str, str]]:
    perfis = dict(GESTFLOW_PERFIS_USUARIO)
    if not usuario_logado_eh_admin_sistema():
        perfis.pop("super_admin", None)
    return perfis


def permissoes_selecionadas_usuario(usuario: dict[str, Any]) -> set[str]:
    permissoes = permissoes_efetivas_usuario(usuario)
    return {
        f"{modulo}:{acao}"
        for modulo, acoes in permissoes.items()
        for acao in acoes
    }


def montar_permissoes_usuario_formulario(perfil: str) -> str:
    perfil_normalizado = normalizar_perfil_usuario(perfil)
    if perfil_normalizado in {"super_admin", "administrador"}:
        return ""

    selecionadas = {
        str(valor or "").strip()
        for valor in request.form.getlist("permissoes")
        if str(valor or "").strip()
    }

    modulos_validos = {item["codigo"] for item in GESTFLOW_MODULOS_PERMISSOES}
    permissoes: dict[str, set[str]] = {}

    for valor in selecionadas:
        if ":" not in valor:
            continue
        modulo, acao = valor.split(":", 1)
        modulo = modulo.strip()
        acao = acao.strip()
        if modulo not in modulos_validos or acao not in GESTFLOW_ACOES_PERMISSAO_CODIGOS:
            continue
        permissoes.setdefault(modulo, set()).add(acao)

    return serializar_permissoes_usuario(permissoes)


def montar_usuario_configuracoes_formulario() -> dict[str, Any]:
    try:
        funcionario_id = int(request.form.get("funcionario_id") or 0) or None
    except (TypeError, ValueError):
        funcionario_id = None

    return {
        "nome": str(request.form.get("nome") or "").strip(),
        "email": str(request.form.get("email") or "").strip().lower(),
        "perfil": normalizar_perfil_usuario(request.form.get("perfil")),
        "status": str(request.form.get("status") or "ativo").strip().lower(),
        "funcionario_id": funcionario_id,
        "senha": str(request.form.get("senha") or "").strip(),
        "confirmar_senha": str(request.form.get("confirmar_senha") or "").strip(),
    }


def validar_usuario_configuracoes_formulario(
    dados: dict[str, Any],
    usuario_id: int | None = None,
) -> str:
    if not dados["nome"]:
        return "Informe o nome do usuário."

    if not dados["email"] or "@" not in dados["email"]:
        return "Informe um e-mail válido."

    perfis_disponiveis = perfis_disponiveis_para_gestao()
    if dados["perfil"] not in perfis_disponiveis:
        return "Perfil de usuário inválido ou não permitido."

    if dados["status"] not in {"ativo", "inativo"}:
        return "Status de usuário inválido."

    with conectar_db() as conn:
        conflito_email = conn.execute(
            """
            SELECT id
            FROM usuarios
            WHERE LOWER(email) = LOWER(?)
              AND id <> COALESCE(?, 0)
            LIMIT 1
            """,
            (dados["email"], usuario_id),
        ).fetchone()
        if conflito_email is not None:
            return "Este e-mail já está vinculado a outro usuário."

        if dados.get("funcionario_id"):
            funcionario = conn.execute(
                """
                SELECT id
                FROM funcionarios
                WHERE id = ?
                  AND empresa_id = ?
                  AND LOWER(COALESCE(status, 'ativo')) <> 'excluido'
                LIMIT 1
                """,
                (int(dados["funcionario_id"]), empresa_logada_id()),
            ).fetchone()
            if funcionario is None:
                return "O funcionário selecionado não pertence a esta empresa."

            conflito_funcionario = conn.execute(
                """
                SELECT id
                FROM usuarios
                WHERE empresa_id = ?
                  AND funcionario_id = ?
                  AND id <> COALESCE(?, 0)
                LIMIT 1
                """,
                (empresa_logada_id(), int(dados["funcionario_id"]), usuario_id),
            ).fetchone()
            if conflito_funcionario is not None:
                return "Este funcionário já está vinculado a outro usuário."

    if usuario_id is not None and dados["senha"]:
        erro_senha = validar_senha_forte(dados["senha"])
        if erro_senha:
            return erro_senha
        if dados["senha"] != dados["confirmar_senha"]:
            return "A confirmação da senha não confere."

    return ""


def contar_administradores_ativos_empresa(excluir_usuario_id: int | None = None) -> int:
    parametros: list[Any] = [empresa_logada_id()]
    filtro = ""
    if excluir_usuario_id:
        filtro = " AND id <> ?"
        parametros.append(excluir_usuario_id)

    with conectar_db() as conn:
        row = conn.execute(
            f"""
            SELECT COUNT(*) AS total
            FROM usuarios
            WHERE empresa_id = ?
              AND LOWER(COALESCE(status, '')) = 'ativo'
              AND LOWER(COALESCE(perfil, '')) IN ('administrador', 'super_admin')
              {filtro}
            """,
            parametros,
        ).fetchone()
    return int(row["total"] or 0)


def criar_usuario_configuracoes_db(dados: dict[str, Any], permissoes_json: str) -> int:
    agora = agora_empresa().isoformat(timespec="seconds")
    with conectar_db() as conn:
        cursor = conn.execute(
            """
            INSERT INTO usuarios (
                empresa_id,
                funcionario_id,
                nome,
                email,
                senha_hash,
                perfil,
                permissoes_json,
                status,
                sessao_versao,
                atualizado_em
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?)
            """,
            (
                empresa_logada_id(),
                dados.get("funcionario_id"),
                dados["nome"],
                dados["email"],
                generate_password_hash(secrets.token_urlsafe(48)),
                dados["perfil"],
                permissoes_json,
                dados["status"],
                agora,
            ),
        )
        usuario_id = int(cursor.lastrowid)
        conn.commit()
    return usuario_id


def enviar_convite_novo_usuario(
    usuario_id: int,
    dados: dict[str, Any],
) -> tuple[bool, str]:
    token = secrets.token_urlsafe(40)
    token_hash = generate_password_hash(token)
    agora = agora_empresa()
    expira_em = (agora + timedelta(hours=24)).isoformat(timespec="seconds")
    base_url = str(
        os.getenv("GESTFLOW_BASE_URL", "")
        or getattr(config, "GESTFLOW_BASE_URL", "")
        or request.url_root.rstrip("/")
    ).rstrip("/")
    link = f"{base_url}/redefinir-senha/{token}"
    assunto = "Convite de acesso - GestFlow"
    corpo = (
        f"Olá, {dados.get('nome') or 'usuário'}.\n\n"
        "Seu acesso ao GestFlow foi criado.\n\n"
        "Use o link abaixo para criar sua senha. Ele é válido por 24 horas e pode ser usado uma única vez:\n"
        f"{link}\n\n"
        "Se você não reconhece este convite, ignore este e-mail."
    )

    with conectar_db() as conn:
        conn.execute(
            """
            INSERT INTO usuario_recuperacao_senha
                (empresa_id, usuario_id, token_hash, expira_em, usado_em, criado_em)
            VALUES (?, ?, ?, ?, '', ?)
            """,
            (
                empresa_logada_id(),
                usuario_id,
                token_hash,
                expira_em,
                agora.isoformat(timespec="seconds"),
            ),
        )
        conn.commit()

    enviado, detalhe = enviar_email_zoho(dados["email"], assunto, corpo)
    if enviado:
        return True, "Convite enviado por e-mail."

    with conectar_db() as conn:
        conn.execute(
            "DELETE FROM usuario_recuperacao_senha WHERE usuario_id = ? AND token_hash = ?",
            (usuario_id, token_hash),
        )
        conn.commit()
    return False, detalhe


def atualizar_usuario_configuracoes_db(
    usuario_id: int,
    dados: dict[str, Any],
    permissoes_json: str,
) -> None:
    agora = agora_empresa().isoformat(timespec="seconds")
    with conectar_db() as conn:
        parametros: list[Any] = [
            dados.get("funcionario_id"),
            dados["nome"],
            dados["email"],
            dados["perfil"],
            permissoes_json,
            dados["status"],
            agora,
        ]
        senha_sql = ""
        if dados.get("senha"):
            senha_sql = ", senha_hash = ?, sessao_versao = COALESCE(sessao_versao, 1) + 1"
            parametros.append(generate_password_hash(dados["senha"]))

        parametros.extend([usuario_id, empresa_logada_id()])
        conn.execute(
            f"""
            UPDATE usuarios
            SET
                funcionario_id = ?,
                nome = ?,
                email = ?,
                perfil = ?,
                permissoes_json = ?,
                status = ?,
                atualizado_em = ?
                {senha_sql}
            WHERE id = ?
              AND empresa_id = ?
            """,
            parametros,
        )
        conn.commit()


