    senha_hash = generate_password_hash(str(nova_senha or ""))

    with conectar_db() as conn:
        conn.execute(
            """
            UPDATE usuarios
            SET
                senha_hash = ?,
                sessao_versao = COALESCE(sessao_versao, 1) + 1,
                atualizado_em = ?
            WHERE id = ?
              AND empresa_id = ?
            """,
            (
                senha_hash,
                agora_empresa().isoformat(timespec="seconds"),
                usuario_id,
                empresa_id,
            ),
        )
        conn.commit()


