def _extensao_logo_permitida(nome_arquivo: str) -> bool:
    if "." not in nome_arquivo:
        return False

    extensao = nome_arquivo.rsplit(".", 1)[1].lower()
    return extensao in EXTENSOES_LOGO_PERMITIDAS


def salvar_upload_logo_empresa(arquivo) -> str:
    nome_seguro = secure_filename(arquivo.filename or "")

    if not nome_seguro or not _extensao_logo_permitida(nome_seguro):
        raise ValueError("Formato de logo inválido. Use PNG, JPG, JPEG, WEBP, GIF, JFIF ou AVIF.")

    extensao = nome_seguro.rsplit(".", 1)[1].lower()
    empresa_id = empresa_logada_id()
    timestamp = agora_empresa().strftime("%Y%m%d%H%M%S")
    codigo_unico = secrets.token_hex(4)
    nome_final = f"empresa_{empresa_id}_{timestamp}_{codigo_unico}.{extensao}"

    UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
    destino = UPLOAD_DIR / nome_final

    arquivo.save(destino)

    return f"/uploads/logos/{nome_final}"



def _extensao_foto_os_permitida(nome_arquivo: str) -> bool:
    if "." not in nome_arquivo:
        return False

    extensao = nome_arquivo.rsplit(".", 1)[1].lower()
    return extensao in EXTENSOES_FOTO_OS_PERMITIDAS


def salvar_upload_foto_os(
    arquivo,
    ordem_servico_id: int,
    tipo_foto: str,
    empresa_id_param: int | None = None,
) -> str:
    nome_seguro = secure_filename(arquivo.filename or "")

    if not nome_seguro:
        return ""

    if not _extensao_foto_os_permitida(nome_seguro):
        raise ValueError("Formato de foto inválido. Use PNG, JPG, JPEG, JFIF ou WEBP.")

    extensao = nome_seguro.rsplit(".", 1)[1].lower()
    empresa_id = int(empresa_id_param or empresa_logada_id())
    timestamp = agora_empresa().strftime("%Y%m%d%H%M%S%f")
    tipo_limpo = "".join(caractere for caractere in str(tipo_foto or "foto") if caractere.isalnum())[:16] or "foto"
    nome_final = f"os_{empresa_id}_{int(ordem_servico_id)}_{tipo_limpo}_{timestamp}.{extensao}"
    destino = OS_FOTOS_DIR / nome_final

    arquivo.save(destino)

    return f"/uploads/os-fotos/{nome_final}"


def listar_fotos_equipamento_os(ordem_servico_id: int) -> list[dict[str, Any]]:
    empresa_id = empresa_logada_id()

    with conectar_db() as conn:
        rows = conn.execute(
            """
            SELECT
                id,
                empresa_id,
                ordem_servico_id,
                titulo,
                equipamento_indice,
                tipo_foto,
                foto_antes_path,
                foto_depois_path,
                observacoes,
                criado_em,
                atualizado_em
            FROM os_fotos_equipamento
            WHERE ordem_servico_id = ?
              AND empresa_id = ?
            ORDER BY
                CASE
                    WHEN TRIM(COALESCE(foto_antes_path, '')) <> ''
                      OR TRIM(COALESCE(foto_depois_path, '')) <> ''
                      OR TRIM(COALESCE(observacoes, '')) <> ''
                    THEN 0
                    ELSE 1
                END,
                CAST(COALESCE(equipamento_indice, '0') AS INTEGER) ASC,
                id ASC
            """,
            (ordem_servico_id, empresa_id),
        ).fetchall()

    return [dict(row) for row in rows]


def _normalizar_chave_card_foto_os(valor: Any) -> str:
    chave = re.sub(r"[^A-Za-z0-9_-]+", "_", str(valor or "").strip())
    return chave[:100]


def _atualizar_fotos_equipamento_os_cards(ordem_servico_id: int) -> None:
    empresa_id = empresa_logada_id()
    equipamentos = montar_equipamentos_ordem_servico_formulario()
    indices_validos = {str(indice) for indice in range(len(equipamentos))}
    agora = agora_empresa().isoformat(timespec="seconds")
    fotos_json_texto = str(request.form.get("os_fotos_json") or "").strip()

    try:
        fotos_json = json.loads(fotos_json_texto) if fotos_json_texto else []
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise ValueError("Não foi possível organizar as fotos da OS. Atualize a página e tente novamente.") from exc

    if not isinstance(fotos_json, list):
        raise ValueError("Os dados das fotos da OS estão inválidos.")

    with conectar_db() as conn:
        registros = conn.execute(
            """
            SELECT *
            FROM os_fotos_equipamento
            WHERE ordem_servico_id = ?
              AND empresa_id = ?
            ORDER BY id ASC
            """,
            (ordem_servico_id, empresa_id),
        ).fetchall()
        registros_por_id = {int(registro["id"]): registro for registro in registros}

        for item in fotos_json:
            if not isinstance(item, dict):
                continue

            chave = _normalizar_chave_card_foto_os(item.get("chave"))
            if not chave:
                continue

            equipamento_indice = str(item.get("equipamento_indice") or "0").strip() or "0"
            if equipamento_indice not in indices_validos:
                continue

            foto_id_texto = str(item.get("id") or "").strip()
            foto_id = int(foto_id_texto) if foto_id_texto.isdigit() else None
            tipo = "depois" if str(item.get("tipo") or "").strip().lower() == "depois" else "antes"
            titulo = str(item.get("titulo") or "").strip()
            observacoes = str(item.get("observacoes") or "").strip()
            remover = str(item.get("remover") or "nao").strip().lower() in {"sim", "true", "1"}
            arquivo = request.files.get(f"foto_os_arquivo_{chave}")

            registro_atual = registros_por_id.get(foto_id) if foto_id is not None else None

            if registro_atual is not None:
                if remover:
                    conn.execute(
                        """
                        DELETE FROM os_fotos_equipamento
                        WHERE id = ?
                          AND ordem_servico_id = ?
                          AND empresa_id = ?
                        """,
                        (foto_id, ordem_servico_id, empresa_id),
                    )
                    continue

                caminho_atual = str(
                    registro_atual["foto_antes_path"]
                    or registro_atual["foto_depois_path"]
                    or ""
                ).strip()
                caminho_final = caminho_atual

                if arquivo is not None and arquivo.filename:
                    caminho_final = salvar_upload_foto_os(
                        arquivo,
                        ordem_servico_id,
                        f"{tipo}_{equipamento_indice}",
                    )

                if not caminho_final:
                    conn.execute(
                        "DELETE FROM os_fotos_equipamento WHERE id = ? AND ordem_servico_id = ? AND empresa_id = ?",
                        (foto_id, ordem_servico_id, empresa_id),
                    )
                    continue

                foto_antes_path = caminho_final if tipo == "antes" else ""
                foto_depois_path = caminho_final if tipo == "depois" else ""
                conn.execute(
                    """
                    UPDATE os_fotos_equipamento
                    SET
                        titulo = ?,
                        equipamento_indice = ?,
                        foto_antes_path = ?,
                        foto_depois_path = ?,
                        observacoes = ?,
                        atualizado_em = ?
                    WHERE id = ?
                      AND ordem_servico_id = ?
                      AND empresa_id = ?
                    """,
                    (
                        titulo,
                        equipamento_indice,
                        foto_antes_path,
                        foto_depois_path,
                        observacoes,
                        agora,
                        foto_id,
                        ordem_servico_id,
                        empresa_id,
                    ),
                )
                continue

            if remover or arquivo is None or not arquivo.filename:
                continue

            caminho_novo = salvar_upload_foto_os(
                arquivo,
                ordem_servico_id,
                f"{tipo}_{equipamento_indice}",
            )
            foto_antes_path = caminho_novo if tipo == "antes" else ""
            foto_depois_path = caminho_novo if tipo == "depois" else ""

            conn.execute(
                """
                INSERT INTO os_fotos_equipamento (
                    empresa_id,
                    ordem_servico_id,
                    titulo,
                    equipamento_indice,
                    foto_antes_path,
                    foto_depois_path,
                    observacoes,
                    atualizado_em
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    ordem_servico_id,
                    titulo,
                    equipamento_indice,
                    foto_antes_path,
                    foto_depois_path,
                    observacoes,
                    agora,
                ),
            )

        if indices_validos:
            placeholders = ", ".join("?" for _ in indices_validos)
            conn.execute(
                f"""
                DELETE FROM os_fotos_equipamento
                WHERE ordem_servico_id = ?
                  AND empresa_id = ?
                  AND COALESCE(equipamento_indice, '0') NOT IN ({placeholders})
                """,
                [ordem_servico_id, empresa_id, *sorted(indices_validos, key=int)],
            )
        else:
            conn.execute(
                "DELETE FROM os_fotos_equipamento WHERE ordem_servico_id = ? AND empresa_id = ?",
                (ordem_servico_id, empresa_id),
            )

        conn.execute(
            """
            DELETE FROM os_fotos_equipamento
            WHERE ordem_servico_id = ?
              AND empresa_id = ?
              AND TRIM(COALESCE(foto_antes_path, '')) = ''
              AND TRIM(COALESCE(foto_depois_path, '')) = ''
            """,
            (ordem_servico_id, empresa_id),
        )
        conn.commit()


def _atualizar_fotos_equipamento_os_indexadas(ordem_servico_id: int) -> None:
    empresa_id = empresa_logada_id()
    equipamentos = montar_equipamentos_ordem_servico_formulario()
    indices_validos = {str(indice) for indice in range(len(equipamentos))}
    agora = agora_empresa().isoformat(timespec="seconds")

    with conectar_db() as conn:
        registros = conn.execute(
            """
            SELECT *
            FROM os_fotos_equipamento
            WHERE ordem_servico_id = ?
              AND empresa_id = ?
            ORDER BY id ASC
            """,
            (ordem_servico_id, empresa_id),
        ).fetchall()
        registros_por_indice: dict[str, list[sqlite3.Row]] = {}
        for registro in registros:
            indice_registro = str(registro["equipamento_indice"] or "0").strip() or "0"
            registros_por_indice.setdefault(indice_registro, []).append(registro)

        for indice, equipamento in enumerate(equipamentos):
            indice_texto = str(indice)
            registros_indice = registros_por_indice.get(indice_texto, [])
            foto_id_texto = str(request.form.get(f"foto_os_id_{indice}") or "").strip()
            foto_id = int(foto_id_texto) if foto_id_texto.isdigit() else None
            remover = bool(request.form.get(f"foto_os_remover_{indice}"))
            observacoes = str(request.form.get(f"foto_os_observacoes_{indice}") or "").strip()
            arquivo_antes = request.files.get(f"foto_os_antes_{indice}")
            arquivo_depois = request.files.get(f"foto_os_depois_{indice}")
            titulo = str(equipamento.get("equipamento") or equipamento.get("titulo") or "").strip()

            registro_atual = None
            if foto_id is not None:
                registro_atual = next(
                    (registro for registro in registros if int(registro["id"]) == foto_id),
                    None,
                )
            if registro_atual is None and registros_indice:
                registro_atual = registros_indice[0]

            if remover:
                conn.execute(
                    """
                    DELETE FROM os_fotos_equipamento
                    WHERE ordem_servico_id = ?
                      AND empresa_id = ?
                      AND equipamento_indice = ?
                    """,
                    (ordem_servico_id, empresa_id, indice_texto),
                )
                continue

            foto_antes_path = str(registro_atual["foto_antes_path"] or "") if registro_atual else ""
            foto_depois_path = str(registro_atual["foto_depois_path"] or "") if registro_atual else ""

            if arquivo_antes is not None and arquivo_antes.filename:
                foto_antes_path = salvar_upload_foto_os(arquivo_antes, ordem_servico_id, f"antes_{indice}")
            if arquivo_depois is not None and arquivo_depois.filename:
                foto_depois_path = salvar_upload_foto_os(arquivo_depois, ordem_servico_id, f"depois_{indice}")

            possui_conteudo = bool(foto_antes_path or foto_depois_path or observacoes)
            if not possui_conteudo:
                conn.execute(
                    """
                    DELETE FROM os_fotos_equipamento
                    WHERE ordem_servico_id = ?
                      AND empresa_id = ?
                      AND equipamento_indice = ?
                    """,
                    (ordem_servico_id, empresa_id, indice_texto),
                )
                continue

            if registro_atual is not None:
                registro_id = int(registro_atual["id"])
                conn.execute(
                    """
                    UPDATE os_fotos_equipamento
                    SET
                        titulo = ?,
                        equipamento_indice = ?,
                        foto_antes_path = ?,
                        foto_depois_path = ?,
                        observacoes = ?,
                        atualizado_em = ?
                    WHERE id = ?
                      AND ordem_servico_id = ?
                      AND empresa_id = ?
                    """,
                    (
                        titulo,
                        indice_texto,
                        foto_antes_path,
                        foto_depois_path,
                        observacoes,
                        agora,
                        registro_id,
                        ordem_servico_id,
                        empresa_id,
                    ),
                )
            else:
                cursor = conn.execute(
                    """
                    INSERT INTO os_fotos_equipamento (
                        empresa_id,
                        ordem_servico_id,
                        titulo,
                        equipamento_indice,
                        foto_antes_path,
                        foto_depois_path,
                        observacoes,
                        atualizado_em
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        empresa_id,
                        ordem_servico_id,
                        titulo,
                        indice_texto,
                        foto_antes_path,
                        foto_depois_path,
                        observacoes,
                        agora,
                    ),
                )
                registro_id = int(cursor.lastrowid)

            conn.execute(
                """
                DELETE FROM os_fotos_equipamento
                WHERE ordem_servico_id = ?
                  AND empresa_id = ?
                  AND equipamento_indice = ?
                  AND id <> ?
                """,
                (ordem_servico_id, empresa_id, indice_texto, registro_id),
            )

        if indices_validos:
            placeholders = ", ".join("?" for _ in indices_validos)
            conn.execute(
                f"""
                DELETE FROM os_fotos_equipamento
                WHERE ordem_servico_id = ?
                  AND empresa_id = ?
                  AND COALESCE(equipamento_indice, '0') NOT IN ({placeholders})
                """,
                [ordem_servico_id, empresa_id, *sorted(indices_validos, key=int)],
            )
        else:
            conn.execute(
                "DELETE FROM os_fotos_equipamento WHERE ordem_servico_id = ? AND empresa_id = ?",
                (ordem_servico_id, empresa_id),
            )

        conn.execute(
            """
            DELETE FROM os_fotos_equipamento
            WHERE ordem_servico_id = ?
              AND empresa_id = ?
              AND TRIM(COALESCE(foto_antes_path, '')) = ''
              AND TRIM(COALESCE(foto_depois_path, '')) = ''
              AND TRIM(COALESCE(observacoes, '')) = ''
            """,
            (ordem_servico_id, empresa_id),
        )
        conn.commit()


def _atualizar_fotos_equipamento_os_legado(ordem_servico_id: int) -> None:
    empresa_id = empresa_logada_id()
    ids = request.form.getlist("foto_os_id")
    titulos = request.form.getlist("foto_os_titulo")
    indices_equipamento = request.form.getlist("foto_os_equipamento_indice")
    observacoes_lista = request.form.getlist("foto_os_observacoes")
    remover_ids = {
        int(valor)
        for valor in request.form.getlist("foto_os_remover")
        if str(valor or "").strip().isdigit()
    }
    arquivos_antes = request.files.getlist("foto_os_antes")
    arquivos_depois = request.files.getlist("foto_os_depois")
    agora = agora_empresa().isoformat(timespec="seconds")
    total_linhas = max(
        len(ids),
        len(titulos),
        len(indices_equipamento),
        len(observacoes_lista),
        len(arquivos_antes),
        len(arquivos_depois),
    )

    with conectar_db() as conn:
        for indice in range(total_linhas):
            foto_id_texto = str(ids[indice] if indice < len(ids) else "").strip()
            foto_id = int(foto_id_texto) if foto_id_texto.isdigit() else None
            titulo = str(titulos[indice] if indice < len(titulos) else "").strip()
            equipamento_indice = str(indices_equipamento[indice] if indice < len(indices_equipamento) else "0").strip() or "0"
            observacoes = str(observacoes_lista[indice] if indice < len(observacoes_lista) else "").strip()
            arquivo_antes = arquivos_antes[indice] if indice < len(arquivos_antes) else None
            arquivo_depois = arquivos_depois[indice] if indice < len(arquivos_depois) else None

            if foto_id is not None and foto_id in remover_ids:
                conn.execute(
                    "DELETE FROM os_fotos_equipamento WHERE id = ? AND ordem_servico_id = ? AND empresa_id = ?",
                    (foto_id, ordem_servico_id, empresa_id),
                )
                continue

            foto_antes_path = ""
            foto_depois_path = ""
            if arquivo_antes is not None and arquivo_antes.filename:
                foto_antes_path = salvar_upload_foto_os(arquivo_antes, ordem_servico_id, "antes")
            if arquivo_depois is not None and arquivo_depois.filename:
                foto_depois_path = salvar_upload_foto_os(arquivo_depois, ordem_servico_id, "depois")

            if foto_id is not None:
                row_atual = conn.execute(
                    """
                    SELECT foto_antes_path, foto_depois_path
                    FROM os_fotos_equipamento
                    WHERE id = ? AND ordem_servico_id = ? AND empresa_id = ?
                    LIMIT 1
                    """,
                    (foto_id, ordem_servico_id, empresa_id),
                ).fetchone()
                if row_atual is None:
                    continue

                foto_antes_final = foto_antes_path or row_atual["foto_antes_path"] or ""
                foto_depois_final = foto_depois_path or row_atual["foto_depois_path"] or ""
                if not foto_antes_final and not foto_depois_final and not observacoes:
                    conn.execute(
                        "DELETE FROM os_fotos_equipamento WHERE id = ? AND ordem_servico_id = ? AND empresa_id = ?",
                        (foto_id, ordem_servico_id, empresa_id),
                    )
                    continue

                conn.execute(
                    """
                    UPDATE os_fotos_equipamento
                    SET titulo = ?, equipamento_indice = ?, foto_antes_path = ?, foto_depois_path = ?, observacoes = ?, atualizado_em = ?
                    WHERE id = ? AND ordem_servico_id = ? AND empresa_id = ?
                    """,
                    (titulo, equipamento_indice, foto_antes_final, foto_depois_final, observacoes, agora, foto_id, ordem_servico_id, empresa_id),
                )
                continue

            if not observacoes and not foto_antes_path and not foto_depois_path:
                continue

            conn.execute(
                """
                INSERT INTO os_fotos_equipamento (
                    empresa_id, ordem_servico_id, titulo, equipamento_indice, foto_antes_path, foto_depois_path, observacoes, atualizado_em
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (empresa_id, ordem_servico_id, titulo, equipamento_indice, foto_antes_path, foto_depois_path, observacoes, agora),
            )

        conn.execute(
            """
            DELETE FROM os_fotos_equipamento
            WHERE ordem_servico_id = ?
              AND empresa_id = ?
              AND TRIM(COALESCE(foto_antes_path, '')) = ''
              AND TRIM(COALESCE(foto_depois_path, '')) = ''
              AND TRIM(COALESCE(observacoes, '')) = ''
            """,
            (ordem_servico_id, empresa_id),
        )
        conn.commit()


def atualizar_fotos_equipamento_os_formulario(ordem_servico_id: int) -> None:
    if str(request.form.get("os_fotos_json") or "").strip():
        _atualizar_fotos_equipamento_os_cards(ordem_servico_id)
        return

    possui_campos_indexados = any(
        str(chave).startswith(("foto_os_id_", "foto_os_observacoes_", "foto_os_remover_"))
        for chave in request.form.keys()
    ) or any(
        str(chave).startswith(("foto_os_antes_", "foto_os_depois_"))
        for chave in request.files.keys()
    )

    if possui_campos_indexados:
        _atualizar_fotos_equipamento_os_indexadas(ordem_servico_id)
        return

    _atualizar_fotos_equipamento_os_legado(ordem_servico_id)


def usuario_logado_eh_admin_sistema() -> bool:
    return normalizar_perfil_usuario(session.get("usuario_perfil")) == "super_admin"




def registrar_atividade_usuario(
    tipo: str,
    modulo: str,
    descricao: str,
    rota: str | None = None,
    empresa_id: int | None = None,
    usuario_id: int | None = None,
    usuario_nome: str | None = None,
    registro_id: Any = None,
    dados_anteriores: Any = None,
    dados_novos: Any = None,
) -> None:
    tipo_normalizado = str(tipo or "acesso").strip().lower() or "acesso"
    modulo_normalizado = str(modulo or "geral").strip().lower() or "geral"
    descricao_normalizada = str(descricao or "").strip()
    rota_normalizada = str(rota or (request.path if request else "")).strip()

    try:
        empresa_final = int(empresa_id if empresa_id is not None else (session.get("empresa_id") or 0))
    except (TypeError, ValueError):
        empresa_final = 0

    try:
        usuario_final = int(usuario_id if usuario_id is not None else (session.get("usuario_id") or 0))
    except (TypeError, ValueError):
        usuario_final = 0

    nome_final = str(usuario_nome or session.get("usuario_nome") or "").strip()

    if not usuario_final and not nome_final:
        return

    def _json_seguro(valor: Any) -> str:
        if valor in (None, ""):
            return ""
        try:
            return json.dumps(valor, ensure_ascii=False, default=str, sort_keys=True)
        except (TypeError, ValueError):
            return json.dumps(str(valor), ensure_ascii=False)

    ip = ""
    try:
        ip = str(request.headers.get("X-Forwarded-For") or request.remote_addr or "").split(",")[0].strip()
    except RuntimeError:
        ip = ""

    try:
        with conectar_db() as conn:
            conn.execute(
                """
                INSERT INTO usuario_atividades (
                    empresa_id,
                    usuario_id,
                    usuario_nome,
                    tipo,
                    modulo,
                    descricao,
                    rota,
                    registro_id,
                    dados_anteriores_json,
                    dados_novos_json,
                    ip,
                    criado_em
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_final or None,
                    usuario_final or None,
                    nome_final,
                    tipo_normalizado,
                    modulo_normalizado,
                    descricao_normalizada,
                    rota_normalizada,
                    str(registro_id or ""),
                    _json_seguro(dados_anteriores),
                    _json_seguro(dados_novos),
                    ip,
                    agora_empresa().isoformat(timespec="seconds"),
                ),
            )
            conn.commit()
    except sqlite3.Error:
        return



def modulo_por_rota_admin(rota: str) -> str | None:
    rota = str(rota or "").strip()

    if rota == "/":
        return "dashboard"

    mapa_modulos = {
        "/clientes": "clientes",
        "/fornecedores": "fornecedores",
        "/funcionarios": "funcionarios",
        "/produtos": "produtos",
        "/servicos": "servicos",
        "/orcamentos": "orcamentos",
        "/contratos": "contratos",
        "/vendas": "vendas",
        "/ordens-servico": "ordens_servico",
        "/estoque": "estoque",
        "/financeiro": "financeiro",
        "/configuracoes": "configuracoes",
        "/admin": "admin",
    }

    for prefixo, modulo in mapa_modulos.items():
        if rota == prefixo or rota.startswith(f"{prefixo}/"):
            return modulo

    return None


@app.before_request
def registrar_acesso_modulo_usuario() -> None:
    if request.method != "GET":
        return

    if not session.get("usuario_id"):
        return

    endpoint = str(request.endpoint or "")
    if endpoint in {"static", "servir_foto_os"}:
        return

    if request.path.startswith("/static/") or request.path.startswith("/uploads/"):
        return

    modulo = modulo_por_rota_admin(request.path)

    if not modulo:
        return

    registrar_atividade_usuario(
        "visualizacao",
        modulo,
        f"Acessou {modulo.replace('_', ' ')}",
        request.path,
    )


def montar_dashboard_admin() -> dict[str, Any]:
    agora = agora_empresa()
    limite_7_dias = (agora - timedelta(days=7)).isoformat(timespec="seconds")

    with conectar_db() as conn:
        resumo_row = conn.execute(
            """
            SELECT
                (SELECT COUNT(*) FROM empresas) AS total_empresas,
                (SELECT COUNT(*) FROM empresas WHERE LOWER(status) = 'trial') AS empresas_trial,
                (SELECT COUNT(*) FROM empresas WHERE LOWER(status) = 'ativo') AS empresas_ativas,
                (SELECT COUNT(*) FROM usuarios) AS total_usuarios,
                (SELECT COUNT(*) FROM usuarios WHERE ultimo_login IS NOT NULL AND TRIM(ultimo_login) <> '') AS usuarios_ja_acessaram,
                (SELECT COUNT(*) FROM usuarios WHERE ultimo_login IS NULL OR TRIM(ultimo_login) = '') AS usuarios_nunca_acessaram,
                (SELECT COUNT(*) FROM usuario_atividades WHERE criado_em >= ?) AS atividades_7_dias,
                (SELECT COUNT(DISTINCT usuario_id) FROM usuario_atividades WHERE criado_em >= ? AND usuario_id IS NOT NULL) AS usuarios_ativos_7_dias
            """,
            (limite_7_dias, limite_7_dias),
        ).fetchone()

        usuarios_rows = conn.execute(
            """
            SELECT
                usuarios.id,
                usuarios.nome,
                usuarios.email,
                usuarios.perfil,
                usuarios.status,
                usuarios.ultimo_login,
                usuarios.criado_em,
                empresas.nome_fantasia AS empresa_nome,
                empresas.status AS empresa_status,
                COALESCE(COUNT(usuario_atividades.id), 0) AS total_atividades,
                COALESCE(SUM(CASE WHEN usuario_atividades.tipo = 'login' THEN 1 ELSE 0 END), 0) AS total_logins,
                COALESCE(SUM(CASE WHEN usuario_atividades.tipo IN ('criacao', 'edicao', 'exclusao') THEN 1 ELSE 0 END), 0) AS total_acoes,
                MAX(usuario_atividades.criado_em) AS ultima_atividade
            FROM usuarios
            JOIN empresas ON empresas.id = usuarios.empresa_id
            LEFT JOIN usuario_atividades ON usuario_atividades.usuario_id = usuarios.id
            GROUP BY usuarios.id
            ORDER BY ultima_atividade DESC, usuarios.id DESC
            LIMIT 80
            """
        ).fetchall()

        atividades_rows = conn.execute(
            """
            SELECT
                usuario_atividades.id,
                usuario_atividades.empresa_id,
                usuario_atividades.usuario_id,
                usuario_atividades.usuario_nome,
                usuario_atividades.tipo,
                usuario_atividades.modulo,
                usuario_atividades.descricao,
                usuario_atividades.rota,
                usuario_atividades.criado_em,
                empresas.nome_fantasia AS empresa_nome
            FROM usuario_atividades
            LEFT JOIN empresas ON empresas.id = usuario_atividades.empresa_id
            ORDER BY usuario_atividades.id DESC
            LIMIT 60
            """
        ).fetchall()

        modulos_rows = conn.execute(
            """
            SELECT
                modulo,
                COUNT(*) AS total_acessos,
                SUM(CASE WHEN tipo IN ('criacao', 'edicao', 'exclusao') THEN 1 ELSE 0 END) AS total_acoes,
                MAX(criado_em) AS ultima_atividade
            FROM usuario_atividades
            WHERE modulo IS NOT NULL AND TRIM(modulo) <> ''
            GROUP BY modulo
            ORDER BY total_acessos DESC, modulo ASC
            LIMIT 20
            """
        ).fetchall()

    resumo = dict(resumo_row or {})
    usuarios = []

    for row in usuarios_rows:
        usuario = dict(row)
        total_logins = int(usuario.get("total_logins") or 0)
        total_acoes = int(usuario.get("total_acoes") or 0)
        ultimo_login = str(usuario.get("ultimo_login") or "").strip()

        if not ultimo_login and total_logins == 0:
            situacao = "Não testou"
            classe = "cancelada"
        elif total_acoes == 0:
            situacao = "Só entrou"
            classe = "aberta"
        elif total_acoes <= 2:
            situacao = "Testou pouco"
            classe = "aguardando"
        elif total_acoes < 10:
            situacao = "Testando"
            classe = "andamento"
        else:
            situacao = "Ativo"
            classe = "concretizada"

        usuario["situacao_uso"] = situacao
        usuario["situacao_classe"] = classe
        usuarios.append(usuario)

    return {
        "resumo": resumo,
        "usuarios": usuarios,
        "atividades": [dict(row) for row in atividades_rows],
        "modulos": [dict(row) for row in modulos_rows],
    }



