def excluir_empresa_cliente_admin_db(empresa_id: int) -> bool:
    try:
        empresa_id = int(empresa_id)
    except (TypeError, ValueError):
        return False

    empresa_principal_id = empresa_padrao_id()
    empresa_sessao_id = empresa_logada_id()

    if empresa_id <= 0:
        return False

    if empresa_id == empresa_principal_id:
        return False

    if empresa_id == empresa_sessao_id:
        return False

    empresa = buscar_empresa_admin_por_id(empresa_id)

    if empresa is None:
        return False

    with conectar_db() as conn:
        tabelas_por_empresa = [
            "notificacoes",
            "configuracoes_modulos",
            "contrato_historico",
            "contrato_anexos",
            "contrato_itens",
            "contrato_sequencias",
            "orcamento_itens",
            "venda_itens",
            "ordem_servico_itens",
            "estoque_movimentacoes",
            "financeiro_titulos",
            "contratos",
            "orcamentos",
            "vendas",
            "ordens_servico",
            "clientes",
            "fornecedores",
            "funcionarios",
            "produtos",
            "servicos",
        ]

        for tabela in tabelas_por_empresa:
            conn.execute(
                f"DELETE FROM {tabela} WHERE empresa_id = ?",
                (empresa_id,),
            )

        conn.execute(
            """
            DELETE FROM indicacao_comissoes
            WHERE indicador_empresa_id = ?
               OR indicado_empresa_id = ?
            """,
            (empresa_id, empresa_id),
        )

        conn.execute(
            """
            UPDATE empresas
            SET
                indicado_por_empresa_id = NULL,
                indicador_codigo = ''
            WHERE indicado_por_empresa_id = ?
            """,
            (empresa_id,),
        )

        conn.execute(
            """
            DELETE FROM lojas
            WHERE empresa_id = ?
            """,
            (empresa_id,),
        )

        conn.execute(
            """
            DELETE FROM usuarios
            WHERE empresa_id = ?
            """,
            (empresa_id,),
        )

        conn.execute(
            """
            DELETE FROM empresas
            WHERE id = ?
            """,
            (empresa_id,),
        )

        conn.commit()

    return True



AGENDAMENTOS_STATUS = ["novo", "agendado", "confirmado", "em_atendimento", "concluido", "cancelado", "nao_compareceu"]
PONTO_ACOES = {
    "entrada": "Entrada",
    "saida_intervalo": "Saída para intervalo",
    "retorno_intervalo": "Retorno do intervalo",
    "saida": "Saída",
}


def ponto_exige_intervalo(funcionario: dict[str, Any] | None) -> bool:
    empresa_id = int((funcionario or {}).get("empresa_id") or 0)
    if empresa_id and int(float(valor_configuracao_modulo("registro_ponto", "intervalo_obrigatorio_minutos", 60, empresa_id) or 0)) <= 0:
        return False
    valor = str(
        (funcionario or {}).get("exigir_intervalo_ponto") or "sim"
    ).strip().lower()
    return valor not in {"nao", "não", "0", "false", "off"}


def validar_local_autorizado_ponto(
    empresa_id: int,
    latitude: str,
    longitude: str,
) -> bool:
    linhas = lista_configuracao_modulo("registro_ponto", "locais_autorizados", empresa_id)
    if not linhas:
        return True
    try:
        latitude_atual = float(latitude)
        longitude_atual = float(longitude)
    except (TypeError, ValueError):
        return False
    raio_padrao = max(1.0, float(valor_configuracao_modulo("registro_ponto", "raio_maximo_metros", 200, empresa_id) or 200))
    locais_validos = 0
    for linha in linhas:
        numeros = re.findall(r"-?\d+(?:[.,]\d+)?", linha)
        if len(numeros) < 2:
            continue
        try:
            latitude_local = float(numeros[-3 if len(numeros) >= 3 else -2].replace(",", "."))
            longitude_local = float(numeros[-2 if len(numeros) >= 3 else -1].replace(",", "."))
            raio = float(numeros[-1].replace(",", ".")) if len(numeros) >= 3 else raio_padrao
        except ValueError:
            continue
        if not (-90 <= latitude_local <= 90 and -180 <= longitude_local <= 180):
            continue
        locais_validos += 1
        raio_terra = 6371000.0
        phi1, phi2 = math.radians(latitude_atual), math.radians(latitude_local)
        dphi = math.radians(latitude_local - latitude_atual)
        dlambda = math.radians(longitude_local - longitude_atual)
        a = math.sin(dphi / 2) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(dlambda / 2) ** 2
        distancia = raio_terra * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a))
        if distancia <= max(1.0, raio):
            return True
    return locais_validos == 0


def ordem_ponto_funcionario(funcionario: dict[str, Any] | None) -> list[str]:
    if ponto_exige_intervalo(funcionario):
        return ["entrada", "saida_intervalo", "retorno_intervalo", "saida"]

    return ["entrada", "saida"]


def rotulo_proxima_acao_ponto(acao: str) -> str:
    rotulos = {
        "entrada": "Próxima marcação: Entrada",
        "saida_intervalo": "Próxima marcação: Saída para intervalo",
        "retorno_intervalo": "Próxima marcação: Retorno do intervalo",
        "saida": "Próxima marcação: Saída",
    }
    return rotulos.get(str(acao or ""), "Ponto de hoje completo.")


def proxima_acao_ponto(
    registro: dict[str, Any] | None,
    funcionario: dict[str, Any] | None,
) -> str:
    ordem = ordem_ponto_funcionario(funcionario)

    if registro is None:
        return "entrada"

    return next((campo for campo in ordem if not registro.get(campo)), "")


def _normalizar_data_iso(valor: Any, padrao: str | None = None) -> str:
    texto = str(valor or "").strip()
    if not texto:
        return padrao or hoje_empresa().isoformat()
    try:
        return datetime.strptime(texto[:10], "%Y-%m-%d").date().isoformat()
    except ValueError:
        return padrao or hoje_empresa().isoformat()


def _normalizar_hora_hhmm(valor: Any) -> str:
    texto = str(valor or "").strip()
    if not texto:
        return ""
    try:
        return datetime.strptime(texto[:5], "%H:%M").strftime("%H:%M")
    except ValueError:
        return texto[:5]


def _calcular_total_horas_ponto(entrada: Any, saida_intervalo: Any, retorno_intervalo: Any, saida: Any) -> str:
    def minutos(valor: Any) -> int | None:
        texto = _normalizar_hora_hhmm(valor)
        if not texto:
            return None
        try:
            hora, minuto = texto.split(":")
            return int(hora) * 60 + int(minuto)
        except (ValueError, AttributeError):
            return None

    entrada_min = minutos(entrada)
    saida_min = minutos(saida)
    pausa_inicio = minutos(saida_intervalo)
    pausa_fim = minutos(retorno_intervalo)

    if entrada_min is None or saida_min is None:
        return ""

    total = saida_min - entrada_min
    if total < 0:
        total += 24 * 60

    if pausa_inicio is not None and pausa_fim is not None:
        pausa = pausa_fim - pausa_inicio
        if pausa < 0:
            pausa += 24 * 60
        total -= max(pausa, 0)

    total = max(total, 0)
    return f"{total // 60:02d}:{total % 60:02d}"


def _status_ponto(entrada: Any, saida_intervalo: Any, retorno_intervalo: Any, saida: Any, ajustado: bool = False) -> str:
    if ajustado:
        return "ajustado"
    if entrada and saida:
        return "completo"
    if entrada or saida_intervalo or retorno_intervalo or saida:
        return "incompleto"
    return "faltou"


def montar_agendamento_formulario() -> dict[str, str]:
    empresa_id = empresa_logada_id()
    servico_id = str(request.form.get("servico_id") or "").strip()
    servico = buscar_servico_empresa(empresa_id, servico_id, request.form.get("servico_nome"))
    profissional_id = str(request.form.get("profissional_id") or "").strip()
    data_agendamento = _normalizar_data_iso(request.form.get("data_agendamento"))
    hora_inicio = _normalizar_hora_hhmm(request.form.get("hora_inicio"))
    duracao_minutos = duracao_efetiva_servico_minutos(servico, empresa_id)
    inicio_minutos = _minutos_hora_agendamento(hora_inicio, -1)
    hora_fim = _hora_agendamento_por_minutos(inicio_minutos + duracao_minutos) if inicio_minutos >= 0 else ""
    profissional_nome = ""
    if profissional_id.isdigit():
        funcionario = buscar_funcionario_por_id(int(profissional_id))
        if funcionario:
            profissional_nome = str(funcionario.get("nome") or "")
    return {
        "cliente_nome": str(request.form.get("cliente_nome") or "").strip(),
        "cliente_telefone": str(request.form.get("cliente_telefone") or "").strip(),
        "servico_id": str(servico.get("id") or "") if servico else "",
        "servico_nome": str(servico.get("nome") or "") if servico else str(request.form.get("servico_nome") or "").strip(),
        "duracao_minutos": str(duracao_minutos),
        "profissional_id": profissional_id,
        "profissional_nome": profissional_nome,
        "data_agendamento": data_agendamento,
        "hora_inicio": hora_inicio,
        "hora_fim": hora_fim,
        "status": str(request.form.get("status") or "agendado").strip() or "agendado",
        "valor": str(request.form.get("valor") or (servico or {}).get("valor_venda") or "").strip(),
        "observacoes": str(request.form.get("observacoes") or "").strip(),
        "origem": str(request.form.get("origem") or "manual").strip() or "manual",
    }


def validar_disponibilidade_dados_agendamento(dados: dict[str, str], ignorar_agendamento_id: Any = "") -> str:
    empresa_id = empresa_logada_id()
    inicio = _minutos_hora_agendamento(dados.get("hora_inicio"), -1)
    fim = _minutos_hora_agendamento(dados.get("hora_fim"), -1)
    if inicio < 0 or fim <= inicio:
        return "O horário final calculado para o serviço é inválido."
    profissional_id, profissional_nome = resolver_profissional_agendamento(
        empresa_id, dados["data_agendamento"], dados.get("profissional_id"), inicio, fim, ignorar_agendamento_id
    )
    if profissional_id == "__indisponivel__" or (listar_profissionais_agendamento_empresa(empresa_id) and not profissional_id):
        return "Não existe profissional disponível durante todo o período deste atendimento."
    if profissional_id:
        dados["profissional_id"] = profissional_id
        dados["profissional_nome"] = profissional_nome
    return ""


