def bloqueio_nova_jornada_ponto_segundos(registro: dict[str, Any] | None) -> int:
    if not registro or not str(registro.get("saida") or "").strip():
        return 0

    atualizado_em = str(registro.get("atualizado_em") or "").strip()
    if not atualizado_em:
        return 0

    try:
        finalizado_em = datetime.fromisoformat(atualizado_em)
    except ValueError:
        return 0

    empresa_id = int(registro.get("empresa_id") or session.get("empresa_id") or 0)
    bloqueio_configurado = int(float(valor_configuracao_modulo(
        "registro_ponto", "bloqueio_entre_marcacoes_segundos",
        PONTO_BLOQUEIO_NOVA_JORNADA_SEGUNDOS, empresa_id or None,
    ) or PONTO_BLOQUEIO_NOVA_JORNADA_SEGUNDOS))
    restante = bloqueio_configurado - int(
        (agora_empresa() - finalizado_em).total_seconds()
    )
    return max(restante, 0)


def normalizar_coordenada_ponto(valor: Any, minimo: float, maximo: float) -> str:
    texto = str(valor or "").strip().replace(",", ".")

    if not texto:
        return ""

    try:
        numero = float(texto)
    except (TypeError, ValueError):
        return ""

    if numero < minimo or numero > maximo:
        return ""

    return f"{numero:.7f}"


def normalizar_precisao_ponto(valor: Any) -> str:
    texto = str(valor or "").strip().replace(",", ".")

    if not texto:
        return ""

    try:
        numero = float(texto)
    except (TypeError, ValueError):
        return ""

    if numero < 0:
        return ""

    return f"{numero:.2f}"


def registrar_batida_ponto_publico(
    funcionario: dict[str, Any],
    acao: str,
    data_ponto: Any = "",
    hora_ponto: Any = "",
    origem: str = "online",
    offline_uuid: Any = "",
    dispositivo_info: Any = "",
    latitude: Any = "",
    longitude: Any = "",
    precisao: Any = "",
) -> tuple[bool, str, dict[str, Any] | None]:
    funcionario_id = int(funcionario.get("id") or 0)
    empresa_id = int(funcionario.get("empresa_id") or 0)
    acao = str(acao or "").strip()
    data_final = _normalizar_data_iso(data_ponto, hoje_empresa().isoformat())
    hora_final = _normalizar_hora_hhmm(hora_ponto) or agora_empresa().strftime("%H:%M")
    origem_final = "offline" if str(origem or "").strip() == "offline" else "online"
    uuid_final = str(offline_uuid or "").strip()
    dispositivo_final = str(dispositivo_info or "").strip()[:500]
    latitude_final = normalizar_coordenada_ponto(latitude, -90, 90)
    longitude_final = normalizar_coordenada_ponto(longitude, -180, 180)
    precisao_final = normalizar_precisao_ponto(precisao)
    localizacao_valida = bool(latitude_final and longitude_final)
    coluna_latitude = f"{acao}_latitude"
    coluna_longitude = f"{acao}_longitude"
    coluna_precisao = f"{acao}_precisao"
    ordem = ordem_ponto_funcionario(funcionario)

    if acao not in ordem:
        if not ponto_exige_intervalo(funcionario) and acao in {
            "saida_intervalo",
            "retorno_intervalo",
        }:
            return (
                False,
                "Este funcionário não exige marcação de intervalo/almoço.",
                None,
            )

        return False, "Ação de ponto inválida.", None

    if not funcionario_id or not empresa_id:
        return False, "Funcionário inválido.", None

    if origem_final == "offline" and not configuracao_bool("registro_ponto", "permitir_offline", True, empresa_id):
        return False, "O ponto offline está desativado pela empresa.", None

    if configuracao_bool("registro_ponto", "gps_obrigatorio", True, empresa_id) and not localizacao_valida:
        return False, "Ative a localização do celular para registrar o ponto.", None
    if localizacao_valida and not validar_local_autorizado_ponto(empresa_id, latitude_final, longitude_final):
        return False, "Você está fora do raio permitido para registrar o ponto.", None

    with conectar_db() as conn:
        if uuid_final:
            duplicado = conn.execute(
                """
                SELECT *
                FROM registros_ponto
                WHERE empresa_id = ?
                  AND offline_uuid = ?
                LIMIT 1
                """,
                (empresa_id, uuid_final),
            ).fetchone()
            if duplicado is not None:
                return True, "Batida offline já sincronizada.", dict(duplicado)

        row = conn.execute(
            """
            SELECT *
            FROM registros_ponto
            WHERE empresa_id = ? AND funcionario_id = ? AND data_ponto = ?
            ORDER BY id DESC
            LIMIT 1
            """,
            (empresa_id, funcionario_id, data_final),
        ).fetchone()
        registro = dict(row) if row else None

        if registro is not None and str(registro.get("saida") or "").strip():
            if acao != "entrada":
                return False, "A jornada anterior foi finalizada. Registre uma nova entrada.", registro
            if not configuracao_bool("registro_ponto", "multiplas_jornadas", True, empresa_id):
                return False, "A empresa não permite mais de uma jornada no mesmo dia.", registro

            bloqueio_restante = bloqueio_nova_jornada_ponto_segundos(registro)
            if bloqueio_restante > 0:
                return (
                    False,
                    f"Nova entrada para hora extra liberada em {bloqueio_restante} segundo(s).",
                    registro,
                )

            registro = None

        if registro is not None and registro.get(acao):
            if origem_final == "offline" and str(registro.get(acao) or "").strip() == hora_final:
                return True, "Batida offline já estava registrada.", registro
            return False, "Esse horário já foi registrado.", registro

        if registro is None and acao != "entrada":
            return False, "Registre a entrada antes dos demais horários.", None

        agora_iso = agora_empresa().isoformat(timespec="seconds")

        if registro is None:
            conn.execute(
                """
                INSERT INTO registros_ponto (
                    empresa_id, funcionario_id, funcionario_nome, data_ponto, entrada,
                    status, observacoes, atualizado_em, origem, offline_uuid, sincronizado_em, dispositivo_info,
                    entrada_latitude, entrada_longitude, entrada_precisao
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    funcionario_id,
                    str(funcionario.get("nome") or ""),
                    data_final,
                    hora_final,
                    "incompleto",
                    "Batida registrada offline." if origem_final == "offline" else "",
                    agora_iso,
                    origem_final,
                    uuid_final,
                    agora_iso if origem_final == "offline" else "",
                    dispositivo_final,
                    latitude_final if localizacao_valida else "",
                    longitude_final if localizacao_valida else "",
                    precisao_final if localizacao_valida else "",
                ),
            )
        else:
            dados = dict(registro)
            dados[acao] = hora_final
            total = _calcular_total_horas_ponto(dados.get("entrada"), dados.get("saida_intervalo"), dados.get("retorno_intervalo"), dados.get("saida"))
            status = _status_ponto(dados.get("entrada"), dados.get("saida_intervalo"), dados.get("retorno_intervalo"), dados.get("saida"))
            observacoes = str(registro.get("observacoes") or "").strip()
            if origem_final == "offline" and "Batida registrada offline." not in observacoes:
                observacoes = (observacoes + "\n" if observacoes else "") + "Batida registrada offline."

            conn.execute(
                f"""
                UPDATE registros_ponto
                SET {acao} = ?, total_trabalhado = ?, status = ?, observacoes = ?, atualizado_em = ?,
                    origem = CASE WHEN origem = 'offline' OR ? = 'offline' THEN 'offline' ELSE COALESCE(NULLIF(origem, ''), 'online') END,
                    offline_uuid = COALESCE(NULLIF(offline_uuid, ''), ?),
                    sincronizado_em = CASE WHEN ? = 'offline' THEN ? ELSE sincronizado_em END,
                    dispositivo_info = COALESCE(NULLIF(dispositivo_info, ''), ?),
                    {coluna_latitude} = CASE WHEN ? THEN ? ELSE {coluna_latitude} END,
                    {coluna_longitude} = CASE WHEN ? THEN ? ELSE {coluna_longitude} END,
                    {coluna_precisao} = CASE WHEN ? THEN ? ELSE {coluna_precisao} END
                WHERE id = ? AND empresa_id = ?
                """,
                (
                    hora_final,
                    total,
                    status,
                    observacoes,
                    agora_iso,
                    origem_final,
                    uuid_final,
                    origem_final,
                    agora_iso,
                    dispositivo_final,
                    localizacao_valida,
                    latitude_final,
                    localizacao_valida,
                    longitude_final,
                    localizacao_valida,
                    precisao_final,
                    registro["id"],
                    empresa_id,
                ),
            )

        conn.commit()

    atualizado = buscar_registro_ponto_publico(empresa_id, funcionario_id, data_final)
    return True, f"{PONTO_ACOES.get(acao, 'Ponto')} registrado às {hora_final}.", atualizado


def bater_ponto_db(funcionario_id: int, acao: str = "") -> tuple[bool, str]:
    funcionario = buscar_funcionario_por_id(funcionario_id)
    if funcionario is None:
        return False, "Funcionário não encontrado."

    hoje = hoje_empresa().isoformat()
    agora_hora = agora_empresa().strftime("%H:%M")
    registro = buscar_registro_ponto(funcionario_id, hoje)
    ordem = ordem_ponto_funcionario(funcionario)

    if registro is not None and str(registro.get("saida") or "").strip():
        if acao and acao != "entrada":
            return False, "A jornada anterior foi finalizada. Registre uma nova entrada."

        bloqueio_restante = bloqueio_nova_jornada_ponto_segundos(registro)
        if bloqueio_restante > 0:
            return False, f"Nova entrada para hora extra liberada em {bloqueio_restante} segundo(s)."

        registro = None
        acao = "entrada"

    if acao not in ordem:
        if registro is None:
            acao = "entrada"
        else:
            acao = next((campo for campo in ordem if not registro.get(campo)), "")

    if not acao:
        return False, "Ponto de hoje já está completo."

    if registro is not None and registro.get(acao):
        return False, "Esse horário já foi registrado."

    if registro is None and acao != "entrada":
        return False, "Registre a entrada antes dos demais horários."

    with conectar_db() as conn:
        if registro is None:
            conn.execute(
                """
                INSERT INTO registros_ponto (
                    empresa_id, funcionario_id, funcionario_nome, data_ponto, entrada,
                    status, atualizado_em
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (empresa_logada_id(), funcionario_id, funcionario["nome"], hoje, agora_hora, "incompleto", agora_empresa().isoformat(timespec="seconds")),
            )
        else:
            dados = dict(registro)
            dados[acao] = agora_hora
            total = _calcular_total_horas_ponto(dados.get("entrada"), dados.get("saida_intervalo"), dados.get("retorno_intervalo"), dados.get("saida"))
            status = _status_ponto(dados.get("entrada"), dados.get("saida_intervalo"), dados.get("retorno_intervalo"), dados.get("saida"))
            conn.execute(
                f"""
                UPDATE registros_ponto
                SET {acao} = ?, total_trabalhado = ?, status = ?, atualizado_em = ?
                WHERE id = ? AND empresa_id = ?
                """,
                (agora_hora, total, status, agora_empresa().isoformat(timespec="seconds"), registro["id"], empresa_logada_id()),
            )
        conn.commit()

    return True, f"{PONTO_ACOES.get(acao, 'Ponto')} registrado às {agora_hora}."


def ajustar_ponto_db() -> tuple[bool, str]:
    funcionario_id_texto = str(request.form.get("ajuste_funcionario_id") or "").strip()
    if not funcionario_id_texto.isdigit():
        return False, "Selecione o funcionário para ajustar o ponto."
    funcionario = buscar_funcionario_por_id(int(funcionario_id_texto))
    if funcionario is None:
        return False, "Funcionário não encontrado."

    data_ponto = _normalizar_data_iso(request.form.get("ajuste_data_ponto"))
    entrada = _normalizar_hora_hhmm(request.form.get("ajuste_entrada"))
    saida_intervalo = _normalizar_hora_hhmm(request.form.get("ajuste_saida_intervalo"))
    retorno_intervalo = _normalizar_hora_hhmm(request.form.get("ajuste_retorno_intervalo"))
    saida = _normalizar_hora_hhmm(request.form.get("ajuste_saida"))
    observacoes = str(request.form.get("ajuste_observacoes") or "").strip()
    total = _calcular_total_horas_ponto(entrada, saida_intervalo, retorno_intervalo, saida)
    status = _status_ponto(entrada, saida_intervalo, retorno_intervalo, saida, ajustado=True)
    existente = buscar_registro_ponto(int(funcionario_id_texto), data_ponto)

    with conectar_db() as conn:
        if existente:
            conn.execute(
                """
                UPDATE registros_ponto
                SET funcionario_nome = ?, entrada = ?, saida_intervalo = ?, retorno_intervalo = ?,
                    saida = ?, total_trabalhado = ?, status = ?, observacoes = ?, ajustado_por = ?, atualizado_em = ?
                WHERE id = ? AND empresa_id = ?
                """,
                (funcionario["nome"], entrada, saida_intervalo, retorno_intervalo, saida, total, status, observacoes, session.get("usuario_nome") or "Administrador", agora_empresa().isoformat(timespec="seconds"), existente["id"], empresa_logada_id()),
            )
        else:
            conn.execute(
                """
                INSERT INTO registros_ponto (
                    empresa_id, funcionario_id, funcionario_nome, data_ponto, entrada, saida_intervalo,
                    retorno_intervalo, saida, total_trabalhado, status, observacoes, ajustado_por, atualizado_em
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (empresa_logada_id(), int(funcionario_id_texto), funcionario["nome"], data_ponto, entrada, saida_intervalo, retorno_intervalo, saida, total, status, observacoes, session.get("usuario_nome") or "Administrador", agora_empresa().isoformat(timespec="seconds")),
            )
        conn.commit()

    return True, "Ponto ajustado com sucesso."


