def url_retorno_configuracao_modulo(
    codigo: str,
    **parametros_extras: Any,
) -> str:
    grupo = CONFIGURACOES_GRUPO_POR_MODULO.get(str(codigo or "").strip().lower(), "sistema")
    parametros = {"modulo": codigo, **parametros_extras}
