@app.route("/configuracoes/usuarios/<int:usuario_id>/editar", methods=["GET", "POST"])
def editar_usuario_configuracoes(usuario_id: int) -> str | Response:
    usuario = buscar_usuario_configuracoes_por_id(usuario_id)
    if usuario is None:
        return redirecionar_configuracoes_usuarios(
            erro="Usuário não encontrado nesta empresa."
        )

    erro = ""
    formulario: dict[str, Any] = dict(usuario)
    formulario["senha"] = ""
    formulario["confirmar_senha"] = ""
    selecionadas = permissoes_selecionadas_usuario(usuario)

    if request.method == "POST":
        dados = montar_usuario_configuracoes_formulario()
        erro = validar_usuario_configuracoes_formulario(dados, usuario_id)
        permissoes_json = montar_permissoes_usuario_formulario(dados["perfil"])
        permissoes_form = normalizar_permissoes_usuario(permissoes_json)
        selecionadas = {
            f"{modulo}:{acao}"
            for modulo, acoes in (permissoes_form or {}).items()
            for acao in acoes
        }
        formulario = dict(dados)
        formulario["id"] = usuario_id

        mudara_para_sem_admin = (
            dados["status"] != "ativo"
            or dados["perfil"] not in {"administrador", "super_admin"}
        )
        usuario_atual_admin = usuario["status"] == "ativo" and usuario["perfil"] in {
            "administrador",
            "super_admin",
        }

        if (
            not erro
            and usuario_atual_admin
            and mudara_para_sem_admin
            and contar_administradores_ativos_empresa(usuario_id) == 0
        ):
            erro = "A empresa precisa manter ao menos um administrador ativo."

        if (
            not erro
            and usuario_id == usuario_logado_id()
            and dados["status"] != "ativo"
        ):
            erro = "Você não pode inativar o próprio usuário."

        if not erro:
            atualizar_usuario_configuracoes_db(usuario_id, dados, permissoes_json)
            registrar_atividade_usuario(
                "edicao",
                "configuracoes",
                f"Editou o usuário {dados['nome']}",
                registro_id=usuario_id,
                dados_anteriores={
                    "nome": usuario.get("nome"),
                    "email": usuario.get("email"),
                    "perfil": usuario.get("perfil"),
                    "status": usuario.get("status"),
                    "funcionario_id": usuario.get("funcionario_id"),
                    "permissoes_json": usuario.get("permissoes_json"),
                },
                dados_novos={
                    "nome": dados["nome"],
                    "email": dados["email"],
                    "perfil": dados["perfil"],
                    "status": dados["status"],
                    "funcionario_id": dados.get("funcionario_id"),
                    "permissoes_json": permissoes_json,
                    "senha_alterada": bool(dados.get("senha")),
                },
            )
            return redirecionar_configuracoes_usuarios(
                sucesso="Usuário atualizado com sucesso."
            )

    return render_template(
        "usuario_editar.html",
        usuario=usuario,
        formulario=formulario,
        erro=erro,
        perfis_usuario=perfis_disponiveis_para_gestao(),
        modulos_permissoes=GESTFLOW_MODULOS_PERMISSOES,
        acoes_permissao=GESTFLOW_ACOES_PERMISSAO,
        permissoes_selecionadas=selecionadas,
        funcionarios=listar_funcionarios_vinculo_usuario(),
    )


@app.post("/configuracoes/usuarios/<int:usuario_id>/status")
def alterar_status_usuario_configuracoes(usuario_id: int) -> Response:
    usuario = buscar_usuario_configuracoes_por_id(usuario_id)
    if usuario is None:
        return redirecionar_configuracoes_usuarios(
            erro="Usuário não encontrado nesta empresa."
        )

    novo_status = str(request.form.get("status") or "").strip().lower()
    if novo_status not in {"ativo", "inativo"}:
        return redirecionar_configuracoes_usuarios(
            erro="Status de usuário inválido."
        )

    if usuario_id == usuario_logado_id() and novo_status == "inativo":
        return redirecionar_configuracoes_usuarios(
            erro="Você não pode inativar o próprio usuário."
        )

    if (
        usuario["status"] == "ativo"
        and usuario["perfil"] in {"administrador", "super_admin"}
        and novo_status == "inativo"
        and contar_administradores_ativos_empresa(usuario_id) == 0
    ):
        return redirecionar_configuracoes_usuarios(
            erro="A empresa precisa manter ao menos um administrador ativo."
        )

    with conectar_db() as conn:
        conn.execute(
            """
            UPDATE usuarios
            SET status = ?, atualizado_em = ?
            WHERE id = ? AND empresa_id = ?
            """,
            (
                novo_status,
                agora_empresa().isoformat(timespec="seconds"),
                usuario_id,
                empresa_logada_id(),
            ),
        )
        conn.commit()

    registrar_atividade_usuario(
        "edicao",
        "configuracoes",
        f"Alterou o status do usuário {usuario['nome']} para {novo_status}",
        registro_id=usuario_id,
        dados_anteriores={"status": usuario.get("status")},
        dados_novos={"status": novo_status},
    )
    return redirecionar_configuracoes_usuarios(
        sucesso="Status do usuário atualizado."
    )


@app.post("/configuracoes/usuarios/redefinir-senha")
def redefinir_senha_usuario_configuracoes() -> Response:
    try:
        usuario_id = int(request.form.get("usuario_id") or 0)
    except (TypeError, ValueError):
        usuario_id = 0

    nova_senha = (request.form.get("nova_senha") or "").strip()
    confirmar_senha = (request.form.get("confirmar_senha") or "").strip()

    usuario = buscar_usuario_configuracoes_por_id(usuario_id)

    if usuario is None:
        return redirecionar_configuracoes_usuarios(
            erro="Usuário não encontrado nesta empresa."
        )

    erro_senha = validar_senha_forte(nova_senha)
    if erro_senha:
        return redirecionar_configuracoes_usuarios(erro=erro_senha)

    if nova_senha != confirmar_senha:
        return redirecionar_configuracoes_usuarios(
            erro="A confirmação da senha não confere."
        )

    redefinir_senha_usuario_configuracoes_db(usuario_id, nova_senha)
    registrar_atividade_usuario(
        "edicao",
        "configuracoes",
        f"Redefiniu a senha do usuário {usuario['nome']}",
        registro_id=usuario_id,
        dados_novos={"senha_redefinida": True},
    )

    return redirecionar_configuracoes_usuarios(
        sucesso="Senha redefinida com sucesso. O usuário deverá entrar novamente."
    )


@app.get("/sair")
def sair() -> Response:
    session.clear()
    return redirect(url_for("login"))


@app.route("/onboarding", methods=["GET", "POST"])
def onboarding() -> str | Response:
    if not session.get("usuario_id"):
        return redirect(url_for("login"))

    empresa = buscar_onboarding_empresa()

    if request.method == "POST":
        dados = montar_onboarding_formulario()
        salvar_onboarding_empresa_db(dados)
        return redirect(url_for("dashboard", tour="1"))

    return render_template(
        "onboarding.html",
        empresa=empresa,
        segmentos=GESTFLOW_SEGMENTOS,
        niveis_onboarding=GESTFLOW_NIVEIS_ONBOARDING,
        modulos_sistema=GESTFLOW_MODULOS,
    )


@app.post("/tour/concluir")
def concluir_tour() -> Response:
    if not session.get("usuario_id"):
        return jsonify({"ok": False}), 401

    marcar_tour_concluido_db()
    return jsonify({"ok": True})


@app.get("/")
def dashboard() -> str | Response:
    if empresa_precisa_onboarding():
        return redirect(url_for("onboarding"))

    dados_dashboard = montar_dashboard()
    iniciar_tour = empresa_precisa_tour() or request.args.get("tour") == "1"

    return render_template(
        "dashboard.html",
        dashboard=dados_dashboard,
        iniciar_tour=iniciar_tour,
    )



def normalizar_slug_vitrine(valor: Any) -> str:
    texto = str(valor or "").strip().lower()
    texto = unicodedata.normalize("NFKD", texto)
    texto = "".join(caractere for caractere in texto if not unicodedata.combining(caractere))
    texto = re.sub(r"[^a-z0-9]+", "-", texto)
    texto = texto.strip("-")
    return texto[:80]


def extensao_arquivo_permitida(nome_arquivo: str, extensoes: set[str]) -> bool:
    nome = str(nome_arquivo or "").strip().lower()
    return "." in nome and nome.rsplit(".", 1)[-1] in extensoes


def salvar_logo_vitrine_upload() -> str:
    arquivo = request.files.get("logo_loja")

    if arquivo is None or not arquivo.filename:
        return ""

    if not extensao_arquivo_permitida(arquivo.filename, EXTENSOES_LOGO_PERMITIDAS):
        return ""

    empresa_id = empresa_logada_id()
    nome_seguro = secure_filename(arquivo.filename)
    extensao = nome_seguro.rsplit(".", 1)[-1].lower()
    nome_final = f"vitrine_empresa_{empresa_id}_{int(datetime.now().timestamp())}.{extensao}"
    caminho_final = VITRINE_UPLOAD_DIR / nome_final
    arquivo.save(caminho_final)
    return f"uploads/vitrines/{nome_final}"


def montar_vitrine_formulario(config_atual: dict[str, Any] | None = None) -> dict[str, str]:
    config_atual = config_atual or {}
    nome_loja = (request.form.get("nome_loja") or "").strip()
    slug = normalizar_slug_vitrine(request.form.get("slug") or nome_loja)

    if not slug:
        slug = f"loja-{empresa_logada_id()}"

    tipo_identidade_visual = (request.form.get("tipo_identidade_visual") or "cores").strip().lower()
    if tipo_identidade_visual not in {"logo", "cores"}:
        tipo_identidade_visual = "cores"

    logo_path = salvar_logo_vitrine_upload() or str(config_atual.get("logo_path") or "")
    if tipo_identidade_visual == "logo" and not logo_path:
        raise ValueError("Envie uma logo antes de usar a identidade visual por logo.")

    cor_principal_atual = str(config_atual.get("cor_principal") or "#111827").strip() or "#111827"
    cor_secundaria_atual = str(config_atual.get("cor_secundaria") or "#f59e0b").strip() or "#f59e0b"

    return {
        "nome_loja": nome_loja,
        "whatsapp": (request.form.get("whatsapp") or "").strip(),
        "instagram": (request.form.get("instagram") or "").strip(),
        "slug": slug,
        "logo_path": logo_path,
        "categoria": (request.form.get("categoria") or "").strip(),
        "descricao_empresa": (request.form.get("descricao_empresa") or "").strip()[:600],
        "tipo_identidade_visual": tipo_identidade_visual,
        "cor_principal": (request.form.get("cor_principal") or cor_principal_atual).strip() or cor_principal_atual,
        "cor_secundaria": (request.form.get("cor_secundaria") or cor_secundaria_atual).strip() or cor_secundaria_atual,
        "template": "catalogo-premium",
        "status": (request.form.get("status") or "rascunho").strip() or "rascunho",
    }


