def remover_arquivo_imagem_vitrine(caminho_relativo: Any) -> None:
    caminho_texto = str(caminho_relativo or "").strip().replace("\\", "/")
    prefixo_permitido = "uploads/vitrines/"

    if not caminho_texto.startswith(prefixo_permitido):
        return

    nome_arquivo = Path(caminho_texto).name
    caminho_arquivo = (VITRINE_UPLOAD_DIR / nome_arquivo).resolve()
    diretorio_vitrine = VITRINE_UPLOAD_DIR.resolve()

    if caminho_arquivo.parent != diretorio_vitrine:
        return

    try:
        caminho_arquivo.unlink(missing_ok=True)
    except OSError:
        app.logger.exception("Não foi possível remover a imagem da vitrine: %s", caminho_texto)


def salvar_imagem_produto_vitrine_upload(produto_id: int) -> str:
    arquivo = request.files.get("imagem_produto")

    if arquivo is None or not arquivo.filename:
        return ""

    if not extensao_arquivo_permitida(arquivo.filename, EXTENSOES_FOTO_VITRINE_PERMITIDAS):
        return ""

    empresa_id = empresa_logada_id()
    nome_seguro = secure_filename(arquivo.filename)
    extensao = nome_seguro.rsplit(".", 1)[-1].lower()
    nome_final = f"vitrine_produto_{empresa_id}_{produto_id}_{int(datetime.now().timestamp())}.{extensao}"
    caminho_final = VITRINE_UPLOAD_DIR / nome_final
    arquivo.save(caminho_final)
    return f"uploads/vitrines/{nome_final}"


def salvar_produto_vitrine_publicacao_db(produto_id: int, dados: dict[str, Any]) -> None:
    empresa_id = empresa_logada_id()
    produto = buscar_produto_vitrine_admin(produto_id)

    if produto is None:
        return

    atualizado_em = agora_empresa().isoformat(timespec="seconds")

    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT id, imagem_path
            FROM vitrine_produtos
            WHERE empresa_id = ?
              AND produto_id = ?
            LIMIT 1
            """,
            (empresa_id, produto_id),
        ).fetchone()

        imagem_anterior = str(row["imagem_path"] or "").strip() if row is not None else ""
        remover_imagem = str(dados.get("remover_imagem") or "").strip().lower() == "sim"
        imagem_path = str(dados.get("imagem_path") or "").strip()

        if remover_imagem:
            imagem_path = ""
        elif not imagem_path:
            imagem_path = imagem_anterior

        valores = (
            str(dados.get("nome") or produto.get("nome") or "").strip(),
            str(dados.get("descricao") or produto.get("observacoes") or "").strip(),
            str(dados.get("categoria") or produto.get("categoria") or "Produtos").strip(),
            str(dados.get("preco") or produto.get("preco_venda") or "0,00").strip(),
            imagem_path,
            str(dados.get("destaque") or "nao").strip() or "nao",
            str(dados.get("status") or "publicado").strip() or "publicado",
            atualizado_em,
        )

        if row is None:
            conn.execute(
                """
                INSERT INTO vitrine_produtos (
                    empresa_id,
                    produto_id,
                    nome,
                    descricao,
                    categoria,
                    preco,
                    imagem_path,
                    destaque,
                    status,
                    atualizado_em
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (empresa_id, produto_id, *valores),
            )
        else:
            conn.execute(
                """
                UPDATE vitrine_produtos
                SET
                    nome = ?,
                    descricao = ?,
                    categoria = ?,
                    preco = ?,
                    imagem_path = ?,
                    destaque = ?,
                    status = ?,
                    atualizado_em = ?
                WHERE empresa_id = ?
                  AND produto_id = ?
                """,
                (*valores, empresa_id, produto_id),
            )

        conn.commit()

    if remover_imagem and imagem_anterior:
        remover_arquivo_imagem_vitrine(imagem_anterior)


