def montar_central_vitrine_admin(empresa_id: int) -> dict[str, Any]:
    with conectar_db() as conn:
        pedidos_rows = conn.execute(
            """
            SELECT
                p.*,
                v.numero AS venda_numero
            FROM vitrine_pedidos p
            LEFT JOIN vendas v
              ON v.id = p.venda_id
             AND v.empresa_id = p.empresa_id
            WHERE p.empresa_id = ?
            ORDER BY p.id DESC
            LIMIT 100
            """,
            (empresa_id,),
        ).fetchall()
        pedido_ids = [int(row["id"]) for row in pedidos_rows]
        itens_por_pedido: dict[int, list[dict[str, Any]]] = {
            pedido_id: [] for pedido_id in pedido_ids
        }
        if pedido_ids:
            placeholders = ",".join("?" for _ in pedido_ids)
            itens_rows = conn.execute(
                f"""
                SELECT *
                FROM vitrine_pedido_itens
                WHERE empresa_id = ?
                  AND pedido_id IN ({placeholders})
                ORDER BY pedido_id DESC, id ASC
                """,
                (empresa_id, *pedido_ids),
            ).fetchall()
            for row in itens_rows:
                item = dict(row)
                itens_por_pedido.setdefault(int(item["pedido_id"]), []).append(item)

        agendamentos_rows = conn.execute(
            """
            SELECT
                a.*,
                v.numero AS venda_numero
            FROM agendamentos a
            LEFT JOIN vendas v
              ON v.id = a.venda_id
             AND v.empresa_id = a.empresa_id
            WHERE a.empresa_id = ?
              AND a.origem IN ('vitrine_online', 'avaliacao_vitrine')
            ORDER BY a.id DESC
            LIMIT 100
            """,
            (empresa_id,),
        ).fetchall()
        solicitacoes_rows = conn.execute(
            """
            SELECT *
            FROM solicitacoes_avaliacao
            WHERE empresa_id = ?
              AND origem = 'vitrine_online'
            ORDER BY id DESC
            LIMIT 100
            """,
            (empresa_id,),
        ).fetchall()
        eventos_rows = conn.execute(
            """
            SELECT
                e.*,
                CASE
                    WHEN e.tipo IN ('produto', 'carrinho', 'pedido') THEN (
                        SELECT COALESCE(
                            (
                                SELECT vp_id.nome
                                FROM vitrine_produtos vp_id
                                WHERE vp_id.empresa_id = e.empresa_id
                                  AND vp_id.id = e.produto_id
                                LIMIT 1
                            ),
                            (
                                SELECT vp_produto.nome
                                FROM vitrine_produtos vp_produto
                                WHERE vp_produto.empresa_id = e.empresa_id
                                  AND vp_produto.produto_id = e.produto_id
                                LIMIT 1
                            )
                        )
                    )
                    WHEN e.tipo IN ('servico', 'agendamento') THEN (
                        SELECT COALESCE(
                            (
                                SELECT vs_id.nome
                                FROM vitrine_servicos vs_id
                                WHERE vs_id.empresa_id = e.empresa_id
                                  AND vs_id.id = e.servico_id
                                LIMIT 1
                            ),
                            (
                                SELECT vs_servico.nome
                                FROM vitrine_servicos vs_servico
                                WHERE vs_servico.empresa_id = e.empresa_id
                                  AND vs_servico.servico_id = e.servico_id
                                LIMIT 1
                            )
                        )
                    )
                    ELSE ''
                END AS item_nome
            FROM vitrine_eventos e
            WHERE e.empresa_id = ?
            ORDER BY e.id DESC
            LIMIT 200
            """,
            (empresa_id,),
        ).fetchall()

    pedidos: list[dict[str, Any]] = []
    for row in pedidos_rows:
        pedido = dict(row)
        pedido_id = int(pedido["id"])
        pedido["itens"] = itens_por_pedido.get(pedido_id, [])
        pedido["criado_em_exibicao"] = formatar_data_hora_br(pedido.get("criado_em"))
        pedido["atendimento_iniciado_em_exibicao"] = formatar_data_hora_br(
            pedido.get("atendimento_iniciado_em")
        )
        pedido["concluido_em_exibicao"] = formatar_data_hora_br(pedido.get("concluido_em"))
        pedido["cancelado_em_exibicao"] = formatar_data_hora_br(pedido.get("cancelado_em"))
        telefone = normalizar_telefone_publico(pedido.get("cliente_whatsapp"))
        if telefone and not telefone.startswith("55"):
            telefone = f"55{telefone}"
        pedido["whatsapp_url"] = f"https://wa.me/{telefone}" if telefone else ""
        pedidos.append(pedido)

    agendamentos: list[dict[str, Any]] = []
    for row in agendamentos_rows:
        agendamento = dict(row)
        agendamento["data_exibicao"] = formatar_data_br(agendamento.get("data_agendamento"))
        agendamento["criado_em_exibicao"] = formatar_data_hora_br(agendamento.get("criado_em"))
        agendamento["confirmado_em_exibicao"] = formatar_data_hora_br(
            agendamento.get("confirmado_em")
        )
        agendamento["atendimento_iniciado_em_exibicao"] = formatar_data_hora_br(
            agendamento.get("atendimento_iniciado_em")
        )
        agendamento["concluido_em_exibicao"] = formatar_data_hora_br(
            agendamento.get("concluido_em")
        )
        agendamento["cancelado_em_exibicao"] = formatar_data_hora_br(
            agendamento.get("cancelado_em")
        )
        agendamento["nao_compareceu_em_exibicao"] = formatar_data_hora_br(
            agendamento.get("nao_compareceu_em")
        )
        telefone = normalizar_telefone_publico(agendamento.get("cliente_telefone"))
        if telefone and not telefone.startswith("55"):
            telefone = f"55{telefone}"
        agendamento["whatsapp_url"] = f"https://wa.me/{telefone}" if telefone else ""
        agendamentos.append(agendamento)

    solicitacoes: list[dict[str, Any]] = []
    for row in solicitacoes_rows:
        solicitacao = dict(row)
        solicitacao["data_exibicao"] = formatar_data_br(solicitacao.get("data_desejada"))
        solicitacao["criado_em_exibicao"] = formatar_data_hora_br(solicitacao.get("criado_em"))
        telefone = normalizar_telefone_publico(solicitacao.get("cliente_telefone"))
        if telefone and not telefone.startswith("55"):
            telefone = f"55{telefone}"
        solicitacao["whatsapp_url"] = f"https://wa.me/{telefone}" if telefone else ""
        solicitacoes.append(solicitacao)

    eventos = []
    for row in eventos_rows:
        evento = dict(row)
        evento["criado_em_exibicao"] = formatar_data_hora_br(evento.get("criado_em"))
        eventos.append(evento)

    return {
        "pedidos": pedidos,
        "agendamentos": agendamentos,
        "solicitacoes": solicitacoes,
        "eventos": eventos,
        "visitas": [item for item in eventos if item.get("tipo") == "visita"],
        "visualizacoes": [
            item for item in eventos if item.get("tipo") in {"produto", "servico"}
        ],
        "carrinhos": [item for item in eventos if item.get("tipo") == "carrinho"],
        "novos_pedidos": sum(1 for item in pedidos if item.get("status") == "novo"),
        "pedidos_em_atendimento": sum(
            1 for item in pedidos if item.get("status") == "em_atendimento"
        ),
        "pedidos_concluidos": sum(
            1 for item in pedidos if item.get("status") == "concluido"
        ),
        "pedidos_cancelados": sum(
            1 for item in pedidos if item.get("status") == "cancelado"
        ),
        "agendamentos_pendentes": sum(
            1
            for item in agendamentos
            if item.get("status") not in {"concluido", "cancelado", "nao_compareceu"}
        ),
        "solicitacoes_pendentes": sum(
            1
            for item in solicitacoes
            if item.get("status") in {"aguardando_avaliacao", "em_analise", "avaliada"}
        ),
    }


def registrar_evento_vitrine(empresa_id: int, tipo: str, item_id: Any = "", origem: Any = "") -> None:
    tipo_normalizado = str(tipo or "").strip().lower()
    if tipo_normalizado not in {"visita", "produto", "servico", "carrinho", "pedido", "agendamento"}:
        return
    item_numero = None
    try:
        if str(item_id or "").strip():
            item_numero = int(str(item_id).strip())
    except ValueError:
        item_numero = None
    produto_numero = item_numero if tipo_normalizado in {"produto", "carrinho", "pedido"} else None
    servico_numero = item_numero if tipo_normalizado in {"servico", "agendamento"} else None
    with conectar_db() as conn:
        conn.execute(
            """
            INSERT INTO vitrine_eventos (
                empresa_id, produto_id, servico_id, tipo, origem, user_agent
            ) VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id, produto_numero, servico_numero, tipo_normalizado,
                str(origem or "").strip()[:120],
                str(request.headers.get("User-Agent") or "")[:240],
            ),
        )
        if tipo_normalizado == "visita":
            conn.execute("UPDATE vitrine_configuracoes SET visitas = COALESCE(visitas, 0) + 1 WHERE empresa_id = ?", (empresa_id,))
        elif tipo_normalizado == "produto":
            conn.execute("UPDATE vitrine_configuracoes SET produtos_vistos = COALESCE(produtos_vistos, 0) + 1 WHERE empresa_id = ?", (empresa_id,))
            if item_numero is not None:
                conn.execute("UPDATE vitrine_produtos SET acessos = COALESCE(acessos, 0) + 1 WHERE empresa_id = ? AND (id = ? OR produto_id = ?)", (empresa_id, item_numero, item_numero))
        elif tipo_normalizado == "servico":
            conn.execute("UPDATE vitrine_configuracoes SET servicos_vistos = COALESCE(servicos_vistos, 0) + 1 WHERE empresa_id = ?", (empresa_id,))
            if item_numero is not None:
                conn.execute("UPDATE vitrine_servicos SET acessos = COALESCE(acessos, 0) + 1 WHERE empresa_id = ? AND (id = ? OR servico_id = ?)", (empresa_id, item_numero, item_numero))
        elif tipo_normalizado == "carrinho":
            conn.execute("UPDATE vitrine_configuracoes SET itens_carrinho = COALESCE(itens_carrinho, 0) + 1 WHERE empresa_id = ?", (empresa_id,))
            if item_numero is not None:
                conn.execute("UPDATE vitrine_produtos SET carrinhos = COALESCE(carrinhos, 0) + 1 WHERE empresa_id = ? AND (id = ? OR produto_id = ?)", (empresa_id, item_numero, item_numero))
        elif tipo_normalizado == "pedido":
            conn.execute("UPDATE vitrine_configuracoes SET pedidos_gerados = COALESCE(pedidos_gerados, 0) + 1 WHERE empresa_id = ?", (empresa_id,))
        conn.commit()


def salvar_pedido_vitrine_db(empresa_id: int, dados: dict[str, Any], itens: list[dict[str, Any]]) -> int:
    total = sum(float(item.get("subtotal_numero") or 0) for item in itens)

    with conectar_db() as conn:
        cursor = conn.execute(
            """
            INSERT INTO vitrine_pedidos (
                empresa_id,
                cliente_nome,
                cliente_whatsapp,
                tipo_entrega,
                endereco,
                forma_pagamento,
                observacoes,
                total,
                status
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                str(dados.get("cliente_nome") or "").strip(),
                str(dados.get("cliente_whatsapp") or "").strip(),
                str(dados.get("tipo_entrega") or "").strip(),
                str(dados.get("endereco") or "").strip(),
                str(dados.get("forma_pagamento") or "").strip(),
                str(dados.get("observacoes") or "").strip(),
                _formatar_moeda_brl(total),
                "novo",
            ),
        )
        pedido_id = int(cursor.lastrowid)

        for item in itens:
            produto_id = int(item.get("produto_id") or 0)
            conn.execute(
                """
                INSERT INTO vitrine_pedido_itens (
                    empresa_id,
                    pedido_id,
                    produto_id,
                    produto_nome,
                    quantidade,
                    valor_unitario,
                    subtotal
                ) VALUES (?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    pedido_id,
                    produto_id,
                    str(item.get("nome") or ""),
                    str(item.get("quantidade") or "1"),
                    str(item.get("preco") or "0,00"),
                    _formatar_moeda_brl(float(item.get("subtotal_numero") or 0)),
                ),
            )
            conn.execute(
                "UPDATE vitrine_produtos SET pedidos = COALESCE(pedidos, 0) + 1 WHERE empresa_id = ? AND (id = ? OR produto_id = ?)",
                (empresa_id, produto_id, produto_id),
            )

        conn.execute(
            "UPDATE vitrine_configuracoes SET pedidos_gerados = COALESCE(pedidos_gerados, 0) + 1 WHERE empresa_id = ?",
            (empresa_id,),
        )
        conn.commit()

    return pedido_id


def buscar_pedido_vitrine_admin(pedido_id: int) -> dict[str, Any] | None:
    empresa_id = empresa_logada_id()
    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT
                p.*,
                v.numero AS venda_numero
            FROM vitrine_pedidos p
            LEFT JOIN vendas v
              ON v.id = p.venda_id
             AND v.empresa_id = p.empresa_id
            WHERE p.id = ?
              AND p.empresa_id = ?
            LIMIT 1
            """,
            (pedido_id, empresa_id),
        ).fetchone()
        if row is None:
            return None
        itens_rows = conn.execute(
            """
            SELECT *
            FROM vitrine_pedido_itens
            WHERE pedido_id = ?
              AND empresa_id = ?
            ORDER BY id ASC
            """,
            (pedido_id, empresa_id),
        ).fetchall()

    pedido = dict(row)
    pedido["itens"] = [dict(item) for item in itens_rows]
    return pedido


def buscar_venda_por_pedido_vitrine_id(pedido_id: int) -> dict[str, Any] | None:
    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT id, numero, status
            FROM vendas
            WHERE empresa_id = ?
              AND origem_vitrine_pedido_id = ?
            LIMIT 1
            """,
            (empresa_logada_id(), pedido_id),
        ).fetchone()
    return dict(row) if row else None


def montar_venda_pedido_vitrine(
    pedido: dict[str, Any],
) -> tuple[dict[str, Any], list[dict[str, str]]]:
    pedido_id = int(pedido.get("id") or 0)
    itens_venda: list[dict[str, str]] = []
    total = 0.0

    for item in pedido.get("itens") or []:
        quantidade = _converter_valor_brl(item.get("quantidade"))
        valor_unitario = _converter_valor_brl(item.get("valor_unitario"))
        subtotal = _converter_valor_brl(item.get("subtotal"))
        if subtotal <= 0:
            subtotal = quantidade * valor_unitario
        total += subtotal
        itens_venda.append(
            {
                "tipo_item": "produto",
                "descricao": str(item.get("produto_nome") or "Produto da vitrine").strip(),
                "detalhes": f"Pedido da vitrine #{pedido_id}.",
                "quantidade": str(item.get("quantidade") or "1"),
                "valor_unitario": str(item.get("valor_unitario") or "0,00"),
                "desconto": "0,00",
                "subtotal": _formatar_moeda_brl(subtotal),
            }
        )

    total_formatado = _formatar_moeda_brl(total)
    forma_pagamento = str(pedido.get("forma_pagamento") or "A definir").strip() or "A definir"
    observacoes_internas = [
        f"Venda gerada pelo pedido da vitrine #{pedido_id}.",
        f"WhatsApp do cliente: {pedido.get('cliente_whatsapp') or '-'}.",
        f"Entrega: {pedido.get('tipo_entrega') or '-'}.",
    ]
    if str(pedido.get("endereco") or "").strip():
        observacoes_internas.append(f"Endereço: {str(pedido.get('endereco')).strip()}.")
    if str(pedido.get("observacoes") or "").strip():
        observacoes_internas.append(
            f"Observações do pedido: {str(pedido.get('observacoes')).strip()}"
        )

    venda: dict[str, Any] = {
        "origem_vitrine_pedido_id": pedido_id,
        "numero": "",
        "cliente": str(pedido.get("cliente_nome") or "Cliente da vitrine").strip(),
        "responsavel": str(session.get("usuario_nome") or "Administrador").strip(),
        "data": hoje_empresa().isoformat(),
        "prazo_entrega": "",
        "canal_venda": "Vitrine online",
        "centro_custo": "Vitrine",
        "centro_custo_id": "",
        "atividade_financeira_id": "",
        "tipo": "produto",
        "status": "concretizada",
        "total_produtos": total_formatado,
        "total_servicos": "0,00",
        "desconto_valor": "0,00",
        "desconto_percentual": "0,00",
        "valor_total": total_formatado,
        "forma_pagamento": forma_pagamento,
        "condicao_pagamento": "avista",
        "meio_pagamento": forma_pagamento,
        "valor_entrada": "0,00",
        "meio_pagamento_entrada": "",
        "data_entrada": hoje_empresa().isoformat(),
        "quantidade_parcelas": 1,
        "primeiro_vencimento": hoje_empresa().isoformat(),
        "intervalo_parcelas": "mensal",
        "observacoes": f"Pedido da vitrine #{pedido_id}.",
        "observacoes_internas": "\n".join(observacoes_internas),
    }
    return venda, itens_venda


def gerar_venda_pedido_vitrine_db(
    pedido_id: int,
) -> tuple[int | None, bool, str]:
    pedido = buscar_pedido_vitrine_admin(pedido_id)
    if pedido is None:
        return None, False, "Pedido não encontrado nesta empresa."

    venda_existente_id = int(pedido.get("venda_id") or 0)
    if venda_existente_id > 0:
        return (
            venda_existente_id,
            False,
            f"Este pedido já gerou a venda {pedido.get('venda_numero') or venda_existente_id}.",
        )

    if str(pedido.get("status") or "").strip().lower() != "em_atendimento":
        return None, False, "Inicie o atendimento antes de concluir o pedido."

    venda, itens_venda = montar_venda_pedido_vitrine(pedido)
    erro_validacao = validar_venda_para_salvar(venda, itens_venda)
    if erro_validacao:
        return None, False, erro_validacao

    try:
        validar_estoque_para_venda_db(itens_venda)
    except ValueError as exc:
        return None, False, str(exc)

    if not reservar_operacao_configurada(
        "vitrine",
        "pedido",
        pedido_id,
        "gerar_venda",
    ):
        venda_existente = buscar_venda_por_pedido_vitrine_id(pedido_id)
        if venda_existente is not None:
            return (
                int(venda_existente["id"]),
                False,
                f"Este pedido já gerou a venda {venda_existente.get('numero') or venda_existente['id']}.",
            )
        return None, False, "A conclusão deste pedido já está sendo processada."

    try:
        venda_id = salvar_venda_db(venda, itens_venda)
    except (sqlite3.Error, ValueError, TypeError) as exc:
        liberar_operacao_configurada("vitrine", "pedido", pedido_id, "gerar_venda")
        app.logger.exception("Falha ao gerar venda pelo pedido da vitrine %s.", pedido_id)
        return None, False, f"Não foi possível gerar a venda: {exc}"

    agora = agora_empresa().isoformat(timespec="seconds")
    try:
        with conectar_db() as conn:
            cursor = conn.execute(
                """
                UPDATE vitrine_pedidos
                SET
                    status = 'concluido',
                    venda_id = ?,
                    atendido_por_usuario_id = ?,
                    atendido_por_nome = ?,
                    concluido_em = ?,
                    atualizado_em = ?
                WHERE id = ?
                  AND empresa_id = ?
                  AND venda_id IS NULL
                """,
                (
                    venda_id,
                    usuario_logado_id(),
                    str(session.get("usuario_nome") or "Administrador").strip(),
                    agora,
                    agora,
                    pedido_id,
                    empresa_logada_id(),
                ),
            )
            conn.commit()
        if cursor.rowcount != 1:
            raise sqlite3.IntegrityError("O pedido não pôde ser vinculado à venda gerada.")
    except sqlite3.Error as exc:
        finalizar_operacao_configurada(
            "vitrine",
            "pedido",
            pedido_id,
            "gerar_venda",
            "",
            {"venda_id": venda_id, "erro_vinculo": str(exc)},
        )
        app.logger.exception(
            "Venda %s criada, mas o vínculo com o pedido da vitrine %s falhou.",
            venda_id,
            pedido_id,
        )
        return (
            venda_id,
            True,
            "A venda foi criada, mas o vínculo com o pedido precisa ser verificado.",
        )

    falhas_integracao: list[str] = []
    try:
        baixar_estoque_por_venda_db(venda_id, venda, itens_venda)
    except (sqlite3.Error, ValueError, TypeError) as exc:
        falhas_integracao.append(f"estoque: {exc}")
        app.logger.exception(
            "Falha na baixa de estoque da venda %s gerada pela vitrine.",
            venda_id,
        )

    try:
        gerar_conta_receber_por_venda_db(venda_id, venda)
    except (sqlite3.Error, ValueError, TypeError) as exc:
        falhas_integracao.append(f"financeiro: {exc}")
        app.logger.exception(
            "Falha no financeiro da venda %s gerada pela vitrine.",
            venda_id,
        )

    finalizar_operacao_configurada(
        "vitrine",
        "pedido",
        pedido_id,
        "gerar_venda",
        "",
        {
            "venda_id": venda_id,
            "venda_numero": str(venda.get("numero") or ""),
            "falhas_integracao": falhas_integracao,
        },
    )

    if falhas_integracao:
        return (
            venda_id,
            True,
            (
                f"Venda {venda.get('numero') or venda_id} criada. "
                "Verifique as integrações de estoque e financeiro."
            ),
        )

    return (
        venda_id,
        True,
        f"Pedido concluído e venda {venda.get('numero') or venda_id} gerada com sucesso.",
    )


def buscar_agendamento_vitrine_admin(agendamento_id: int) -> dict[str, Any] | None:
    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT
                a.*,
                v.numero AS venda_numero
            FROM agendamentos a
            LEFT JOIN vendas v
              ON v.id = a.venda_id
             AND v.empresa_id = a.empresa_id
            WHERE a.id = ?
              AND a.empresa_id = ?
              AND a.origem IN ('vitrine_online', 'avaliacao_vitrine')
            LIMIT 1
            """,
            (agendamento_id, empresa_logada_id()),
        ).fetchone()
    return dict(row) if row else None


def buscar_venda_por_agendamento_vitrine_id(
    agendamento_id: int,
) -> dict[str, Any] | None:
    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT id, numero, status
            FROM vendas
            WHERE empresa_id = ?
              AND origem_vitrine_agendamento_id = ?
            LIMIT 1
            """,
            (empresa_logada_id(), agendamento_id),
        ).fetchone()
    return dict(row) if row else None


