        vitrine=config_vitrine,
        produtos_vitrine=listar_produtos_vitrine_empresa(empresa_id),
        produtos_vitrine_admin=produtos_admin,
        servicos_vitrine=listar_servicos_vitrine_empresa(empresa_id),
