@app.post("/ordens-servico/<int:ordem_servico_id>/fotos/upload")
def upload_foto_ordem_servico_edicao(ordem_servico_id: int) -> Response:
    """Salva uma única foto imediatamente, sem reenviar todo o formulário da OS."""
    ordem_servico = buscar_ordem_servico_por_id(ordem_servico_id)

    if ordem_servico is None:
        return jsonify({"ok": False, "erro": "Ordem de serviço não encontrada."}), 404

    arquivo = request.files.get("foto")

    if arquivo is None:
        print(
            "[OS FOTO][UPLOAD VAZIO] "
            f"os={ordem_servico_id} "
            f"content_type={request.content_type!r} "
            f"files={list(request.files.keys())} "
            f"form={list(request.form.keys())}",
            flush=True,
        )
        return jsonify({
            "ok": False,
            "erro": "A imagem não chegou ao servidor. Atualize a página e selecione novamente."
        }), 400

    if not str(arquivo.filename or "").strip():
        extensao_por_mime = {
            "image/jpeg": "jpg",
            "image/png": "png",
            "image/webp": "webp",
            "image/heic": "heic",
            "image/heif": "heif",
        }
        extensao_fallback = extensao_por_mime.get(
            str(arquivo.mimetype or "").strip().lower(),
            "jpg",
        )
        arquivo.filename = f"foto_os_{ordem_servico_id}.{extensao_fallback}"

    tipo = "depois" if str(request.form.get("tipo") or "").strip().lower() == "depois" else "antes"
    equipamento_indice = str(request.form.get("equipamento_indice") or "0").strip() or "0"
    titulo = str(request.form.get("titulo") or "").strip()
    observacoes = str(request.form.get("observacoes") or "").strip()
    foto_id_texto = str(request.form.get("foto_id") or "").strip()
    foto_id = int(foto_id_texto) if foto_id_texto.isdigit() else None
    empresa_id = empresa_logada_id()

    try:
        caminho = salvar_upload_foto_os(
            arquivo,
            ordem_servico_id,
            f"{tipo}_{equipamento_indice}",
        )
    except ValueError as exc:
        return jsonify({"ok": False, "erro": str(exc)}), 400
    except OSError:
        return jsonify({
            "ok": False,
            "erro": "Não foi possível gravar a imagem no armazenamento da OS."
        }), 500

    agora = agora_empresa().isoformat(timespec="seconds")
    foto_antes_path = caminho if tipo == "antes" else ""
    foto_depois_path = caminho if tipo == "depois" else ""

    with conectar_db() as conn:
        if foto_id is not None:
            registro = conn.execute(
                """
                SELECT id
                FROM os_fotos_equipamento
                WHERE id = ?
                  AND ordem_servico_id = ?
                  AND empresa_id = ?
                LIMIT 1
                """,
                (foto_id, ordem_servico_id, empresa_id),
            ).fetchone()

            if registro is None:
                return jsonify({"ok": False, "erro": "Foto não encontrada nesta OS."}), 404

            conn.execute(
                """
                UPDATE os_fotos_equipamento
                SET
                    titulo = ?,
                    equipamento_indice = ?,
                    tipo_foto = ?,
                    foto_antes_path = ?,
                    foto_depois_path = ?,
                    observacoes = ?,
                    atualizado_em = ?
                WHERE id = ?
                  AND ordem_servico_id = ?
                  AND empresa_id = ?
                """,
                (
                    titulo,
                    equipamento_indice,
                    tipo,
                    foto_antes_path,
                    foto_depois_path,
                    observacoes,
                    agora,
                    foto_id,
                    ordem_servico_id,
                    empresa_id,
                ),
            )
            registro_id = foto_id
        else:
            cursor = conn.execute(
                """
                INSERT INTO os_fotos_equipamento (
                    empresa_id,
                    ordem_servico_id,
                    titulo,
                    equipamento_indice,
                    tipo_foto,
                    foto_antes_path,
                    foto_depois_path,
                    observacoes,
                    atualizado_em
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    empresa_id,
                    ordem_servico_id,
                    titulo,
                    equipamento_indice,
                    tipo,
                    foto_antes_path,
                    foto_depois_path,
                    observacoes,
                    agora,
                ),
            )
            registro_id = int(cursor.lastrowid)

        conn.commit()

    return jsonify({
        "ok": True,
        "foto": {
            "id": registro_id,
            "tipo": tipo,
            "caminho": caminho,
            "equipamento_indice": equipamento_indice,
            "titulo": titulo,
            "observacoes": observacoes,
        },
    })


@app.post("/ordens-servico/<int:ordem_servico_id>/fotos/<int:foto_id>/excluir")
def excluir_foto_ordem_servico_edicao(ordem_servico_id: int, foto_id: int) -> Response:
    """Exclui uma foto enviada imediatamente pela tela de edição."""
    ordem_servico = buscar_ordem_servico_por_id(ordem_servico_id)

    if ordem_servico is None:
        return jsonify({"ok": False, "erro": "Ordem de serviço não encontrada."}), 404

    empresa_id = empresa_logada_id()

    with conectar_db() as conn:
        registro = conn.execute(
            """
            SELECT id
            FROM os_fotos_equipamento
            WHERE id = ?
              AND ordem_servico_id = ?
              AND empresa_id = ?
            LIMIT 1
            """,
            (foto_id, ordem_servico_id, empresa_id),
        ).fetchone()

        if registro is None:
            return jsonify({"ok": False, "erro": "Foto não encontrada nesta OS."}), 404

        conn.execute(
            """
            DELETE FROM os_fotos_equipamento
            WHERE id = ?
              AND ordem_servico_id = ?
              AND empresa_id = ?
            """,
            (foto_id, ordem_servico_id, empresa_id),
        )
        conn.commit()

    return jsonify({"ok": True})


@app.post("/ordens-servico/<int:ordem_servico_id>/editar")
def atualizar_ordem_servico(ordem_servico_id: int) -> Response:
    ordem_servico_atual = buscar_ordem_servico_por_id(ordem_servico_id)

    if ordem_servico_atual is None:
        return redirect(url_for("ordens_servico"))

    ordem_servico = montar_ordem_servico_formulario(numero_padrao=str(ordem_servico_atual["numero"] or ""))
    ordem_servico["numero"] = str(ordem_servico_atual["numero"] or "")

    # Na edição, alguns navegadores móveis podem não enviar o valor do <select>
    # mesmo quando o cliente aparece selecionado. Como cliente é obrigatório,
    # preservamos o cliente atual quando o POST chegar vazio.
    if not str(ordem_servico.get("cliente") or "").strip():
        cliente_atual = str(
            request.form.get("os_cliente_original")
            or ordem_servico_atual.get("cliente")
            or ""
        ).strip()
        ordem_servico["cliente"] = cliente_atual

    itens = montar_ordem_servico_itens_formulario()
    erro_validacao = validar_ordem_servico_para_salvar(ordem_servico, itens)

    if erro_validacao:
        return redirect(url_for("editar_ordem_servico", ordem_servico_id=ordem_servico_id, erro=erro_validacao))

    atualizar_ordem_servico_db(ordem_servico_id, ordem_servico, itens)
    try:
        atualizar_fotos_equipamento_os_formulario(ordem_servico_id)
    except ValueError as exc:
        return redirect(url_for("editar_ordem_servico", ordem_servico_id=ordem_servico_id, erro=str(exc)))

    integracoes = executar_integracoes_ordem_servico_configuradas(ordem_servico_id)

    return redirect(
        url_for(
            "ordens_servico",
            sucesso=f"OS {ordem_servico.get('numero')} atualizada com sucesso." + (" Gerado: " + ", ".join(integracoes) + "." if integracoes else ""),
        )
    )


@app.post("/ordens-servico/<int:ordem_servico_id>/excluir")
def excluir_ordem_servico(ordem_servico_id: int) -> Response:
    ordem_servico = buscar_ordem_servico_por_id(ordem_servico_id)

    if ordem_servico is not None:
        excluir_ordem_servico_db(ordem_servico_id)

    return redirect(url_for("ordens_servico"))




def buscar_caixa_aberto_db() -> dict[str, Any] | None:
    empresa_id = empresa_logada_id()

    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT
                id,
                empresa_id,
                usuario_id,
                responsavel,
                valor_abertura,
                valor_fechamento,
                status,
                aberto_em,
                fechado_em,
                observacoes,
                criado_em
            FROM caixa_aberturas
            WHERE empresa_id = ?
              AND status = 'aberto'
            ORDER BY id DESC
            LIMIT 1
            """,
            (empresa_id,),
        ).fetchone()

    if row is None:
        return None

    return dict(row)


def abrir_caixa_db(valor_abertura: str, responsavel: str, gerar_recebimento: bool = False) -> int:
    empresa_id = empresa_logada_id()
    usuario_id = usuario_logado_id()
    valor_abertura_formatado = _formatar_moeda_brl(_converter_valor_brl(valor_abertura))
    aberto_em = agora_empresa().isoformat(timespec="seconds")

    with conectar_db() as conn:
        cursor = conn.execute(
            """
            INSERT INTO caixa_aberturas (
                empresa_id,
                usuario_id,
                responsavel,
                valor_abertura,
                valor_fechamento,
                status,
                aberto_em,
                fechado_em,
                observacoes
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                usuario_id,
                responsavel,
                valor_abertura_formatado,
                "",
                "aberto",
                aberto_em,
                "",
                "Abertura de caixa do PDV.",
            ),
        )
        caixa_id = int(cursor.lastrowid)

        conn.execute(
            """
            INSERT INTO caixa_movimentacoes (
                empresa_id,
                caixa_id,
                venda_id,
                tipo,
                descricao,
                forma_pagamento,
                valor
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                caixa_id,
                None,
                "abertura",
                "Abertura de caixa",
                "Dinheiro",
                valor_abertura_formatado,
            ),
        )

        conn.commit()

    if gerar_recebimento and _converter_valor_brl(valor_abertura_formatado) > 0:
        salvar_financeiro_titulo_db(
            {
                "tipo": "receber",
                "descricao": "Abertura de caixa PDV",
                "pessoa": responsavel or "Balcão",
                "categoria": "Caixa",
                "origem": "caixa",
                "origem_id": str(caixa_id),
                "documento": f"Caixa Nº {caixa_id}",
                "data_emissao": hoje_empresa().isoformat(),
                "data_vencimento": hoje_empresa().isoformat(),
                "data_pagamento": hoje_empresa().isoformat(),
                "valor": valor_abertura_formatado,
                "forma_pagamento": "Dinheiro",
                "status": "pago",
                "observacoes": "Recebimento opcional gerado pela abertura de caixa.",
            }
        )

    return caixa_id


