@app.get("/orcamentos/exportar.csv")
def exportar_orcamentos_csv() -> Response:
    if not usuario_tem_permissao("orcamentos", "exportar"):
        return Response("Acesso negado à exportação de orçamentos.", status=403)

    filtros = montar_filtros_orcamentos_avancados()
    ordenar = str(request.args.get("ordenar") or "id").strip()
    if ordenar not in ORCAMENTOS_ORDENACAO:
        ordenar = "id"
    direcao = str(request.args.get("direcao") or "desc").strip().lower()
    if direcao not in {"asc", "desc"}:
        direcao = "desc"

    colunas_solicitadas = [
        item.strip() for item in str(request.args.get("colunas") or "").split(",") if item.strip()
    ]
    colunas = [item for item in colunas_solicitadas if item in ORCAMENTOS_COLUNAS_EXPORTACAO]
    if not colunas:
        colunas = list(ORCAMENTOS_COLUNAS_PADRAO)

    registros, _ = listar_orcamentos_filtrados(filtros, ordenar, direcao)
    saida = io.StringIO(newline="")
    saida.write("\ufeff")
    escritor = csv.writer(saida, delimiter=";")
    escritor.writerow([ORCAMENTOS_COLUNAS_EXPORTACAO[coluna][0] for coluna in colunas])
    for registro in registros:
        escritor.writerow([
            str(registro.get(ORCAMENTOS_COLUNAS_EXPORTACAO[coluna][1]) or "")
            for coluna in colunas
        ])

    nome = f"orcamentos_{hoje_empresa().isoformat()}.csv"
    registrar_atividade_usuario(
        "exportacao", "orcamentos", f"Exportou {len(registros)} orçamento(s) em CSV", request.path
    )
    return Response(
        saida.getvalue(),
        mimetype="text/csv; charset=utf-8",
        headers={"Content-Disposition": f'attachment; filename="{nome}"'},
    )


@app.post("/orcamentos")
def salvar_orcamento() -> Response:
    orcamento = montar_orcamento_formulario(numero_padrao=proximo_numero_orcamento())
    orcamento["origem"] = "manual"
    itens = montar_orcamento_itens_formulario()
    erro_validacao = validar_orcamento_para_salvar(orcamento, itens)
    if erro_validacao:
        return redirect(url_for("orcamentos", erro=erro_validacao))

    resultado_salvamento = salvar_orcamento_db(
        orcamento,
        itens,
        impedir_numero_duplicado=True,
        retornar_criacao=True,
    )
    orcamento_id, orcamento_criado = resultado_salvamento

    if not orcamento_criado:
        return redirect(
            url_for(
                "orcamentos",
                aviso="Este orçamento já havia sido salvo. Nenhuma duplicidade foi criada.",
            )
        )

    sincronizar_apresentacao_orcamento_db(
        orcamento_id,
        orcamento,
        itens,
        itens_informados=montar_orcamento_apresentacao_formulario(),
    )
    registrar_atividade_usuario(
        "criacao",
        "orcamentos",
        f"Criou orçamento {orcamento.get('numero') or orcamento_id}",
        request.path,
    )
    return redirect(
        url_for(
            "orcamentos",
            sucesso=f"Orçamento {orcamento.get('numero')} criado com sucesso.",
        )
    )



@app.get("/orcamentos/<int:orcamento_id>")
def ver_orcamento(orcamento_id: int) -> str | Response:
    acao_gerar = str(request.args.get("gerar") or "").strip().lower()

    if acao_gerar == "venda":
        return redirect(url_for("gerar_venda_por_orcamento", orcamento_id=orcamento_id))

    if acao_gerar == "os":
        return redirect(url_for("gerar_ordem_servico_por_orcamento", orcamento_id=orcamento_id))

    orcamento = buscar_orcamento_por_id(orcamento_id)
    if orcamento is None:
        return redirect(url_for("orcamentos"))

    orcamento = formatar_datas_documento_exibicao(orcamento, ("data", "validade"))
    itens = listar_orcamento_itens(orcamento_id)
    itens_apresentacao = listar_orcamento_apresentacao_itens(orcamento_id)
    dados_gerador = buscar_orcamento_gerador_dados(orcamento_id)
    if normalizar_modo_apresentacao(orcamento.get("modo_apresentacao"), "agrupado") != "detalhado" and not itens_apresentacao:
        itens_apresentacao = montar_apresentacao_padrao_orcamento(orcamento, itens)

    return render_template(
        "orcamento_detalhe.html",
        orcamento=orcamento,
        itens=itens,
        itens_apresentacao=itens_apresentacao,
        dados_gerador=dados_gerador,
        historico_gerador=listar_historico_gerador(orcamento_id)[:3],
        venda_gerada=buscar_venda_por_orcamento_id(orcamento_id),
        escopo_formatado=formatar_escopo_orcamento(orcamento.get("observacoes"), dados_gerador),
        atividade=buscar_atividade_financeira_por_id(orcamento.get("atividade_financeira_id")) if orcamento.get("atividade_financeira_id") else None,
        resumo_atividade=resumir_atividade_financeira(orcamento.get("atividade_financeira_id")),
        atividades_operacionais=[a for a in _listar_atividades_operacionais() if int(a.get("orcamento_id") or 0) == orcamento_id],
    )




@app.get("/orcamentos/<int:orcamento_id>/gerar/venda")
def gerar_venda_por_orcamento(orcamento_id: int) -> Response:
    venda_id, venda_criada = gerar_venda_por_orcamento_db(orcamento_id)

    if venda_id is None:
        return redirect(
            url_for(
                "ver_orcamento",
                orcamento_id=orcamento_id,
                erro="Não foi possível gerar a venda. Confira os itens e o valor do orçamento.",
            )
        )

    if venda_criada:
        venda = buscar_venda_por_id(venda_id)
        itens_venda = listar_venda_itens(venda_id)

        if venda is not None:
            baixar_estoque_por_venda_db(venda_id, venda, itens_venda)
            gerar_conta_receber_por_venda_db(venda_id, venda)

        registrar_atividade_usuario(
            "criacao",
            "orcamentos",
            f"Gerou venda #{venda_id} pelo orçamento #{orcamento_id}",
            request.path,
        )

    venda = buscar_venda_por_id(venda_id)
    mensagem = (
        "Venda já gerada anteriormente para este orçamento."
        if not venda_criada
        else (
            f"Venda {venda.get('numero')} gerada pelo orçamento."
            if venda is not None
            else "Venda gerada pelo orçamento."
        )
    )
    parametro = "aviso" if not venda_criada else "sucesso"
    return redirect(url_for("vendas", **{parametro: mensagem}))


