@app.route("/ponto/<token>", methods=["GET", "POST"])
def ponto_publico(token: str) -> str | Response:
    funcionario = buscar_funcionario_por_token_ponto(token)
    erro = ""
    sucesso = ""
    telefone_validado = session.get(f"ponto_validado_{token}") == "sim"
    registro_hoje = None
    registro_exibicao = None
    bloqueio_nova_entrada_segundos = 0

    if funcionario is None:
        erro = "Link de ponto inválido ou funcionário inativo."
    else:
        empresa_ponto_id = int(funcionario.get("empresa_id") or 0)
        validar_celular = configuracao_bool("registro_ponto", "validacao_celular", True, empresa_ponto_id)
        if not validar_celular:
            telefone_validado = True
        else:
            validado_em = str(session.get(f"ponto_validado_em_{token}") or "")
            dias_confianca = int(float(valor_configuracao_modulo("registro_ponto", "confianca_aparelho_dias", 30, empresa_ponto_id) or 30))
            if validado_em:
                try:
                    telefone_validado = agora_empresa() - datetime.fromisoformat(validado_em) <= timedelta(days=dias_confianca)
                except ValueError:
                    telefone_validado = False
        registro_hoje = buscar_registro_ponto_publico(
            int(funcionario["empresa_id"]),
            int(funcionario["id"]),
            hoje_empresa().isoformat(),
        )

        if request.method == "POST":
            etapa = str(request.form.get("etapa") or "").strip()

            if etapa == "validar_celular":
                telefone_digitado = normalizar_telefone_validacao_ponto(request.form.get("telefone"))
                telefone_cadastrado = normalizar_telefone_validacao_ponto(funcionario.get("telefone"))

                if telefone_cadastrado and telefone_digitado == telefone_cadastrado:
                    session.permanent = True
                    session[f"ponto_validado_{token}"] = "sim"
                    session[f"ponto_validado_em_{token}"] = agora_empresa().isoformat(timespec="seconds")
                    return redirect(url_for("ponto_publico", token=token, sucesso="Celular validado com sucesso."))

                erro = "WhatsApp informado não confere com o cadastro do funcionário."
            else:
                if not telefone_validado:
                    erro = "Valide seu WhatsApp antes de bater o ponto."
                else:
                    acao = str(request.form.get("acao") or "").strip()
                    ok, mensagem, registro_hoje = registrar_batida_ponto_publico(
                        funcionario,
                        acao,
                        latitude=request.form.get("latitude") or "",
                        longitude=request.form.get("longitude") or "",
                        precisao=request.form.get("precisao") or "",
                        dispositivo_info=request.headers.get("User-Agent") or "",
                    )
                    parametro = "sucesso" if ok else "erro"
                    return redirect(url_for("ponto_publico", token=token, **{parametro: mensagem}))

    erro = erro or str(request.args.get("erro") or "")
    sucesso = sucesso or str(request.args.get("sucesso") or "")

    registro_exibicao = registro_hoje
    bloqueio_nova_entrada_segundos = bloqueio_nova_jornada_ponto_segundos(registro_hoje)

    if (
        registro_hoje
        and str(registro_hoje.get("saida") or "").strip()
        and bloqueio_nova_entrada_segundos <= 0
    ):
        registro_exibicao = None

    return render_template(
        "ponto_funcionario.html",
        token=token,
        funcionario=funcionario,
        registro_hoje=registro_exibicao,
        telefone_validado=telefone_validado,
        telefone_mascarado=mascarar_telefone_ponto(funcionario.get("telefone") if funcionario else ""),
        data_hoje=formatar_data_br(hoje_empresa()),
        exigir_intervalo_ponto=ponto_exige_intervalo(funcionario),
        proxima_acao_ponto=proxima_acao_ponto(registro_exibicao, funcionario),
        bloqueio_nova_entrada_segundos=bloqueio_nova_entrada_segundos,
        erro=erro,
        sucesso=sucesso,
        gestflow_configuracoes_runtime=(
            montar_configuracoes_runtime(int(funcionario.get("empresa_id") or 0))
            if funcionario else {}
        ),
    )


@app.post("/api/ponto/offline/sincronizar")
def api_ponto_offline_sincronizar() -> Response:
    dados = request.get_json(silent=True) or {}
    token = str(dados.get("token") or "").strip()
    batidas = dados.get("batidas") or []
    funcionario = buscar_funcionario_por_token_ponto(token)

    if funcionario is None:
        return jsonify({"ok": False, "erro": "Link de ponto inválido ou funcionário inativo."}), 404

    if not configuracao_bool("registro_ponto", "permitir_offline", True, int(funcionario.get("empresa_id") or 0)):
        return jsonify({"ok": False, "erro": "O ponto offline está desativado pela empresa."}), 403

    if not isinstance(batidas, list):
        return jsonify({"ok": False, "erro": "Lista de batidas inválida."}), 400

    resultados = []
    sincronizadas = 0

    for batida in batidas:
        if not isinstance(batida, dict):
            continue

        ok, mensagem, registro = registrar_batida_ponto_publico(
            funcionario,
            str(batida.get("acao") or ""),
            batida.get("data_ponto") or "",
            batida.get("hora_ponto") or "",
            origem="offline",
            offline_uuid=batida.get("uuid") or "",
            dispositivo_info=batida.get("dispositivo") or request.headers.get("User-Agent") or "",
            latitude=batida.get("latitude") or "",
            longitude=batida.get("longitude") or "",
            precisao=batida.get("precisao") or "",
        )

        if ok:
            sincronizadas += 1

        resultados.append(
            {
                "uuid": str(batida.get("uuid") or ""),
                "ok": ok,
                "mensagem": mensagem,
                "registro": registro or {},
            }
        )

    return jsonify({"ok": True, "sincronizadas": sincronizadas, "resultados": resultados})


@app.route("/registro-ponto", methods=["GET", "POST"])
def registro_ponto() -> str | Response:
    garantir_tokens_ponto_funcionarios_empresa()

    if request.method == "POST":
        funcionario_id_texto = str(request.form.get("funcionario_id") or "").strip()
        acao = str(request.form.get("acao") or "").strip()

        if not funcionario_id_texto.isdigit():
            return redirect(
                url_for(
                    "registro_ponto",
                    erro="Selecione o funcionário para bater ponto.",
                )
            )

        ok, mensagem = bater_ponto_db(int(funcionario_id_texto), acao)
        parametro = "sucesso" if ok else "erro"
        return redirect(
            url_for(
                "registro_ponto",
                funcionario_id=funcionario_id_texto,
                **{parametro: mensagem},
            )
        )

    funcionario_id = str(request.args.get("funcionario_id") or "").strip()
    data_inicio = _normalizar_data_iso(
        request.args.get("data_inicio") or hoje_empresa().isoformat()
    )
    data_fim = _normalizar_data_iso(
        request.args.get("data_fim") or data_inicio,
        data_inicio,
    )
    funcionarios_lista = listar_funcionarios()

    for funcionario in funcionarios_lista:
        funcionario["token_ponto_publico"] = str(
            funcionario.get("token_ponto") or ""
        ).strip()
        funcionario["exigir_intervalo_bool"] = ponto_exige_intervalo(funcionario)

    ids_validos = {
        str(funcionario.get("id") or "")
        for funcionario in funcionarios_lista
    }

    if funcionario_id not in ids_validos:
        funcionario_id = ""

    funcionario_selecionado = next(
        (
            funcionario
            for funcionario in funcionarios_lista
            if str(funcionario.get("id") or "") == funcionario_id
        ),
        None,
    )

    exigir_intervalo = (
        ponto_exige_intervalo(funcionario_selecionado)
        if funcionario_selecionado
        else True
    )
    registro_hoje = None
    proxima_acao = ""

    if funcionario_selecionado is not None:
        registro_hoje = buscar_registro_ponto(
            int(funcionario_selecionado["id"]),
            hoje_empresa().isoformat(),
        )
        proxima_acao = proxima_acao_ponto(
            registro_hoje,
            funcionario_selecionado,
        )

    return render_template(
        "registro_ponto.html",
        funcionarios=funcionarios_lista,
        funcionario_selecionado=funcionario_selecionado,
        tem_funcionario=funcionario_selecionado is not None,
        funcionario_id=funcionario_id,
        exigir_intervalo_ponto=exigir_intervalo,
        proxima_acao_ponto=proxima_acao,
        bloqueio_nova_entrada_segundos=bloqueio_nova_jornada_ponto_segundos(registro_hoje),
        proxima_marcacao=(
            rotulo_proxima_acao_ponto(proxima_acao)
            if funcionario_selecionado
            else "Selecione o funcionário para liberar os botões de ponto."
        ),
        data_inicio=data_inicio,
        data_fim=data_fim,
        registros=listar_registros_ponto(
            data_inicio,
            data_fim,
            funcionario_id,
        ),
        registro_hoje=registro_hoje,
        acoes_ponto=PONTO_ACOES,
        erro=request.args.get("erro") or "",
        sucesso=request.args.get("sucesso") or "",
    )


