def garantir_estrutura_emprestimos() -> None:
    """Cria e migra a estrutura do módulo Empréstimos sem apagar dados."""
    with conectar_db() as conn:
        conn.executescript(
            """
            CREATE TABLE IF NOT EXISTS emprestimos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                numero TEXT NOT NULL,
                tipo TEXT NOT NULL DEFAULT 'recebido',
                modalidade TEXT NOT NULL DEFAULT 'parcelado',
                status TEXT NOT NULL DEFAULT 'rascunho',
                titulo TEXT NOT NULL,
                parte_tipo TEXT NOT NULL DEFAULT 'outro',
                parte_id INTEGER,
                parte_nome TEXT NOT NULL,
                parte_documento TEXT,
                parte_email TEXT,
                parte_telefone TEXT,
                banco TEXT,
                conta_financeira TEXT,
                centro_custo_id INTEGER,
                centro_custo TEXT,
                data_contrato TEXT NOT NULL,
                data_liberacao TEXT,
                primeira_parcela TEXT NOT NULL,
                quantidade_parcelas INTEGER NOT NULL DEFAULT 1,
                intervalo_dias INTEGER NOT NULL DEFAULT 30,
                sistema_amortizacao TEXT NOT NULL DEFAULT 'simples',
                valor_principal TEXT NOT NULL DEFAULT '0,00',
                principal_atual TEXT NOT NULL DEFAULT '0,00',
                total_juros_recebidos TEXT NOT NULL DEFAULT '0,00',
                total_amortizado TEXT NOT NULL DEFAULT '0,00',
                permitir_amortizacao INTEGER NOT NULL DEFAULT 1,
                taxa_juros_percentual TEXT NOT NULL DEFAULT '0,00',
                tipo_juros TEXT NOT NULL DEFAULT 'simples',
                multa_percentual TEXT NOT NULL DEFAULT '0,00',
                juros_atraso_mes_percentual TEXT NOT NULL DEFAULT '0,00',
                tarifas TEXT NOT NULL DEFAULT '0,00',
                iof TEXT NOT NULL DEFAULT '0,00',
                valor_total TEXT NOT NULL DEFAULT '0,00',
                saldo_atual TEXT NOT NULL DEFAULT '0,00',
                forma_pagamento TEXT,
                garantia TEXT,
                fiador TEXT,
                observacoes TEXT,
                gerar_financeiro INTEGER NOT NULL DEFAULT 1,
                contrato_origem_id INTEGER,
                criado_por_usuario_id INTEGER,
                criado_por_nome TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP,
                atualizado_em TEXT,
                cancelado_em TEXT,
                quitado_em TEXT
            );

            CREATE TABLE IF NOT EXISTS emprestimo_parcelas (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                emprestimo_id INTEGER NOT NULL,
                numero_parcela INTEGER NOT NULL,
                vencimento TEXT NOT NULL,
                valor_principal TEXT NOT NULL DEFAULT '0,00',
                valor_juros TEXT NOT NULL DEFAULT '0,00',
                valor_tarifas TEXT NOT NULL DEFAULT '0,00',
                tipo_periodo TEXT NOT NULL DEFAULT 'parcelado',
                principal_base TEXT NOT NULL DEFAULT '0,00',
                juros_pago TEXT NOT NULL DEFAULT '0,00',
                amortizacao_principal TEXT NOT NULL DEFAULT '0,00',
                valor_previsto TEXT NOT NULL DEFAULT '0,00',
                valor_pago TEXT NOT NULL DEFAULT '0,00',
                multa_aplicada TEXT NOT NULL DEFAULT '0,00',
                juros_atraso_aplicado TEXT NOT NULL DEFAULT '0,00',
                desconto_aplicado TEXT NOT NULL DEFAULT '0,00',
                saldo_parcela TEXT NOT NULL DEFAULT '0,00',
                status TEXT NOT NULL DEFAULT 'aberta',
                data_pagamento TEXT,
                forma_pagamento TEXT,
                conta_financeira TEXT,
                comprovante TEXT,
                observacoes TEXT,
                lancamento_financeiro_id INTEGER,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP,
                atualizado_em TEXT
            );

            CREATE TABLE IF NOT EXISTS emprestimo_renegociacoes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                emprestimo_id INTEGER NOT NULL,
                motivo TEXT NOT NULL,
                data_renegociacao TEXT NOT NULL,
                saldo_anterior TEXT NOT NULL DEFAULT '0,00',
                novo_valor_total TEXT NOT NULL DEFAULT '0,00',
                nova_taxa_juros_percentual TEXT NOT NULL DEFAULT '0,00',
                nova_quantidade_parcelas INTEGER NOT NULL DEFAULT 1,
                novo_primeiro_vencimento TEXT NOT NULL,
                observacoes TEXT,
                usuario_id INTEGER,
                usuario_nome TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS emprestimo_historico (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                emprestimo_id INTEGER NOT NULL,
                parcela_id INTEGER,
                renegociacao_id INTEGER,
                tipo_evento TEXT NOT NULL,
                descricao TEXT NOT NULL,
                dados_anteriores TEXT,
                dados_novos TEXT,
                usuario_id INTEGER,
                usuario_nome TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS emprestimo_anexos (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                empresa_id INTEGER NOT NULL,
                emprestimo_id INTEGER NOT NULL,
                nome_original TEXT NOT NULL,
                nome_arquivo TEXT NOT NULL,
                caminho TEXT NOT NULL,
                tipo_mime TEXT,
                tamanho_bytes INTEGER NOT NULL DEFAULT 0,
                criado_por_usuario_id INTEGER,
                criado_por_nome TEXT,
                criado_em TEXT DEFAULT CURRENT_TIMESTAMP
            );

            CREATE TABLE IF NOT EXISTS emprestimo_sequencias (
                empresa_id INTEGER NOT NULL,
                ano INTEGER NOT NULL,
                ultimo_numero INTEGER NOT NULL DEFAULT 0,
                atualizado_em TEXT,
                PRIMARY KEY (empresa_id, ano)
            );

            CREATE UNIQUE INDEX IF NOT EXISTS idx_emprestimos_empresa_numero
                ON emprestimos(empresa_id, numero);
            CREATE INDEX IF NOT EXISTS idx_emprestimos_empresa_status
                ON emprestimos(empresa_id, status, id);
            CREATE INDEX IF NOT EXISTS idx_emprestimos_empresa_tipo
                ON emprestimos(empresa_id, tipo, id);
            CREATE INDEX IF NOT EXISTS idx_emprestimos_empresa_parte
                ON emprestimos(empresa_id, parte_tipo, parte_id, id);
            CREATE UNIQUE INDEX IF NOT EXISTS idx_emprestimo_parcela_numero
                ON emprestimo_parcelas(empresa_id, emprestimo_id, numero_parcela);
            CREATE INDEX IF NOT EXISTS idx_emprestimo_parcelas_vencimento
                ON emprestimo_parcelas(empresa_id, status, vencimento);
            CREATE UNIQUE INDEX IF NOT EXISTS idx_emprestimo_parcela_financeiro
                ON emprestimo_parcelas(empresa_id, lancamento_financeiro_id)
                WHERE lancamento_financeiro_id IS NOT NULL;
            CREATE INDEX IF NOT EXISTS idx_emprestimo_renegociacoes_emprestimo
                ON emprestimo_renegociacoes(empresa_id, emprestimo_id, id);
            CREATE INDEX IF NOT EXISTS idx_emprestimo_historico_emprestimo
                ON emprestimo_historico(empresa_id, emprestimo_id, id);
            CREATE INDEX IF NOT EXISTS idx_emprestimo_anexos_emprestimo
                ON emprestimo_anexos(empresa_id, emprestimo_id, id);
            """
        )

        colunas_emprestimos = {
            str(row["name"])
            for row in conn.execute("PRAGMA table_info(emprestimos)").fetchall()
        }
        migracoes_emprestimos = {
            "modalidade": "TEXT NOT NULL DEFAULT 'parcelado'",
            "principal_atual": "TEXT NOT NULL DEFAULT '0,00'",
            "total_juros_recebidos": "TEXT NOT NULL DEFAULT '0,00'",
            "total_amortizado": "TEXT NOT NULL DEFAULT '0,00'",
            "permitir_amortizacao": "INTEGER NOT NULL DEFAULT 1",
        }
        for coluna, definicao in migracoes_emprestimos.items():
            if coluna not in colunas_emprestimos:
                conn.execute(f"ALTER TABLE emprestimos ADD COLUMN {coluna} {definicao}")

        colunas_parcelas = {
            str(row["name"])
            for row in conn.execute("PRAGMA table_info(emprestimo_parcelas)").fetchall()
        }
        migracoes_parcelas = {
            "tipo_periodo": "TEXT NOT NULL DEFAULT 'parcelado'",
            "principal_base": "TEXT NOT NULL DEFAULT '0,00'",
            "juros_pago": "TEXT NOT NULL DEFAULT '0,00'",
            "amortizacao_principal": "TEXT NOT NULL DEFAULT '0,00'",
        }
        for coluna, definicao in migracoes_parcelas.items():
            if coluna not in colunas_parcelas:
                conn.execute(f"ALTER TABLE emprestimo_parcelas ADD COLUMN {coluna} {definicao}")

        conn.execute(
            """
            UPDATE emprestimos
            SET principal_atual=valor_principal
            WHERE modalidade='rotativo'
              AND (principal_atual IS NULL OR principal_atual='' OR principal_atual='0,00')
            """
        )
        conn.commit()


def _emprestimo_decimal(valor: Any) -> Decimal:
    return _decimal_moeda(valor)


def _emprestimo_moeda(valor: Decimal | Any) -> str:
    numero = valor if isinstance(valor, Decimal) else _emprestimo_decimal(valor)
    return _formatar_decimal_brl(numero)


def _emprestimo_data_iso(valor: Any, padrao: str = "") -> str:
    texto = str(valor or "").strip()
    if not texto:
        return padrao
    try:
        return date.fromisoformat(texto).isoformat()
    except ValueError:
        return padrao


def _emprestimo_inteiro_positivo(valor: Any, padrao: int = 1) -> int:
    try:
        numero = int(str(valor or "").strip())
    except (TypeError, ValueError):
        return padrao
    return numero if numero > 0 else padrao


def _emprestimo_adicionar_meses(data_base: date, meses: int) -> date:
    mes_indice = data_base.month - 1 + meses
    ano = data_base.year + mes_indice // 12
    mes = mes_indice % 12 + 1
    dias_mes = [
        31,
        29 if ano % 4 == 0 and (ano % 100 != 0 or ano % 400 == 0) else 28,
        31, 30, 31, 30, 31, 31, 30, 31, 30, 31,
    ]
    return date(ano, mes, min(data_base.day, dias_mes[mes - 1]))


def gerar_numero_emprestimo_db(conn: sqlite3.Connection | None = None) -> str:
    empresa_id = empresa_logada_id()
    agora = agora_empresa()
    ano = agora.year
    prefixo = str(valor_configuracao_modulo("emprestimos", "prefixo_numero", "EMP") or "EMP").strip().upper()
    conexao_propria = conn is None
    banco = conn or conectar_db()
    try:
        row = banco.execute(
            "SELECT ultimo_numero FROM emprestimo_sequencias WHERE empresa_id=? AND ano=?",
            (empresa_id, ano),
        ).fetchone()
        proximo = int(row["ultimo_numero"] if row else 0) + 1
        banco.execute(
            """
            INSERT INTO emprestimo_sequencias (empresa_id, ano, ultimo_numero, atualizado_em)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(empresa_id, ano)
            DO UPDATE SET ultimo_numero=excluded.ultimo_numero, atualizado_em=excluded.atualizado_em
            """,
            (empresa_id, ano, proximo, agora.isoformat(timespec="seconds")),
        )
        if conexao_propria:
            banco.commit()
        return f"{prefixo}-{ano}-{proximo:05d}"
    finally:
        if conexao_propria:
            banco.close()


def calcular_plano_emprestimo(
    valor_principal: Decimal,
    taxa_juros_percentual: Decimal,
    quantidade_parcelas: int,
    sistema_amortizacao: str,
    primeira_parcela: date,
    intervalo_dias: int,
    tarifas: Decimal = Decimal("0.00"),
    iof: Decimal = Decimal("0.00"),
) -> list[dict[str, Any]]:
    quantidade = max(1, quantidade_parcelas)
    sistema = sistema_amortizacao if sistema_amortizacao in EMPRESTIMO_SISTEMAS_AMORTIZACAO_CODIGOS else "simples"
    principal = valor_principal.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    taxa = (taxa_juros_percentual / Decimal("100")).quantize(Decimal("0.00000001"))
    adicionais = (tarifas + iof).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    parcelas: list[dict[str, Any]] = []

    if sistema == "price" and taxa > 0:
        fator = (Decimal("1") + taxa) ** quantidade
        valor_parcela = (principal * taxa * fator / (fator - Decimal("1"))).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        saldo = principal
        for indice in range(1, quantidade + 1):
            juros = (saldo * taxa).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            amortizacao = (valor_parcela - juros).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            if indice == quantidade:
                amortizacao = saldo
                valor_parcela = amortizacao + juros
            saldo = max(Decimal("0.00"), saldo - amortizacao)
            parcelas.append({"principal": amortizacao, "juros": juros, "total": valor_parcela})
    elif sistema == "sac":
        amortizacao_padrao = (principal / quantidade).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        saldo = principal
        for indice in range(1, quantidade + 1):
            amortizacao = amortizacao_padrao if indice < quantidade else saldo
            juros = (saldo * taxa).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
            total = amortizacao + juros
            saldo = max(Decimal("0.00"), saldo - amortizacao)
            parcelas.append({"principal": amortizacao, "juros": juros, "total": total})
    else:
        juros_total = (principal * taxa * quantidade).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        total_geral = principal + juros_total
        parcela_padrao = (total_geral / quantidade).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        principal_padrao = (principal / quantidade).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        juros_padrao = (juros_total / quantidade).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        total_acumulado = Decimal("0.00")
        principal_acumulado = Decimal("0.00")
        juros_acumulado = Decimal("0.00")
        for indice in range(1, quantidade + 1):
            if indice == quantidade:
                total = total_geral - total_acumulado
                principal_item = principal - principal_acumulado
                juros_item = juros_total - juros_acumulado
            else:
                total = parcela_padrao
                principal_item = principal_padrao
                juros_item = juros_padrao
            total_acumulado += total
            principal_acumulado += principal_item
            juros_acumulado += juros_item
            parcelas.append({"principal": principal_item, "juros": juros_item, "total": total})

    adicional_parcela = (adicionais / quantidade).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    adicional_acumulado = Decimal("0.00")
    for indice, parcela in enumerate(parcelas, start=1):
        adicional_item = adicional_parcela if indice < quantidade else adicionais - adicional_acumulado
        adicional_acumulado += adicional_item
        parcela["tarifas"] = adicional_item
        parcela["total"] = (parcela["total"] + adicional_item).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        if intervalo_dias == 30:
            vencimento = _emprestimo_adicionar_meses(primeira_parcela, indice - 1)
        else:
            vencimento = primeira_parcela + timedelta(days=intervalo_dias * (indice - 1))
        parcela["numero"] = indice
        parcela["vencimento"] = vencimento.isoformat()

    return parcelas



def _calcular_juros_periodo_rotativo(principal: Decimal, taxa_percentual: Decimal) -> Decimal:
    return (
        principal * (taxa_percentual / Decimal("100"))
    ).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _proximo_vencimento_rotativo(vencimento_atual: str, intervalo_dias: int) -> str:
    data_atual = date.fromisoformat(vencimento_atual)
    if intervalo_dias == 30:
        return _emprestimo_adicionar_meses(data_atual, 1).isoformat()
    return (data_atual + timedelta(days=max(1, intervalo_dias))).isoformat()


def _criar_periodo_rotativo_db(
    conn: sqlite3.Connection,
    emprestimo: dict[str, Any],
    *,
    vencimento: str,
    numero_parcela: int,
    observacoes: str = "",
) -> int:
    principal = _emprestimo_decimal(emprestimo.get("principal_atual") or emprestimo.get("valor_principal"))
    taxa = _emprestimo_decimal(emprestimo.get("taxa_juros_percentual"))
    juros = _calcular_juros_periodo_rotativo(principal, taxa)
    agora = agora_empresa().isoformat(timespec="seconds")
    cursor = conn.execute(
        """
        INSERT INTO emprestimo_parcelas (
            empresa_id, emprestimo_id, numero_parcela, vencimento,
            valor_principal, valor_juros, valor_tarifas, tipo_periodo,
            principal_base, juros_pago, amortizacao_principal,
            valor_previsto, valor_pago, saldo_parcela, status,
            observacoes, criado_em, atualizado_em
        ) VALUES (?, ?, ?, ?, ?, ?, '0,00', 'rotativo', ?, '0,00', '0,00',
                  ?, '0,00', ?, 'aberta', ?, ?, ?)
        """,
        (
            int(emprestimo["empresa_id"]),
            int(emprestimo["id"]),
            numero_parcela,
            vencimento,
            _emprestimo_moeda(principal),
            _emprestimo_moeda(juros),
            _emprestimo_moeda(principal),
            _emprestimo_moeda(juros),
            _emprestimo_moeda(juros),
            observacoes,
            agora,
            agora,
        ),
    )
    return int(cursor.lastrowid)


def _renovar_periodo_rotativo_db(
    conn: sqlite3.Connection,
    emprestimo_id: int,
    parcela_atual: dict[str, Any],
) -> int | None:
    emprestimo_row = conn.execute(
        "SELECT * FROM emprestimos WHERE id=? AND empresa_id=?",
        (emprestimo_id, empresa_logada_id()),
    ).fetchone()
    if emprestimo_row is None:
        return None
    emprestimo = dict(emprestimo_row)
    principal = _emprestimo_decimal(emprestimo.get("principal_atual"))
    if principal <= 0 or str(emprestimo.get("status")) in {"quitado", "cancelado"}:
        return None

    existente = conn.execute(
        """
        SELECT id FROM emprestimo_parcelas
        WHERE empresa_id=? AND emprestimo_id=? AND numero_parcela>?
          AND status NOT IN ('cancelada')
        ORDER BY numero_parcela LIMIT 1
        """,
        (
            empresa_logada_id(),
            emprestimo_id,
            int(parcela_atual.get("numero_parcela") or 0),
        ),
    ).fetchone()
    if existente:
        return int(existente["id"])

    novo_numero = int(parcela_atual.get("numero_parcela") or 0) + 1
    novo_vencimento = _proximo_vencimento_rotativo(
        str(parcela_atual.get("vencimento")),
        int(emprestimo.get("intervalo_dias") or 30),
    )
    novo_id = _criar_periodo_rotativo_db(
        conn,
        emprestimo,
        vencimento=novo_vencimento,
        numero_parcela=novo_numero,
        observacoes=f"Renovação automática do período {parcela_atual.get('numero_parcela')}.",
    )
    conn.execute(
        """
        UPDATE emprestimos
        SET primeira_parcela=?, quantidade_parcelas=?,
            valor_total=?, saldo_atual=?, atualizado_em=?
        WHERE id=? AND empresa_id=?
        """,
        (
            novo_vencimento,
            novo_numero,
            _emprestimo_moeda(principal + _calcular_juros_periodo_rotativo(
                principal,
                _emprestimo_decimal(emprestimo.get("taxa_juros_percentual")),
            )),
            _emprestimo_moeda(principal),
            agora_empresa().isoformat(timespec="seconds"),
            emprestimo_id,
            empresa_logada_id(),
        ),
    )
    _registrar_historico_emprestimo(
        conn,
        emprestimo_id,
        "renovacao_rotativa",
        (
            f"Principal de {_emprestimo_moeda(principal)} renovado para "
            f"{novo_vencimento}, com novo período de juros."
        ),
        parcela_id=novo_id,
        dados_novos={
            "principal": _emprestimo_moeda(principal),
            "vencimento": novo_vencimento,
            "periodo": novo_numero,
        },
    )
    return novo_id


def _registrar_historico_emprestimo(
    conn: sqlite3.Connection,
    emprestimo_id: int,
    tipo_evento: str,
    descricao: str,
    *,
    parcela_id: int | None = None,
    renegociacao_id: int | None = None,
    dados_anteriores: Any = None,
    dados_novos: Any = None,
) -> None:
    conn.execute(
        """
        INSERT INTO emprestimo_historico (
            empresa_id, emprestimo_id, parcela_id, renegociacao_id,
            tipo_evento, descricao, dados_anteriores, dados_novos,
            usuario_id, usuario_nome, criado_em
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """,
        (
            empresa_logada_id(),
            emprestimo_id,
            parcela_id,
            renegociacao_id,
            tipo_evento,
            descricao,
            json.dumps(dados_anteriores, ensure_ascii=False, default=str) if dados_anteriores is not None else None,
            json.dumps(dados_novos, ensure_ascii=False, default=str) if dados_novos is not None else None,
            usuario_logado_id(),
            session.get("usuario_nome") or "Administrador",
            agora_empresa().isoformat(timespec="seconds"),
        ),
    )


def atualizar_status_emprestimo_db(emprestimo_id: int, conn: sqlite3.Connection | None = None) -> None:
    conexao_propria = conn is None
    banco = conn or conectar_db()
    try:
        hoje = hoje_empresa().isoformat()
        emprestimo = banco.execute(
            "SELECT * FROM emprestimos WHERE id=? AND empresa_id=?",
            (emprestimo_id, empresa_logada_id()),
        ).fetchone()
        if not emprestimo or str(emprestimo["status"]) in {"cancelado", "renegociado"}:
            return

        modalidade = str(emprestimo["modalidade"] or "parcelado")
        rows = banco.execute(
            """
            SELECT status, vencimento, saldo_parcela
            FROM emprestimo_parcelas
            WHERE empresa_id=? AND emprestimo_id=? AND status!='cancelada'
            """,
            (empresa_logada_id(), emprestimo_id),
        ).fetchall()
        possui_vencida = any(
            str(row["status"]) != "paga"
            and str(row["vencimento"]) < hoje
            and _emprestimo_decimal(row["saldo_parcela"]) > 0
            for row in rows
        )

        if modalidade == "rotativo":
            principal = _emprestimo_decimal(emprestimo["principal_atual"])
            novo_status = "quitado" if principal <= 0 else ("atrasado" if possui_vencida else "ativo")
            saldo = principal
        else:
            saldo = sum((_emprestimo_decimal(row["saldo_parcela"]) for row in rows), Decimal("0.00"))
            novo_status = "quitado" if saldo <= 0 else ("atrasado" if possui_vencida else "ativo")

        quitado_em = agora_empresa().isoformat(timespec="seconds") if novo_status == "quitado" else None
        banco.execute(
            """
            UPDATE emprestimos
            SET saldo_atual=?, status=?, quitado_em=?, atualizado_em=?
            WHERE id=? AND empresa_id=?
            """,
            (
                _emprestimo_moeda(saldo),
                novo_status,
                quitado_em,
                agora_empresa().isoformat(timespec="seconds"),
                emprestimo_id,
                empresa_logada_id(),
            ),
        )
        banco.execute(
            """
            UPDATE emprestimo_parcelas
            SET status='vencida', atualizado_em=?
            WHERE empresa_id=? AND emprestimo_id=? AND status='aberta'
              AND vencimento<? AND saldo_parcela!='0,00'
            """,
            (agora_empresa().isoformat(timespec="seconds"), empresa_logada_id(), emprestimo_id, hoje),
        )
        if conexao_propria:
            banco.commit()
    finally:
        if conexao_propria:
            banco.close()



def _tipo_titulo_financeiro_emprestimo(tipo_emprestimo: Any) -> str:
    return "receber" if str(tipo_emprestimo or "").strip().lower() == "concedido" else "pagar"


def _status_titulo_financeiro_parcela_emprestimo(status_parcela: Any) -> str:
    status = str(status_parcela or "aberta").strip().lower()
    if status == "paga":
        return "pago"
    if status == "cancelada":
        return "cancelado"
    return "aberto"


def _documento_financeiro_parcela_emprestimo(numero_emprestimo: Any, numero_parcela: Any) -> str:
    try:
        parcela = int(numero_parcela or 0)
    except (TypeError, ValueError):
        parcela = 0
    return f"{str(numero_emprestimo or 'EMP').strip()}-P{parcela:03d}"


def _sincronizar_titulo_financeiro_parcela_emprestimo_db(
    conn: sqlite3.Connection,
    emprestimo: dict[str, Any],
    parcela: dict[str, Any],
) -> int | None:
    if not bool(int(emprestimo.get("gerar_financeiro") or 0)):
        return None
    if not configuracao_bool("emprestimos", "gerar_financeiro_automaticamente", True):
        return None

    empresa_id = int(emprestimo["empresa_id"])
    emprestimo_id = int(emprestimo["id"])
    parcela_id = int(parcela["id"])
    documento = _documento_financeiro_parcela_emprestimo(
        emprestimo.get("numero"),
        parcela.get("numero_parcela"),
    )
    tipo_titulo = _tipo_titulo_financeiro_emprestimo(emprestimo.get("tipo"))
    status_titulo = _status_titulo_financeiro_parcela_emprestimo(parcela.get("status"))
    data_pagamento = (
        str(parcela.get("data_pagamento") or "").strip()
        if status_titulo == "pago"
        else ""
    )
    categoria = (
        "Empréstimos concedidos"
        if tipo_titulo == "receber"
        else "Empréstimos recebidos"
    )
    descricao = (
        f"Parcela {parcela.get('numero_parcela')} do empréstimo "
        f"{emprestimo.get('numero')} - {emprestimo.get('titulo')}"
    )
    observacoes = (
        f"Gerado automaticamente pelo módulo Empréstimos. "
        f"Parcela interna #{parcela_id}."
    )

    titulo = None
    titulo_id = parcela.get("lancamento_financeiro_id")
    if titulo_id:
        titulo = conn.execute(
            """
            SELECT *
            FROM financeiro_titulos
            WHERE id=? AND empresa_id=?
            """,
            (int(titulo_id), empresa_id),
        ).fetchone()

    if titulo is None:
        titulo = conn.execute(
            """
            SELECT *
            FROM financeiro_titulos
            WHERE empresa_id=?
              AND origem='emprestimo'
              AND origem_id=?
              AND documento=?
            ORDER BY id
            LIMIT 1
            """,
            (empresa_id, emprestimo_id, documento),
        ).fetchone()

    agora = agora_empresa().isoformat(timespec="seconds")
    if titulo is None:
        cursor = conn.execute(
            """
            INSERT INTO financeiro_titulos (
                empresa_id, tipo, descricao, pessoa, categoria,
                centro_custo_id, atividade_financeira_id,
                origem, origem_id, documento, data_emissao,
                data_vencimento, data_pagamento, valor,
                forma_pagamento, status, observacoes
            ) VALUES (?, ?, ?, ?, ?, ?, NULL, 'emprestimo', ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_id,
                tipo_titulo,
                descricao,
                str(emprestimo.get("parte_nome") or "").strip(),
                categoria,
                emprestimo.get("centro_custo_id") or None,
                emprestimo_id,
                documento,
                str(emprestimo.get("data_contrato") or hoje_empresa().isoformat()),
                str(parcela.get("vencimento") or ""),
                data_pagamento,
                str(parcela.get("valor_previsto") or "0,00"),
                str(parcela.get("forma_pagamento") or emprestimo.get("forma_pagamento") or "").strip(),
                status_titulo,
                observacoes,
            ),
        )
        titulo_id = int(cursor.lastrowid)
        registrar_historico_financeiro_titulo_db(
            titulo_id,
            "criado",
            f"Título criado automaticamente para a parcela {parcela.get('numero_parcela')} do empréstimo {emprestimo.get('numero')}.",
            dados_novos={
                "tipo": tipo_titulo,
                "descricao": descricao,
                "pessoa": emprestimo.get("parte_nome"),
                "categoria": categoria,
                "origem": "emprestimo",
                "origem_id": emprestimo_id,
                "documento": documento,
                "data_emissao": emprestimo.get("data_contrato"),
                "data_vencimento": parcela.get("vencimento"),
                "data_pagamento": data_pagamento,
                "valor": parcela.get("valor_previsto"),
                "forma_pagamento": parcela.get("forma_pagamento") or emprestimo.get("forma_pagamento"),
                "status": status_titulo,
                "observacoes": observacoes,
            },
            conn=conn,
        )
    else:
        titulo_atual = dict(titulo)
        titulo_id = int(titulo_atual["id"])

        # Um título já pago no Financeiro não é reaberto por uma sincronização de leitura.
        if str(titulo_atual.get("status") or "") == "pago" and status_titulo != "pago":
            status_titulo = "pago"
            data_pagamento = str(titulo_atual.get("data_pagamento") or "").strip()

        conn.execute(
            """
            UPDATE financeiro_titulos
            SET tipo=?, descricao=?, pessoa=?, categoria=?,
                centro_custo_id=?, origem='emprestimo', origem_id=?,
                documento=?, data_emissao=?, data_vencimento=?,
                data_pagamento=?, valor=?, forma_pagamento=?,
                status=?, observacoes=?
            WHERE id=? AND empresa_id=?
            """,
            (
                tipo_titulo,
                descricao,
                str(emprestimo.get("parte_nome") or "").strip(),
                categoria,
                emprestimo.get("centro_custo_id") or None,
                emprestimo_id,
                documento,
                str(emprestimo.get("data_contrato") or hoje_empresa().isoformat()),
                str(parcela.get("vencimento") or ""),
                data_pagamento,
                str(parcela.get("valor_previsto") or "0,00"),
                str(parcela.get("forma_pagamento") or emprestimo.get("forma_pagamento") or "").strip(),
                status_titulo,
                observacoes,
                titulo_id,
                empresa_id,
            ),
        )

    conn.execute(
        """
        UPDATE emprestimo_parcelas
        SET lancamento_financeiro_id=?, atualizado_em=?
        WHERE id=? AND empresa_id=?
        """,
        (titulo_id, agora, parcela_id, empresa_id),
    )
    return int(titulo_id)


def sincronizar_financeiro_emprestimo_db(
    emprestimo_id: int,
    conn: sqlite3.Connection | None = None,
) -> None:
    conexao_propria = conn is None
    banco = conn or conectar_db()
    try:
        emprestimo_row = banco.execute(
            "SELECT * FROM emprestimos WHERE id=? AND empresa_id=?",
            (emprestimo_id, empresa_logada_id()),
        ).fetchone()
        if emprestimo_row is None:
            return
        emprestimo = dict(emprestimo_row)
        parcelas = banco.execute(
            """
            SELECT *
            FROM emprestimo_parcelas
            WHERE emprestimo_id=? AND empresa_id=?
            ORDER BY numero_parcela, id
            """,
            (emprestimo_id, empresa_logada_id()),
        ).fetchall()
        for parcela_row in parcelas:
            _sincronizar_titulo_financeiro_parcela_emprestimo_db(
                banco,
                emprestimo,
                dict(parcela_row),
            )
        if conexao_propria:
            banco.commit()
    finally:
        if conexao_propria:
            banco.close()


def sincronizar_financeiro_emprestimos_empresa_db() -> None:
    with conectar_db() as conn:
        ids = [
            int(row["id"])
            for row in conn.execute(
                """
                SELECT id
                FROM emprestimos
                WHERE empresa_id=?
                  AND gerar_financeiro=1
                ORDER BY id
                """,
                (empresa_logada_id(),),
            ).fetchall()
        ]
        for emprestimo_id in ids:
            sincronizar_financeiro_emprestimo_db(emprestimo_id, conn=conn)
        conn.commit()


def _sincronizar_parcela_emprestimo_por_titulo_financeiro_db(
    titulo_id: int,
    status_financeiro: str,
    data_pagamento: str = "",
) -> None:
    status = str(status_financeiro or "").strip().lower()
    if status not in {"pago", "cancelado"}:
        return

    emprestimo_id: int | None = None
    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT p.*, e.numero AS emprestimo_numero
            FROM emprestimo_parcelas p
            JOIN emprestimos e
              ON e.id=p.emprestimo_id
             AND e.empresa_id=p.empresa_id
            WHERE p.empresa_id=?
              AND p.lancamento_financeiro_id=?
            LIMIT 1
            """,
            (empresa_logada_id(), titulo_id),
        ).fetchone()
        if row is None:
            return

        parcela = dict(row)
        emprestimo_id = int(parcela["emprestimo_id"])
        agora = agora_empresa().isoformat(timespec="seconds")

        if status == "pago":
            if parcela.get("status") == "cancelada":
                return
            novo_status = "paga"
            valor_pago = str(parcela.get("valor_previsto") or "0,00")
            saldo = "0,00"
            pagamento = _emprestimo_data_iso(
                data_pagamento,
                hoje_empresa().isoformat(),
            )
            descricao = (
                f"Parcela {parcela.get('numero_parcela')} baixada automaticamente "
                f"pelo título financeiro #{titulo_id}."
            )
            conn.execute(
                """
                UPDATE emprestimo_parcelas
                SET valor_pago=?, saldo_parcela=?, status='paga',
                    data_pagamento=?, atualizado_em=?
                WHERE id=? AND empresa_id=?
                """,
                (
                    valor_pago,
                    saldo,
                    pagamento,
                    agora,
                    int(parcela["id"]),
                    empresa_logada_id(),
                ),
            )
        else:
            if parcela.get("status") == "paga":
                return
            novo_status = "cancelada"
            descricao = (
                f"Parcela {parcela.get('numero_parcela')} cancelada automaticamente "
                f"pelo título financeiro #{titulo_id}."
            )
            conn.execute(
                """
                UPDATE emprestimo_parcelas
                SET status='cancelada', atualizado_em=?
                WHERE id=? AND empresa_id=?
                """,
                (agora, int(parcela["id"]), empresa_logada_id()),
            )

        emprestimo_modalidade = conn.execute(
            "SELECT modalidade FROM emprestimos WHERE id=? AND empresa_id=?",
            (emprestimo_id, empresa_logada_id()),
        ).fetchone()
        if (
            status == "pago"
            and emprestimo_modalidade
            and str(emprestimo_modalidade["modalidade"] or "parcelado") == "rotativo"
        ):
            conn.execute(
                """
                UPDATE emprestimo_parcelas
                SET juros_pago=valor_previsto, amortizacao_principal='0,00'
                WHERE id=? AND empresa_id=?
                """,
                (int(parcela["id"]), empresa_logada_id()),
            )
            juros_total_row = conn.execute(
                "SELECT total_juros_recebidos FROM emprestimos WHERE id=? AND empresa_id=?",
                (emprestimo_id, empresa_logada_id()),
            ).fetchone()
            juros_total = _emprestimo_decimal(juros_total_row["total_juros_recebidos"]) + _emprestimo_decimal(parcela["valor_previsto"])
            conn.execute(
                """
                UPDATE emprestimos
                SET total_juros_recebidos=?, atualizado_em=?
                WHERE id=? AND empresa_id=?
                """,
                (_emprestimo_moeda(juros_total), agora, emprestimo_id, empresa_logada_id()),
            )
            _renovar_periodo_rotativo_db(conn, emprestimo_id, parcela)

        _registrar_historico_emprestimo(
            conn,
            emprestimo_id,
            "sincronizacao_financeiro",
            descricao,
            parcela_id=int(parcela["id"]),
            dados_anteriores={
                "status": parcela.get("status"),
                "saldo": parcela.get("saldo_parcela"),
            },
            dados_novos={
                "status": novo_status,
                "titulo_financeiro_id": titulo_id,
            },
        )
        conn.commit()

    if emprestimo_id is not None:
        atualizar_status_emprestimo_db(emprestimo_id)

def criar_emprestimo_db(dados: dict[str, Any]) -> int:
    tipo = str(dados.get("tipo") or "recebido").strip().lower()
    if tipo not in EMPRESTIMO_TIPOS_CODIGOS:
        raise ValueError("Tipo de empréstimo inválido.")

    modalidade = str(dados.get("modalidade") or "parcelado").strip().lower()
    if modalidade not in EMPRESTIMO_MODALIDADES_CODIGOS:
        raise ValueError("Modalidade de empréstimo inválida.")

    titulo = str(dados.get("titulo") or "").strip()
    parte_nome = str(dados.get("parte_nome") or "").strip()
    if not titulo:
        raise ValueError("Informe o título do empréstimo.")
    if not parte_nome:
        raise ValueError("Informe o credor ou devedor.")

    principal = _emprestimo_decimal(dados.get("valor_principal"))
    if principal <= 0:
        raise ValueError("O valor principal precisa ser maior que zero.")

    primeira_texto = _emprestimo_data_iso(dados.get("primeira_parcela"))
    if not primeira_texto:
        raise ValueError("Informe a data do primeiro vencimento.")
    primeira_data = date.fromisoformat(primeira_texto)

    taxa = _emprestimo_decimal(dados.get("taxa_juros_percentual"))
    if modalidade == "rotativo" and taxa <= 0:
        raise ValueError("Informe uma taxa de juros maior que zero para o empréstimo rotativo.")

    tarifas = _emprestimo_decimal(dados.get("tarifas"))
    iof = _emprestimo_decimal(dados.get("iof"))
    intervalo = _emprestimo_inteiro_positivo(dados.get("intervalo_dias"), 30)
    sistema = str(dados.get("sistema_amortizacao") or "simples").strip().lower()
    permitir_amortizacao = bool(dados.get("permitir_amortizacao", True))

    if modalidade == "rotativo":
        quantidade = 1
        juros_periodo = _calcular_juros_periodo_rotativo(principal, taxa)
        valor_total = principal + juros_periodo + tarifas + iof
        parcelas = []
    else:
        quantidade = _emprestimo_inteiro_positivo(dados.get("quantidade_parcelas"), 1)
        maximo = int(valor_configuracao_modulo("emprestimos", "maximo_parcelas", 120) or 120)
        if quantidade > maximo:
            raise ValueError(f"A quantidade máxima configurada é {maximo} parcelas.")
        parcelas = calcular_plano_emprestimo(
            principal,
            taxa,
            quantidade,
            sistema,
            primeira_data,
            intervalo,
            tarifas,
            iof,
        )
        valor_total = sum((item["total"] for item in parcelas), Decimal("0.00"))

    agora = agora_empresa().isoformat(timespec="seconds")
    with conectar_db() as conn:
        numero = gerar_numero_emprestimo_db(conn)
        cursor = conn.execute(
            """
            INSERT INTO emprestimos (
                empresa_id, numero, tipo, modalidade, status, titulo, parte_tipo, parte_id,
                parte_nome, parte_documento, parte_email, parte_telefone, banco,
                conta_financeira, centro_custo_id, centro_custo, data_contrato,
                data_liberacao, primeira_parcela, quantidade_parcelas, intervalo_dias,
                sistema_amortizacao, valor_principal, principal_atual,
                total_juros_recebidos, total_amortizado, permitir_amortizacao,
                taxa_juros_percentual, tipo_juros, multa_percentual,
                juros_atraso_mes_percentual, tarifas, iof, valor_total, saldo_atual,
                forma_pagamento, garantia, fiador, observacoes, gerar_financeiro,
                criado_por_usuario_id, criado_por_nome, criado_em, atualizado_em
            ) VALUES (
                ?, ?, ?, ?, 'ativo', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?,
                ?, ?, '0,00', '0,00', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?
            )
            """,
            (
                empresa_logada_id(), numero, tipo, modalidade, titulo,
                str(dados.get("parte_tipo") or "outro").strip(), dados.get("parte_id"),
                parte_nome, str(dados.get("parte_documento") or "").strip(),
                str(dados.get("parte_email") or "").strip(),
                str(dados.get("parte_telefone") or "").strip(),
                str(dados.get("banco") or "").strip(),
                str(dados.get("conta_financeira") or "").strip(),
                dados.get("centro_custo_id"), str(dados.get("centro_custo") or "").strip(),
                _emprestimo_data_iso(dados.get("data_contrato"), hoje_empresa().isoformat()),
                _emprestimo_data_iso(dados.get("data_liberacao")), primeira_texto,
                quantidade, intervalo, sistema, _emprestimo_moeda(principal),
                _emprestimo_moeda(principal), 1 if permitir_amortizacao else 0,
                _emprestimo_moeda(taxa), str(dados.get("tipo_juros") or "simples").strip(),
                _emprestimo_moeda(dados.get("multa_percentual")),
                _emprestimo_moeda(dados.get("juros_atraso_mes_percentual")),
                _emprestimo_moeda(tarifas), _emprestimo_moeda(iof),
                _emprestimo_moeda(valor_total),
                _emprestimo_moeda(principal if modalidade == "rotativo" else valor_total),
                str(dados.get("forma_pagamento") or "").strip(),
                str(dados.get("garantia") or "").strip(),
                str(dados.get("fiador") or "").strip(),
                str(dados.get("observacoes") or "").strip(),
                1 if dados.get("gerar_financeiro", True) else 0,
                usuario_logado_id(), session.get("usuario_nome") or "Administrador",
                agora, agora,
            ),
        )
        emprestimo_id = int(cursor.lastrowid)

        if modalidade == "rotativo":
            emprestimo_row = conn.execute(
                "SELECT * FROM emprestimos WHERE id=? AND empresa_id=?",
                (emprestimo_id, empresa_logada_id()),
            ).fetchone()
            _criar_periodo_rotativo_db(
                conn,
                dict(emprestimo_row),
                vencimento=primeira_texto,
                numero_parcela=1,
                observacoes="Primeiro período de juros do contrato rotativo.",
            )
            descricao_criacao = (
                f"Empréstimo rotativo {numero} criado com principal de "
                f"{_emprestimo_moeda(principal)} e juros de {_emprestimo_moeda(taxa)}% por período."
            )
        else:
            for item in parcelas:
                conn.execute(
                    """
                    INSERT INTO emprestimo_parcelas (
                        empresa_id, emprestimo_id, numero_parcela, vencimento,
                        valor_principal, valor_juros, valor_tarifas, tipo_periodo,
                        principal_base, valor_previsto, valor_pago, saldo_parcela,
                        status, criado_em, atualizado_em
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, 'parcelado', ?, ?, '0,00', ?, 'aberta', ?, ?)
                    """,
                    (
                        empresa_logada_id(), emprestimo_id, item["numero"], item["vencimento"],
                        _emprestimo_moeda(item["principal"]), _emprestimo_moeda(item["juros"]),
                        _emprestimo_moeda(item["tarifas"]), _emprestimo_moeda(principal),
                        _emprestimo_moeda(item["total"]), _emprestimo_moeda(item["total"]),
                        agora, agora,
                    ),
                )
            descricao_criacao = f"Empréstimo {numero} criado com {quantidade} parcela(s)."

        _registrar_historico_emprestimo(
            conn, emprestimo_id, "criacao", descricao_criacao,
            dados_novos={
                "numero": numero, "tipo": tipo, "modalidade": modalidade,
                "valor_total": _emprestimo_moeda(valor_total),
            },
        )
        sincronizar_financeiro_emprestimo_db(emprestimo_id, conn=conn)
        conn.commit()

    return emprestimo_id


def buscar_emprestimo_db(emprestimo_id: int) -> dict[str, Any] | None:
    atualizar_status_emprestimo_db(emprestimo_id)
    sincronizar_financeiro_emprestimo_db(emprestimo_id)
    with conectar_db() as conn:
        row = conn.execute(
            "SELECT * FROM emprestimos WHERE id=? AND empresa_id=?",
            (emprestimo_id, empresa_logada_id()),
        ).fetchone()
        if row is None:
            return None
        emprestimo = dict(row)
        emprestimo["parcelas"] = [
            dict(item)
            for item in conn.execute(
                """
                SELECT * FROM emprestimo_parcelas
                WHERE emprestimo_id=? AND empresa_id=?
                ORDER BY numero_parcela, id
                """,
                (emprestimo_id, empresa_logada_id()),
            ).fetchall()
        ]
        emprestimo["renegociacoes"] = [
            dict(item)
            for item in conn.execute(
                """
                SELECT * FROM emprestimo_renegociacoes
                WHERE emprestimo_id=? AND empresa_id=?
                ORDER BY id DESC
                """,
                (emprestimo_id, empresa_logada_id()),
            ).fetchall()
        ]
        emprestimo["historico"] = [
            dict(item)
            for item in conn.execute(
                """
                SELECT * FROM emprestimo_historico
                WHERE emprestimo_id=? AND empresa_id=?
                ORDER BY id DESC
                LIMIT 200
                """,
                (emprestimo_id, empresa_logada_id()),
            ).fetchall()
        ]
        return emprestimo


def listar_emprestimos_db() -> list[dict[str, Any]]:
    sincronizar_financeiro_emprestimos_empresa_db()
    busca = str(request.args.get("busca") or "").strip()
    status = str(request.args.get("status") or "").strip()
    tipo = str(request.args.get("tipo") or "").strip()
    parametros: list[Any] = [empresa_logada_id()]
    filtros = ["empresa_id=?"]
    if busca:
        filtros.append("(numero LIKE ? OR titulo LIKE ? OR parte_nome LIKE ?)")
        termo = f"%{busca}%"
        parametros.extend([termo, termo, termo])
    if status in EMPRESTIMO_STATUS_CODIGOS:
        filtros.append("status=?")
        parametros.append(status)
    if tipo in EMPRESTIMO_TIPOS_CODIGOS:
        filtros.append("tipo=?")
        parametros.append(tipo)

    with conectar_db() as conn:
        ids = [
            int(row["id"])
            for row in conn.execute(
                f"SELECT id FROM emprestimos WHERE {' AND '.join(filtros)} ORDER BY id DESC",
                parametros,
            ).fetchall()
        ]
    for emprestimo_id in ids:
        atualizar_status_emprestimo_db(emprestimo_id)

    with conectar_db() as conn:
        return [
            dict(row)
            for row in conn.execute(
                f"SELECT * FROM emprestimos WHERE {' AND '.join(filtros)} ORDER BY id DESC",
                parametros,
            ).fetchall()
        ]


def listar_parcelas_emprestimos_db() -> list[dict[str, Any]]:
    status = str(request.args.get("status") or "").strip()
    data_inicio = _emprestimo_data_iso(request.args.get("data_inicio"))
    data_fim = _emprestimo_data_iso(request.args.get("data_fim"))
    parametros: list[Any] = [empresa_logada_id()]
    filtros = ["p.empresa_id=?"]
    if status:
        filtros.append("p.status=?")
        parametros.append(status)
    if data_inicio:
        filtros.append("p.vencimento>=?")
        parametros.append(data_inicio)
    if data_fim:
        filtros.append("p.vencimento<=?")
        parametros.append(data_fim)

    with conectar_db() as conn:
        return [
            dict(row)
            for row in conn.execute(
                f"""
                SELECT p.*, e.numero AS emprestimo_numero, e.titulo AS emprestimo_titulo,
                       e.tipo AS emprestimo_tipo, e.parte_nome
                FROM emprestimo_parcelas p
                JOIN emprestimos e ON e.id=p.emprestimo_id AND e.empresa_id=p.empresa_id
                WHERE {' AND '.join(filtros)}
                ORDER BY p.vencimento, p.id
                """,
                parametros,
            ).fetchall()
        ]


def montar_dashboard_emprestimos_db() -> dict[str, Any]:
    emprestimos = listar_emprestimos_db()
    parcelas = listar_parcelas_emprestimos_db()
    hoje = hoje_empresa().isoformat()
    limite = (hoje_empresa() + timedelta(days=30)).isoformat()

    def soma_emprestimos(tipo: str, campo: str) -> Decimal:
        return sum(
            (_emprestimo_decimal(item.get(campo)) for item in emprestimos if item.get("tipo") == tipo and item.get("status") != "cancelado"),
            Decimal("0.00"),
        )

    saldo_recebido = soma_emprestimos("recebido", "saldo_atual")
    saldo_concedido = soma_emprestimos("concedido", "saldo_atual")
    vencidas = [item for item in parcelas if item.get("status") in {"vencida", "aberta", "parcial"} and str(item.get("vencimento")) < hoje]
    proximas = [item for item in parcelas if item.get("status") in {"aberta", "parcial"} and hoje <= str(item.get("vencimento")) <= limite]

    return {
        "total_tomado": _emprestimo_moeda(soma_emprestimos("recebido", "valor_principal")),
        "total_emprestado": _emprestimo_moeda(soma_emprestimos("concedido", "valor_principal")),
        "saldo_devedor": _emprestimo_moeda(saldo_recebido),
        "saldo_a_receber": _emprestimo_moeda(saldo_concedido),
        "parcelas_vencidas": len(vencidas),
        "valor_vencido": _emprestimo_moeda(sum((_emprestimo_decimal(item.get("saldo_parcela")) for item in vencidas), Decimal("0.00"))),
        "parcelas_proximos_30_dias": len(proximas),
        "valor_proximos_30_dias": _emprestimo_moeda(sum((_emprestimo_decimal(item.get("saldo_parcela")) for item in proximas), Decimal("0.00"))),
        "ativos": sum(1 for item in emprestimos if item.get("status") in {"ativo", "atrasado"}),
        "quitados": sum(1 for item in emprestimos if item.get("status") == "quitado"),
        "recentes": emprestimos[:10],
        "proximas_parcelas": proximas[:10],
    }


def baixar_parcela_emprestimo_db(parcela_id: int, dados: dict[str, Any]) -> tuple[bool, str, int | None]:
    valor_baixa = _emprestimo_decimal(dados.get("valor_pago"))
    if valor_baixa <= 0:
        return False, "Informe um valor de baixa maior que zero.", None

    with conectar_db() as conn:
        row = conn.execute(
            """
            SELECT p.*, e.numero AS emprestimo_numero, e.modalidade,
                   e.principal_atual, e.taxa_juros_percentual,
                   e.total_juros_recebidos, e.total_amortizado,
                   e.permitir_amortizacao, e.intervalo_dias, e.status AS emprestimo_status
            FROM emprestimo_parcelas p
            JOIN emprestimos e ON e.id=p.emprestimo_id AND e.empresa_id=p.empresa_id
            WHERE p.id=? AND p.empresa_id=?
            """,
            (parcela_id, empresa_logada_id()),
        ).fetchone()
        if row is None:
            return False, "Parcela não encontrada.", None
        parcela = dict(row)
        emprestimo_id = int(parcela["emprestimo_id"])
        if parcela["status"] in {"paga", "cancelada"}:
            return False, "Esta parcela não pode receber nova baixa.", emprestimo_id

        if str(parcela.get("modalidade") or "parcelado") != "rotativo":
            saldo = _emprestimo_decimal(parcela["saldo_parcela"])
            if valor_baixa > saldo:
                return False, f"O valor informado é maior que o saldo da parcela ({_emprestimo_moeda(saldo)}).", emprestimo_id
            if valor_baixa < saldo and not configuracao_bool("emprestimos", "permitir_baixa_parcial", True):
                return False, "A baixa parcial está desativada nas configurações.", emprestimo_id

            pago_anterior = _emprestimo_decimal(parcela["valor_pago"])
            novo_pago = pago_anterior + valor_baixa
            novo_saldo = saldo - valor_baixa
            novo_status = "paga" if novo_saldo <= 0 else "parcial"
            agora = agora_empresa().isoformat(timespec="seconds")
            conn.execute(
                """
                UPDATE emprestimo_parcelas
                SET valor_pago=?, saldo_parcela=?, status=?, data_pagamento=?,
                    forma_pagamento=?, conta_financeira=?, observacoes=?, atualizado_em=?
                WHERE id=? AND empresa_id=?
                """,
                (
                    _emprestimo_moeda(novo_pago), _emprestimo_moeda(novo_saldo), novo_status,
                    _emprestimo_data_iso(dados.get("data_pagamento"), hoje_empresa().isoformat()),
                    str(dados.get("forma_pagamento") or "").strip(),
                    str(dados.get("conta_financeira") or "").strip(),
                    str(dados.get("observacoes") or "").strip(),
                    agora, parcela_id, empresa_logada_id(),
                ),
            )
            _registrar_historico_emprestimo(
                conn, emprestimo_id, "baixa_parcela",
                f"Baixa de {_emprestimo_moeda(valor_baixa)} na parcela {parcela['numero_parcela']}.",
                parcela_id=parcela_id,
                dados_anteriores={"saldo": parcela["saldo_parcela"], "status": parcela["status"]},
                dados_novos={"saldo": _emprestimo_moeda(novo_saldo), "status": novo_status},
            )
            sincronizar_financeiro_emprestimo_db(emprestimo_id, conn=conn)
            conn.commit()
            atualizar_status_emprestimo_db(emprestimo_id)
            return True, "Parcela baixada com sucesso.", emprestimo_id

        tipo_baixa = str(dados.get("tipo_baixa") or "somente_juros").strip().lower()
        if tipo_baixa not in {"somente_juros", "juros_amortizacao", "quitacao"}:
            return False, "Tipo de baixa rotativa inválido.", emprestimo_id

        principal = _emprestimo_decimal(parcela.get("principal_atual"))
        juros_saldo = _emprestimo_decimal(parcela.get("saldo_parcela"))
        if juros_saldo <= 0:
            return False, "Os juros deste período já estão quitados.", emprestimo_id

        if tipo_baixa == "somente_juros" and valor_baixa != juros_saldo:
            return False, f"Para pagar somente os juros, informe exatamente {_emprestimo_moeda(juros_saldo)}.", emprestimo_id
        if tipo_baixa in {"juros_amortizacao", "quitacao"} and valor_baixa < juros_saldo:
            return False, f"O pagamento deve cobrir primeiro os juros de {_emprestimo_moeda(juros_saldo)}.", emprestimo_id
        if tipo_baixa == "juros_amortizacao" and not bool(int(parcela.get("permitir_amortizacao") or 0)):
            return False, "A amortização parcial está desativada neste contrato.", emprestimo_id

        amortizacao = max(Decimal("0.00"), valor_baixa - juros_saldo)
        if tipo_baixa == "somente_juros":
            amortizacao = Decimal("0.00")
        if tipo_baixa == "quitacao":
            valor_necessario = juros_saldo + principal
            if valor_baixa != valor_necessario:
                return False, f"Para quitar, informe exatamente {_emprestimo_moeda(valor_necessario)}.", emprestimo_id
            amortizacao = principal
        if amortizacao > principal:
            return False, "A amortização não pode ser maior que o principal atual.", emprestimo_id

        novo_principal = principal - amortizacao
        juros_recebidos_total = _emprestimo_decimal(parcela.get("total_juros_recebidos")) + juros_saldo
        amortizado_total = _emprestimo_decimal(parcela.get("total_amortizado")) + amortizacao
        agora = agora_empresa().isoformat(timespec="seconds")
        data_pagamento = _emprestimo_data_iso(dados.get("data_pagamento"), hoje_empresa().isoformat())

        conn.execute(
            """
            UPDATE emprestimo_parcelas
            SET valor_pago=?, juros_pago=?, amortizacao_principal=?,
                saldo_parcela='0,00', status='paga', data_pagamento=?,
                forma_pagamento=?, conta_financeira=?, observacoes=?, atualizado_em=?
            WHERE id=? AND empresa_id=?
            """,
            (
                _emprestimo_moeda(valor_baixa), _emprestimo_moeda(juros_saldo),
                _emprestimo_moeda(amortizacao), data_pagamento,
                str(dados.get("forma_pagamento") or "").strip(),
                str(dados.get("conta_financeira") or "").strip(),
                str(dados.get("observacoes") or "").strip(),
                agora, parcela_id, empresa_logada_id(),
            ),
        )
        novo_status_emprestimo = "quitado" if novo_principal <= 0 else "ativo"
        conn.execute(
            """
            UPDATE emprestimos
            SET principal_atual=?, total_juros_recebidos=?, total_amortizado=?,
                saldo_atual=?, status=?, quitado_em=?, atualizado_em=?
            WHERE id=? AND empresa_id=?
            """,
            (
                _emprestimo_moeda(novo_principal),
                _emprestimo_moeda(juros_recebidos_total),
                _emprestimo_moeda(amortizado_total),
                _emprestimo_moeda(novo_principal),
                novo_status_emprestimo,
                agora if novo_status_emprestimo == "quitado" else None,
                agora, emprestimo_id, empresa_logada_id(),
            ),
        )
        descricao = (
            f"Período {parcela['numero_parcela']} baixado: juros "
            f"{_emprestimo_moeda(juros_saldo)}, amortização "
            f"{_emprestimo_moeda(amortizacao)} e principal restante "
            f"{_emprestimo_moeda(novo_principal)}."
        )
        _registrar_historico_emprestimo(
            conn, emprestimo_id, "baixa_rotativa", descricao,
            parcela_id=parcela_id,
            dados_anteriores={"principal": _emprestimo_moeda(principal)},
            dados_novos={
                "juros": _emprestimo_moeda(juros_saldo),
                "amortizacao": _emprestimo_moeda(amortizacao),
                "principal": _emprestimo_moeda(novo_principal),
                "tipo_baixa": tipo_baixa,
            },
        )
        if novo_principal > 0:
            _renovar_periodo_rotativo_db(conn, emprestimo_id, parcela)
        sincronizar_financeiro_emprestimo_db(emprestimo_id, conn=conn)
        conn.commit()

    atualizar_status_emprestimo_db(emprestimo_id)
    mensagem = "Juros recebidos e principal renovado."
    if amortizacao > 0 and novo_principal > 0:
        mensagem = "Juros recebidos, principal amortizado e próximo período gerado."
    if novo_principal <= 0:
        mensagem = "Empréstimo quitado com sucesso."
    return True, mensagem, emprestimo_id


def cancelar_emprestimo_db(emprestimo_id: int, motivo: str) -> tuple[bool, str]:
    motivo = str(motivo or "").strip()
    if not motivo:
        return False, "Informe o motivo do cancelamento."
    with conectar_db() as conn:
        row = conn.execute(
            "SELECT numero, status FROM emprestimos WHERE id=? AND empresa_id=?",
            (emprestimo_id, empresa_logada_id()),
        ).fetchone()
        if row is None:
            return False, "Empréstimo não encontrado."
        if row["status"] == "quitado":
            return False, "Um empréstimo quitado não pode ser cancelado."
        agora = agora_empresa().isoformat(timespec="seconds")
        conn.execute(
            """
            UPDATE emprestimos
            SET status='cancelado', cancelado_em=?, atualizado_em=?, observacoes=
                CASE WHEN observacoes IS NULL OR observacoes='' THEN ? ELSE observacoes || CHAR(10) || ? END
            WHERE id=? AND empresa_id=?
            """,
            (agora, agora, f"Cancelamento: {motivo}", f"Cancelamento: {motivo}", emprestimo_id, empresa_logada_id()),
        )
        conn.execute(
            """
            UPDATE emprestimo_parcelas
            SET status='cancelada', atualizado_em=?
            WHERE emprestimo_id=? AND empresa_id=? AND status!='paga'
            """,
            (agora, emprestimo_id, empresa_logada_id()),
        )
        _registrar_historico_emprestimo(
            conn, emprestimo_id, "cancelamento", f"Empréstimo {row['numero']} cancelado. Motivo: {motivo}"
        )
        sincronizar_financeiro_emprestimo_db(emprestimo_id, conn=conn)
        conn.commit()
    return True, "Empréstimo cancelado com sucesso."


def renegociar_emprestimo_db(emprestimo_id: int, dados: dict[str, Any]) -> tuple[bool, str]:
    if not configuracao_bool("emprestimos", "permitir_renegociacao", True):
        return False, "A renegociação está desativada nas configurações."
    motivo = str(dados.get("motivo") or "").strip()
    if configuracao_bool("emprestimos", "exigir_motivo_renegociacao", True) and not motivo:
        return False, "Informe o motivo da renegociação."

    with conectar_db() as conn:
        emprestimo = conn.execute(
            "SELECT * FROM emprestimos WHERE id=? AND empresa_id=?",
            (emprestimo_id, empresa_logada_id()),
        ).fetchone()
        if emprestimo is None:
            return False, "Empréstimo não encontrado."
        if emprestimo["status"] in {"quitado", "cancelado", "renegociado"}:
            return False, "Este empréstimo não pode ser renegociado."
        if str(emprestimo["modalidade"] or "parcelado") == "rotativo":
            return False, "No empréstimo rotativo, use a baixa com amortização ou quitação."

        parcelas_abertas = conn.execute(
            """
            SELECT * FROM emprestimo_parcelas
            WHERE emprestimo_id=? AND empresa_id=? AND status NOT IN ('paga','cancelada')
            """,
            (emprestimo_id, empresa_logada_id()),
        ).fetchall()
        saldo = sum((_emprestimo_decimal(row["saldo_parcela"]) for row in parcelas_abertas), Decimal("0.00"))
        quantidade = _emprestimo_inteiro_positivo(dados.get("quantidade_parcelas"), 1)
        taxa = _emprestimo_decimal(dados.get("taxa_juros_percentual"))
        primeira_texto = _emprestimo_data_iso(dados.get("primeira_parcela"))
        if not primeira_texto:
            return False, "Informe o primeiro vencimento da renegociação."
        sistema = str(dados.get("sistema_amortizacao") or emprestimo["sistema_amortizacao"] or "simples")
        intervalo = _emprestimo_inteiro_positivo(dados.get("intervalo_dias"), int(emprestimo["intervalo_dias"] or 30))
        novas = calcular_plano_emprestimo(
            saldo,
            taxa,
            quantidade,
            sistema,
            date.fromisoformat(primeira_texto),
            intervalo,
        )
        novo_total = sum((item["total"] for item in novas), Decimal("0.00"))
        agora = agora_empresa().isoformat(timespec="seconds")

        cursor = conn.execute(
            """
            INSERT INTO emprestimo_renegociacoes (
                empresa_id, emprestimo_id, motivo, data_renegociacao,
                saldo_anterior, novo_valor_total, nova_taxa_juros_percentual,
                nova_quantidade_parcelas, novo_primeiro_vencimento, observacoes,
                usuario_id, usuario_nome, criado_em
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                empresa_logada_id(), emprestimo_id, motivo, hoje_empresa().isoformat(),
                _emprestimo_moeda(saldo), _emprestimo_moeda(novo_total),
                _emprestimo_moeda(taxa), quantidade, primeira_texto,
                str(dados.get("observacoes") or "").strip(),
                usuario_logado_id(), session.get("usuario_nome") or "Administrador", agora,
            ),
        )
        renegociacao_id = int(cursor.lastrowid)

        conn.execute(
            """
            UPDATE emprestimo_parcelas
            SET status='cancelada', atualizado_em=?
            WHERE emprestimo_id=? AND empresa_id=? AND status NOT IN ('paga','cancelada')
            """,
            (agora, emprestimo_id, empresa_logada_id()),
        )

        maior_numero = conn.execute(
            "SELECT COALESCE(MAX(numero_parcela),0) AS maior FROM emprestimo_parcelas WHERE emprestimo_id=? AND empresa_id=?",
            (emprestimo_id, empresa_logada_id()),
        ).fetchone()["maior"]
        for item in novas:
            conn.execute(
                """
                INSERT INTO emprestimo_parcelas (
                    empresa_id, emprestimo_id, numero_parcela, vencimento,
                    valor_principal, valor_juros, valor_tarifas, valor_previsto,
                    valor_pago, saldo_parcela, status, observacoes, criado_em, atualizado_em
                ) VALUES (?, ?, ?, ?, ?, ?, '0,00', ?, '0,00', ?, 'aberta', ?, ?, ?)
                """,
                (
                    empresa_logada_id(), emprestimo_id, int(maior_numero) + item["numero"],
                    item["vencimento"], _emprestimo_moeda(item["principal"]),
                    _emprestimo_moeda(item["juros"]), _emprestimo_moeda(item["total"]),
                    _emprestimo_moeda(item["total"]), f"Gerada pela renegociação #{renegociacao_id}",
                    agora, agora,
                ),
            )

        conn.execute(
            """
            UPDATE emprestimos
            SET status='ativo', quantidade_parcelas=?, primeira_parcela=?,
                taxa_juros_percentual=?, sistema_amortizacao=?, intervalo_dias=?,
                valor_total=?, saldo_atual=?, atualizado_em=?
            WHERE id=? AND empresa_id=?
            """,
            (
                quantidade, primeira_texto, _emprestimo_moeda(taxa), sistema, intervalo,
                _emprestimo_moeda(novo_total), _emprestimo_moeda(novo_total),
                agora, emprestimo_id, empresa_logada_id(),
            ),
        )
        _registrar_historico_emprestimo(
            conn,
            emprestimo_id,
            "renegociacao",
            f"Empréstimo renegociado em {quantidade} nova(s) parcela(s).",
            renegociacao_id=renegociacao_id,
            dados_anteriores={"saldo": _emprestimo_moeda(saldo)},
            dados_novos={"novo_total": _emprestimo_moeda(novo_total), "parcelas": quantidade},
        )
        sincronizar_financeiro_emprestimo_db(emprestimo_id, conn=conn)
        conn.commit()

    return True, "Empréstimo renegociado com sucesso."


